INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51688, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "無垢", "is_correct": true, "explanation": "正解。「むく」。"}, {"text": "無口", "is_correct": false, "explanation": "「むくち」。「むく」が共通で一拍多い。"}, {"text": "麦茶", "is_correct": false, "explanation": "「むぎちゃ」。「む」が共通で後半が異なる。"}, {"text": "杭", "is_correct": false, "explanation": "「くい」。音の並びが近い。"}], "explanations": {"無垢": "正解。「むく」。", "無口": "「むくち」。「むく」が共通で一拍多い。", "麦茶": "「むぎちゃ」。「む」が共通で後半が異なる。", "杭": "「くい」。音の並びが近い。"}, "sentence_index": null, "correct_answer": "無垢"}, "level_3": {"options": [{"text": "無垢", "is_correct": true, "explanation": "正解。赤ちゃんの純粋さを表す。"}, {"text": "退屈", "is_correct": false, "explanation": "意味：赤ちゃんの性質として不自然。"}, {"text": "満員", "is_correct": false, "explanation": "意味：場所の混み具合の語で赤ちゃんの性質にならない。"}, {"text": "複雑", "is_correct": false, "explanation": "意味：赤ちゃんの性質を表さない。"}], "explanations": {"無垢": "正解。赤ちゃんの純粋さを表す。", "退屈": "意味：赤ちゃんの性質として不自然。", "満員": "意味：場所の混み具合の語で赤ちゃんの性質にならない。", "複雑": "意味：赤ちゃんの性質を表さない。"}, "sentence_index": 6, "correct_answer": "無垢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は無垢だ質問をした。", "explanation": "活用の誤り：名詞を修飾するときは「無垢な」とする。"}, {"text": "彼を無垢な質問をした。", "explanation": "助詞の誤り：質問する人は「は／が」で示す。"}, {"text": "彼は無垢さな質問をした。", "explanation": "形の誤り：「無垢さ」は名詞で「な」を付けて修飾できない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
