INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37775, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の物や人が集まってできた、一つのまとまり。", "primary_collocate": null, "pronunciation": "しゅうごう", "ipa": "ɕɯːɡoː", "syllable_count": 4, "sentences": [{"text": "建築を単なる機能の集合体ではなく、記号が織りなすテキストとして読み解く態度が、ポスト構造主義に基づく批評の核心です。", "target_word": "集合", "complexity_tier": "T3", "furigana": "けんちく しゅうごう", "sentence_source": "mined"}, {"text": "ワインという液体媒体において、テロワールは単なる気象・地質学的変数の集合体ではなく、地質学的記憶が液相内に結晶化した記号系として機能する。", "target_word": "集合", "complexity_tier": "T3", "furigana": "しゅうごう", "sentence_source": "mined"}, {"text": "町は人の集合でできている。", "target_word": "集合", "complexity_tier": "T3", "furigana": "まち ひと しゅうごう", "sentence_source": "generated"}, {"text": "このチームは個性の集合だ。", "target_word": "集合", "complexity_tier": "T3", "furigana": "しゅうごう", "sentence_source": "generated"}, {"text": "星の集合を星団と呼ぶ。", "target_word": "集合", "complexity_tier": "T3", "furigana": "ほし しゅうごう せいだん よ", "sentence_source": "generated"}, {"text": "細胞の集合が体を作っている。", "target_word": "集合", "complexity_tier": "T3", "furigana": "さいぼう しゅうごう からだ つく", "sentence_source": "generated"}, {"text": "森は木の集合だと言える。", "target_word": "集合", "complexity_tier": "T3", "furigana": "もり き しゅうごう い", "sentence_source": "generated"}, {"text": "数の集合について学んでいる。", "target_word": "集合", "complexity_tier": "T3", "furigana": "かず しゅうごう まな", "sentence_source": "generated"}, {"text": "意見の集合が一つの答えになる。", "target_word": "集合", "complexity_tier": "T3", "furigana": "いけん しゅうごう ひと こた", "sentence_source": "generated"}, {"text": "集合としての力は大きい。", "target_word": "集合", "complexity_tier": "T3", "furigana": "しゅうごう ちから おお", "sentence_source": "generated"}], "morphological_forms": [{"form": "集合体", "label": "派生"}, {"form": "集合する", "label": "派生"}, {"form": "集合的", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 多くの物が集まったまとまり", "co