INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36125, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある言葉や物事の意味・内容を、はっきりと決めて説明すること。また、その説明。", "primary_collocate": null, "pronunciation": "ていぎ", "ipa": "teːɡi", "syllable_count": 3, "sentences": [{"text": "結果として、建築は静的な物体ではなく、見る者によって絶えず意味が更新される開かれた場として再定義されるのです。", "target_word": "定義", "complexity_tier": "T3", "furigana": "けんちく ていぎ", "sentence_source": "mined"}, {"text": "かかる感覚的知見の蓄積は、単一品種を基準とした旧来の分類体系を相対化し、微細な区画ごとの個性を階層的に位置づけるアペラシオンの概念を、より厳密かつ動的なヒエラルキーへと昇華させ、ワインの価値評価基準そのものを哲学的かつ実践的に再定義しているのである。", "target_word": "定義", "complexity_tier": "T3", "furigana": "ていぎ", "sentence_source": "mined"}, {"text": "この言葉の定義を調べた。", "target_word": "定義", "complexity_tier": "T3", "furigana": "ことば ていぎ しら", "sentence_source": "generated"}, {"text": "先生が「友情」を定義した。", "target_word": "定義", "complexity_tier": "T3", "furigana": "せんせい ゆうじょう ていぎ", "sentence_source": "generated"}, {"text": "定義がはっきりしていない。", "target_word": "定義", "complexity_tier": "T3", "furigana": "ていぎ", "sentence_source": "generated"}, {"text": "辞書の定義はわかりやすい。", "target_word": "定義", "complexity_tier": "T3", "furigana": "じしょ ていぎ", "sentence_source": "generated"}, {"text": "幸せの定義は人によって違う。", "target_word": "定義", "complexity_tier": "T3", "furigana": "しあわ ていぎ ひと ちが", "sentence_source": "generated"}, {"text": "まず用語を定義しておこう。", "target_word": "定義", "complexity_tier": "T3", "furigana": "ようご ていぎ", "sentence_source": "generated"}, {"text": "その定義には反対です。", "target_word": "定義", "complexity_tier": "T3", "furigana": "ていぎ はんたい", "sentence_source": "generated"}, {"text": "定義を覚えてから問題を解く。", "target_word": "定義", "complexity_tier": "T3", "furigana": "ていぎ おぼ もんだい と", "sentence_source": "generated"}], "morphological_forms": [{"form": "定義する", "label": "派生"}, {"form": "再定義", "label": "派生"}, {"form": "定義づける", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 言葉の意味をはっきり決めた説明", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: アペラシオン (Zipf 1.01)']::text[], '2020269c-3d1b-437c-b05b-0392b6452fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
