INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51908, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "続いていたものが途中で途切れて、なくなること。終わること。", "primary_collocate": null, "pronunciation": "たえる", "ipa": "taeɾɯ", "syllable_count": 3, "sentences": [{"text": "結果として、建築は静的な物体ではなく、見る者によって絶えず意味が更新される開かれた場として再定義されるのです。", "target_word": "絶え", "complexity_tier": "T3", "furigana": "た", "sentence_source": "mined"}, {"text": "なぜならば、無数の主体が限られた情報に基づき絶えず適応を繰り返す過程で、意図せぬイノベーションやシステミック・リスクが突発的に顕現するからに他ならない。", "target_word": "絶え", "complexity_tier": "T3", "furigana": "た", "sentence_source": "mined"}, {"text": "村から人の声が絶えた。", "target_word": "絶え", "complexity_tier": "T3", "furigana": "むら ひと こえ た", "sentence_source": "generated"}, {"text": "彼の家は笑いが絶えない。", "target_word": "絶え", "complexity_tier": "T3", "furigana": "かれ いえ わら た", "sentence_source": "generated"}, {"text": "連絡が絶えて一年になる。", "target_word": "絶え", "complexity_tier": "T3", "furigana": "れんらく た いちねん", "sentence_source": "generated"}, {"text": "この町では事故が絶えない。", "target_word": "絶え", "complexity_tier": "T3", "furigana": "まち じこ た", "sentence_source": "generated"}, {"text": "その家の血筋が絶えた。", "target_word": "絶え", "complexity_tier": "T3", "furigana": "いえ ちすじ た", "sentence_source": "generated"}, {"text": "客足が絶えることはない。", "target_word": "絶える", "complexity_tier": "T3", "furigana": "きゃくあし た", "sentence_source": "generated"}, {"text": "山道から人の姿が絶えた。", "target_word": "絶え", "complexity_tier": "T3", "furigana": "やまみち ひと すがた た", "sentence_source": "generated"}, {"text": "通りから人通りが絶えた。", "target_word": "絶え", "complexity_tier": "T3", "furigana": "とお ひとどお た", "sentence_source": "generated"}], "morphological_forms": [{"form": "絶えた", "label": "活用"}, {"form": "絶えて", "label": "活用"}, {"form": "絶えない", "label": "活用"}, {"form": "絶えず", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 続いていたものが途切れてなくなる", "colloc