INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36085, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "心の中で、これからこうしようと考えている内容。", "primary_collocate": null, "pronunciation": "いと", "ipa": "ito", "syllable_count": 2, "sentences": [{"text": "この理論的基盤は、建物に込められた作者の意図や固定的な意味を脱構築し、その背後にある社会的な文脈や矛盾を浮き彫りにします。", "target_word": "意図", "complexity_tier": "T3", "furigana": "いと", "sentence_source": "mined"}, {"text": "なぜならば、無数の主体が限られた情報に基づき絶えず適応を繰り返す過程で、意図せぬイノベーションやシステミック・リスクが突発的に顕現するからに他ならない。", "target_word": "意図", "complexity_tier": "T3", "furigana": "いと", "sentence_source": "mined"}, {"text": "彼の意図がわからない。", "target_word": "意図", "complexity_tier": "T3", "furigana": "かれ いと", "sentence_source": "generated"}, {"text": "作者の意図を考えてみよう。", "target_word": "意図", "complexity_tier": "T3", "furigana": "さくしゃ いと かんが", "sentence_source": "generated"}, {"text": "その発言に悪い意図はない。", "target_word": "意図", "complexity_tier": "T3", "furigana": "はつげん わる いと", "sentence_source": "generated"}, {"text": "意図を正しく伝えたい。", "target_word": "意図", "complexity_tier": "T3", "furigana": "いと ただ つた", "sentence_source": "generated"}, {"text": "私の意図とは違う結果だ。", "target_word": "意図", "complexity_tier": "T3", "furigana": "わたし いと ちが けっか", "sentence_source": "generated"}, {"text": "先生は意図して質問した。", "target_word": "意図", "complexity_tier": "T3", "furigana": "せんせい いと しつもん", "sentence_source": "generated"}, {"text": "意図が伝わってうれしい。", "target_word": "意図", "complexity_tier": "T3", "furigana": "いと つた", "sentence_source": "generated"}, {"text": "この絵の意図は何だろう。", "target_word": "意図", "complexity_tier": "T3", "furigana": "え いと なん", "sentence_source": "generated"}], "morphological_forms": [{"form": "意図する", "label": "派生"}, {"form": "意図的", "label": "派生"}, {"form": "意図せず", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 何かをしようとする考え", "collocate_grounding": {"status": "no_source",