INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51708, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "家やビルなどの建物を設計・建設すること。", "primary_collocate": null, "pronunciation": "けんちく", "ipa": "keɲtɕikɯ", "syllable_count": 4, "sentences": [{"text": "建築を単なる機能の集合体ではなく、記号が織りなすテキストとして読み解く態度が、ポスト構造主義に基づく批評の核心です。", "target_word": "建築", "complexity_tier": "T3", "furigana": "けんちく", "sentence_source": "mined"}, {"text": "結果として、建築は静的な物体ではなく、見る者によって絶えず意味が更新される開かれた場として再定義されるのです。", "target_word": "建築", "complexity_tier": "T3", "furigana": "けんちく", "sentence_source": "mined"}, {"text": "この建設には、当時の建築工学の知恵が結集されています。", "target_word": "建築", "complexity_tier": "T3", "furigana": "けんちく", "sentence_source": "mined"}, {"text": "兄は大学で建築を学んでいる。", "target_word": "建築", "complexity_tier": "T3", "furigana": "あに だいがく けんちく まな", "sentence_source": "generated"}, {"text": "家の建築を工務店に頼んだ。", "target_word": "建築", "complexity_tier": "T3", "furigana": "いえ けんちく こうむてん たの", "sentence_source": "generated"}, {"text": "建築の仕事にあこがれている。", "target_word": "建築", "complexity_tier": "T3", "furigana": "けんちく しごと", "sentence_source": "generated"}, {"text": "新しい駅の建築が始まった。", "target_word": "建築", "complexity_tier": "T3", "furigana": "あたら えき けんちく はじ", "sentence_source": "generated"}, {"text": "ビルの建築が予定より遅れている。", "target_word": "建築", "complexity_tier": "T3", "furigana": "けんちく よてい おく", "sentence_source": "generated"}, {"text": "彼女は建築に興味がある。", "target_word": "建築", "complexity_tier": "T3", "furigana": "かのじょ けんちく きょうみ", "sentence_source": "generated"}, {"text": "建築には長い時間がかかる。", "target_word": "建築", "complexity_tier": "T3", "furigana": "けんちく なが じかん", "sentence_source": "generated"}], "morphological_forms": [{"form": "建築家", "label": "派生"}, {"form": "建築物", "label": "派生"}, {"form": "建築する", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 建物を設計し建てること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2020269c-3d1b-437c-b05b-0392b6452fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37775, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "集合", "is_correct": true, "explanation": "正しい表記。"}, {"text": "就航", "is_correct": false, "explanation": "しゅうこう。「ご」が清音「こ」になる清濁の違い。"}, {"text": "照合", "is_correct": false, "explanation": "しょうごう。第一モーラ「しゅ」が「しょ」になる一モーラ差。"}, {"text": "終業", "is_correct": false, "explanation": "しゅうぎょう。「ご」が「ぎょ」になる一モーラ差。"}, {"text": "酒豪", "is_correct": false, "explanation": "しゅごう。「しゅう」の長音がない長短の違い。"}], "explanations": {"集合": "正しい表記。", "就航": "しゅうこう。「ご」が清音「こ」になる清濁の違い。", "照合": "しょうごう。第一モーラ「しゅ」が「しょ」になる一モーラ差。", "終業": "しゅうぎょう。「ご」が「ぎょ」になる一モーラ差。", "酒豪": "しゅごう。「しゅう」の長音がない長短の違い。"}, "sentence_index": null, "correct_answer": "集合"}, "level_3": {"options": [{"text": "集合", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "時間", "is_correct": false, "explanation": "意味：「機能の時間体」という語はなく、まとまりを表さない。"}, {"text": "気分", "is_correct": false, "explanation": "意味：気持ちを表す語で、まとまりの意味にならない。"}, {"text": "速度", "is_correct": false, "explanation": "連語：「速度体」とは言わず、周囲の語と結びつかない。"}], "explanations": {"集合": "文脈に合う正しい語。", "時間": "意味：「機能の時間体」という語はなく、まとまりを表さない。", "気分": "意味：気持ちを表す語で、まとまりの意味にならない。", "速度": "連語：「速度体」とは言わず、周囲の語と結びつかない。"}, "sentence_index": 0, "correct_answer": "集合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このチームは三冊の個性の集合だ。", "explanation": "助数詞の誤り：個性の集まりを「冊」で数えることはできない。"}, {"text": "このチームは個性を集合だ。", "explanation": "助詞の混同：「集合」を修飾するのは「の」で、「を」では文が成り立たない。"}, {"text": "このチームは集合だ個性の。", "explanation": "語順の誤り：「個性の」は「集合」の前に置く。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0835a5b8-0c2b-475e-a81f-6b8c4b182eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validat