INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51908, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "絶える", "is_correct": true, "explanation": "正しい表記。"}, {"text": "食べる", "is_correct": false, "explanation": "たべる。「え」が「べ」になる一モーラ差。"}, {"text": "貯める", "is_correct": false, "explanation": "ためる。「え」が「め」になる一モーラ差。"}, {"text": "帰る", "is_correct": false, "explanation": "かえる。「た」が「か」になる一モーラ差。"}, {"text": "冴える", "is_correct": false, "explanation": "さえる。「た」が「さ」になる一モーラ差。"}], "explanations": {"絶える": "正しい表記。", "食べる": "たべる。「え」が「べ」になる一モーラ差。", "貯める": "ためる。「え」が「め」になる一モーラ差。", "帰る": "かえる。「た」が「か」になる一モーラ差。", "冴える": "さえる。「た」が「さ」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "絶える"}, "level_3": {"options": [{"text": "絶え", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "食べ", "is_correct": false, "explanation": "意味：「食べず意味が更新される」は意味をなさない。"}, {"text": "泳が", "is_correct": false, "explanation": "意味：泳ぐことは意味の更新と関係がない。"}, {"text": "書か", "is_correct": false, "explanation": "項構造：「書かず」は目的語が必要で文が成り立たない。"}], "explanations": {"絶え": "文脈に合う正しい語。", "食べ": "意味：「食べず意味が更新される」は意味をなさない。", "泳が": "意味：泳ぐことは意味の更新と関係がない。", "書か": "項構造：「書かず」は目的語が必要で文が成り立たない。"}, "sentence_index": 0, "correct_answer": "絶え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の家は笑いを絶えない。", "explanation": "助詞の混同：「絶える」は自動詞で、主語は「が」。"}, {"text": "彼の家は笑いが絶えるない。", "explanation": "活用の誤り：「絶える」の否定は「絶えない」。"}, {"text": "彼の家は三冊の笑いが絶えない。", "explanation": "助数詞の誤り：笑いは「冊」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0835a5b8-0c2b-475e-a81f-6b8c4b182eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCL