INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51586, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "作物や製品などが実際に得られる量。", "primary_collocate": null, "pronunciation": "しゅうりょう", "ipa": "ɕɯːɾʲoː", "syllable_count": 4, "sentences": [{"text": "センサー等を用いた技術導入は、収量の安定化により収益性を向上させます。", "target_word": "収量", "complexity_tier": "T3", "furigana": "しゅうりょう", "sentence_source": "mined"}, {"text": "これにより、ムダを省きながら収量の「最適化」を図ることができます。", "target_word": "収量", "complexity_tier": "T3", "furigana": "しゅうりょう", "sentence_source": "mined"}, {"text": "今年は米の収量が増えた。", "target_word": "収量", "complexity_tier": "T3", "furigana": "しゅうりょう", "sentence_source": "generated"}, {"text": "雨が少なくて収量が減っている。", "target_word": "収量", "complexity_tier": "T3", "furigana": "しゅうりょう", "sentence_source": "generated"}, {"text": "新しい肥料で収量を上げられる。", "target_word": "収量", "complexity_tier": "T3", "furigana": "しゅうりょう", "sentence_source": "generated"}, {"text": "この畑の収量は去年より多い。", "target_word": "収量", "complexity_tier": "T3", "furigana": "しゅうりょう", "sentence_source": "generated"}, {"text": "農家は収量を毎年記録している。", "target_word": "収量", "complexity_tier": "T3", "furigana": "しゅうりょう", "sentence_source": "generated"}, {"text": "天気が収量に大きく関係する。", "target_word": "収量", "complexity_tier": "T3", "furigana": "しゅうりょう", "sentence_source": "generated"}, {"text": "収量の多い品種を選んだ。", "target_word": "収量", "complexity_tier": "T3", "furigana": "しゅうりょう", "sentence_source": "generated"}, {"text": "トマトの収量を比べてみた。", "target_word": "収量", "complexity_tier": "T3", "furigana": "しゅうりょう", "sentence_source": "generated"}], "morphological_forms": [{"form": "収量増加", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 作物などが実際に取れる量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45a2ade8-13aa-47db-928