INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51588, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "相手にしないで、ないものとして扱うこと。", "primary_collocate": null, "pronunciation": "むし", "ipa": "mɯɕi", "syllable_count": 2, "sentences": [{"text": "一方で、農村経済全体を見ると、労働需要の質が変化するという社会経済的影響も無視できません。", "target_word": "無視", "complexity_tier": "T3", "furigana": "むし", "sentence_source": "mined"}, {"text": "この際、脂質の膜がジャムの水分浸透を防ぐバリアーとして機能するという科学的裏付けも無視できない。", "target_word": "無視", "complexity_tier": "T3", "furigana": "むし", "sentence_source": "mined"}, {"text": "彼は私の話を無視した。", "target_word": "無視", "complexity_tier": "T3", "furigana": "むし", "sentence_source": "generated"}, {"text": "信号を無視してはいけない。", "target_word": "無視", "complexity_tier": "T3", "furigana": "むし", "sentence_source": "generated"}, {"text": "友だちに無視されて悲しかった。", "target_word": "無視", "complexity_tier": "T3", "furigana": "むし", "sentence_source": "generated"}, {"text": "その意見は無視できない。", "target_word": "無視", "complexity_tier": "T3", "furigana": "むし", "sentence_source": "generated"}, {"text": "無視はいじめの一つだ。", "target_word": "無視", "complexity_tier": "T3", "furigana": "むし", "sentence_source": "generated"}, {"text": "ルールの無視は許されない。", "target_word": "無視", "complexity_tier": "T3", "furigana": "むし", "sentence_source": "generated"}, {"text": "先生の注意を無視している。", "target_word": "無視", "complexity_tier": "T3", "furigana": "むし", "sentence_source": "generated"}, {"text": "無視するのはよくないと思う。", "target_word": "無視", "complexity_tier": "T3", "furigana": "むし", "sentence_source": "generated"}], "morphological_forms": [{"form": "無視する", "label": "活用"}, {"form": "無視した", "label": "活用"}, {"form": "無視される", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | ないものとして扱うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', tru