INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39329, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "特定の分野について深い知識や技術を持つこと。また、その分野。", "primary_collocate": null, "pronunciation": "せんもん", "ipa": "semmoɴ", "syllable_count": 4, "sentences": [{"text": "従来の肉体労働は減少しますが、機械を操作する専門知識を持つ人材の確保が、新たな課題として浮上しているのです。", "target_word": "専門", "complexity_tier": "T3", "furigana": "せんもん", "sentence_source": "mined"}, {"text": "多忙な現代の専門職に就く我々にとって、オフィスや書斎で迎える限られた昼食の時間はいかにして精神的・肉体的充足へと転換され得るだろうか。", "target_word": "専門", "complexity_tier": "T3", "furigana": "せんもん", "sentence_source": "mined"}, {"text": "兄の専門は物理学だ。", "target_word": "専門", "complexity_tier": "T3", "furigana": "せんもん", "sentence_source": "generated"}, {"text": "大学で経済を専門に学んでいる。", "target_word": "専門", "complexity_tier": "T3", "furigana": "せんもん", "sentence_source": "generated"}, {"text": "それは私の専門ではない。", "target_word": "専門", "complexity_tier": "T3", "furigana": "せんもん", "sentence_source": "generated"}, {"text": "専門の先生に話を聞いた。", "target_word": "専門", "complexity_tier": "T3", "furigana": "せんもん", "sentence_source": "generated"}, {"text": "彼女は子どもの病気が専門だ。", "target_word": "専門", "complexity_tier": "T3", "furigana": "せんもん", "sentence_source": "generated"}, {"text": "この店は靴が専門です。", "target_word": "専門", "complexity_tier": "T3", "furigana": "せんもん", "sentence_source": "generated"}, {"text": "専門の知識がなくても分かる。", "target_word": "専門", "complexity_tier": "T3", "furigana": "せんもん", "sentence_source": "generated"}, {"text": "将来は音楽を専門にしたい。", "target_word": "専門", "complexity_tier": "T3", "furigana": "せんもん", "sentence_source": "generated"}], "morphological_forms": [{"form": "専門家", "label": "派生"}, {"form": "専門的", "label": "派生"}, {"form": "専門店", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 特定分野の深い知識や技術", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: 5 words above tier T1 (max 2): 多忙 (Zipf 3.57), 就く (Zipf 3.43), 書斎 (Zipf 3.25), 昼食 (Zipf 3.9), 充足 (Zipf 3.05)']::text[], '45a2ade8-13aa-47db-9282-c68f3148d36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35515, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "土地を耕して作物を育てたり家畜を飼ったりして、食料を生産する産業。", "primary_collocate": null, "pronunciation": "のうぎょう", "ipa": "noːɡʲoː", "syllable_count": 4, "sentences": [{"text": "近年、精密農業の導入が小規模農家の経営に新たな可能性をもたらしています。", "target_word": "農業", "complexity_tier": "T3", "furigana": "のうぎょう", "sentence_source": "mined"}, {"text": "近年、センサーやデータ解析技術を活用した「精密農業」が注目されています。", "target_word": "農業", "complexity_tier": "T3", "furigana": "のうぎょう", "sentence_source": "mined"}, {"text": "祖父は長い間農業をしている。", "target_word": "農業", "complexity_tier": "T3", "furigana": "のうぎょう", "sentence_source": "generated"}, {"text": "この村は農業がさかんだ。", "target_word": "農業", "complexity_tier": "T3", "furigana": "のうぎょう", "sentence_source": "generated"}, {"text": "農業には水がとても大切だ。", "target_word": "農業", "complexity_tier": "T3", "furigana": "のうぎょう", "sentence_source": "generated"}, {"text": "将来は農業を仕事にしたい。", "target_word": "農業", "complexity_tier": "T3", "furigana": "のうぎょう", "sentence_source": "generated"}, {"text": "農業で働く若者が減っている。", "target_word": "農業", "complexity_tier": "T3", "furigana": "のうぎょう", "sentence_source": "generated"}, {"text": "学校で農業について学んだ。", "target_word": "農業", "complexity_tier": "T3", "furigana": "のうぎょう", "sentence_source": "generated"}, {"text": "天気は農業に大きく関わる。", "target_word": "農業", "complexity_tier": "T3", "furigana": "のうぎょう", "sentence_source": "generated"}, {"text": "農業の機械が新しくなった。", "target_word": "農業", "complexity_tier": "T3", "furigana": "のうぎょう", "sentence_source": "generated"}], "morphological_forms": [{"form": "農業用", "label": "派生"}, {"form": "農業者", "label": "派生"}, {"form": "農業国", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 作物や家畜を育てる産業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'clau