INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51586, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "収量", "is_correct": true, "explanation": "正解：「収量」（しゅうりょう）。"}, {"text": "少量", "is_correct": false, "explanation": "「少量」（しょうりょう）：「しゅ」が「しょ」になった語で、量が少ないこと。"}, {"text": "重量", "is_correct": false, "explanation": "「重量」（じゅうりょう）：最初が濁音になった語で、重さのこと。"}, {"text": "狩猟", "is_correct": false, "explanation": "「狩猟」（しゅりょう）：「しゅう」が短くなった語で、動物をとること。"}, {"text": "収容", "is_correct": false, "explanation": "「収容」（しゅうよう）：「りょ」が「よ」になった語で、人や物を入れること。"}], "explanations": {"収量": "正解：「収量」（しゅうりょう）。", "少量": "「少量」（しょうりょう）：「しゅ」が「しょ」になった語で、量が少ないこと。", "重量": "「重量」（じゅうりょう）：最初が濁音になった語で、重さのこと。", "狩猟": "「狩猟」（しゅりょう）：「しゅう」が短くなった語で、動物をとること。", "収容": "「収容」（しゅうよう）：「りょ」が「よ」になった語で、人や物を入れること。"}, "sentence_index": null, "correct_answer": "収量"}, "level_3": {"options": [{"text": "収量", "is_correct": true, "explanation": "「収量」が文の意味に合う。"}, {"text": "友情", "is_correct": false, "explanation": "意味：友だちの気持ちは技術で安定させて収益にするものではない。"}, {"text": "年齢", "is_correct": false, "explanation": "意味：年齢は技術導入で安定化するものではない。"}, {"text": "勇気", "is_correct": false, "explanation": "連語：「勇気の安定化」は不自然な結びつきだ。"}], "explanations": {"収量": "「収量」が文の意味に合う。", "友情": "意味：友だちの気持ちは技術で安定させて収益にするものではない。", "年齢": "意味：年齢は技術導入で安定化するものではない。", "勇気": "連語：「勇気の安定化」は不自然な結びつきだ。"}, "sentence_index": 0, "correct_answer": "収量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が少なくて収量で減っている。", "explanation": "助詞の混同：「収量で」では何が減るのか示せない。「が」が正しい。"}, {"text": "収量が雨が少なくて減っているに。", "explanation": "語順・係り受けの誤り：文末に助詞「に」が残り、文が成立しない。"}, {"text": "収量を二冊とれた。", "explanation": "助数詞の誤り：収量は「冊」で数えない。量は「トン」などで表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4397dffc-9090-43ce-b166-88579989dd89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
