INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51586, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「省く」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「省く」は他動詞なので、目的語に「が」は使えない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表し、ここでは意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、「省く」とは結びつかない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「省く」の目的語を示す。", "が": "「省く」は他動詞なので、目的語に「が」は使えない。", "で": "手段や場所を表し、ここでは意味が通らない。", "へ": "方向を表し、「省く」とは結びつかない。"}, "error_tags": {"が": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4397dffc-9090-43ce-b166-88579989dd89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51586, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "収量", "is_correct": true, "explanation": "正解：「収量」（しゅうりょう）。"}, {"text": "収納", "is_correct": false, "explanation": "「収納」（しゅうのう）：「りょう」が「のう」になった語。物をしまうこと。"}, {"text": "主力", "is_correct": false, "explanation": "「主力」（しゅりょく）：「しゅう」が短く、最後が「りょく」の語。中心となる力。"}, {"text": "首領", "is_correct": false, "explanation": "「首領」（しゅりょう）：「しゅう」が短い「しゅ」の語。集団のかしら。"}, {"text": "十両", "is_correct": false, "explanation": "「十両」（じゅうりょう）：最初が濁音「じゅ」の語。相撲の地位。"}], "explanations": {"収量": "正解：「収量」（しゅうりょう）。", "収納": "「収納」（しゅうのう）：「りょう」が「のう」になった語。物をしまうこと。", "主力": "「主力」（しゅりょく）：「しゅう」が短く、最後が「りょく」の語。中心となる力。", "首領": "「首領」（しゅりょう）：「しゅう」が短い「しゅ」の語。集団のかしら。", "十両": "「十両」（じゅうりょう）：最初が濁音「じゅ」の語。相撲の地位。"}, "sentence_index": null, "correct_answer": "収量"}, "level_3": {"options": [{"text": "収量", "is_correct": true, "explanation": "「収量」が文の意味に合う。"}, {"text": "住所", "is_correct": false, "explanation": "意味：農家が毎年記録する対象として住所は合わない。"}, {"text": "身長", "is_correct": false, "explanation": "意味：農家の仕事として身長を毎年記録するのは文脈に合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "語域：宿題は学校の場面の語で、農家の記録には合わない。"}], "explanations": {"収量": "「収量」が文の意味に合う。", "住所": "意味：農家が毎年記録する対象として住所は合わない。", "身長": "意味：農家の仕事として身長を毎年記録するのは文脈に合わない。", "宿題": "語域：宿題は学校の場面の語で、農家の記録には合わない。"}, "sentence_index": 6, "correct_answer": "収量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "トマトの収量が比べてみた。", "explanation": "助詞の混同：他動詞「比べる」の目的語は「を」で示す。"}, {"text": "トマトの収量を比べている昨日。", "explanation": "語順・係り受けの誤り：時を表す「昨日」が文末にあり、アスペクトとも合わない。"}, {"text": "トマトの収量を三匹比べた。", "explanation": "助数詞の誤り：収量は動物ではないので「匹」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4397dffc-9090-43ce-b166-88579989dd89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
