INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51588, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「防ぐ」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「防ぐ」の目的語に「が」は使えない。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、防ぐ対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表し、ここでは意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「防ぐ」の目的語を示す。", "が": "「防ぐ」の目的語に「が」は使えない。", "に": "着点を表し、防ぐ対象を示せない。", "で": "手段を表し、ここでは意味が通らない。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "重視", "is_correct": true, "explanation": "大事なものとして扱うことで、無視の反対。"}, {"text": "軽視", "is_correct": false, "explanation": "軽く扱うことで、無視に近く反対ではない。"}, {"text": "放置", "is_correct": false, "explanation": "そのままにしておくことで、反対の意味ではない。"}, {"text": "想像", "is_correct": false, "explanation": "心に思い描くことで、無視とは関係がない。"}], "correct_answer": "重視", "explanations": {"重視": "大事なものとして扱うことで、無視の反対。", "軽視": "軽く扱うことで、無視に近く反対ではない。", "放置": "そのままにしておくことで、反対の意味ではない。", "想像": "心に思い描くことで、無視とは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4397dffc-9090-43ce-b166-88579989dd89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51588, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "無視", "is_correct": true, "explanation": "正解：「無視」（むし）。"}, {"text": "無知", "is_correct": false, "explanation": "「無知」（むち）：「し」が「ち」になった語。知識がないこと。"}, {"text": "蒸す", "is_correct": false, "explanation": "「蒸す」（むす）：「し」が「す」になった語。湯気で熱すること。"}, {"text": "無地", "is_correct": false, "explanation": "「無地」（むじ）：最後が濁音の語。模様のない布など。"}, {"text": "牛", "is_correct": false, "explanation": "「牛」（うし）：最初が「う」の語。乳をとる動物。"}], "explanations": {"無視": "正解：「無視」（むし）。", "無知": "「無知」（むち）：「し」が「ち」になった語。知識がないこと。", "蒸す": "「蒸す」（むす）：「し」が「す」になった語。湯気で熱すること。", "無地": "「無地」（むじ）：最後が濁音の語。模様のない布など。", "牛": "「牛」（うし）：最初が「う」の語。乳をとる動物。"}, "sentence_index": null, "correct_answer": "無視"}, "level_3": {"options": [{"text": "無視", "is_correct": true, "explanation": "「無視」が文の意味に合う。"}, {"text": "勉強", "is_correct": false, "explanation": "意味：「勉強はいじめの一つ」は意味が通らない。"}, {"text": "握手", "is_correct": false, "explanation": "意味：握手は親しみを示す行為で、いじめではない。"}, {"text": "挨拶", "is_correct": false, "explanation": "連語：「挨拶はいじめの一つ」は不自然な結びつきだ。"}], "explanations": {"無視": "「無視」が文の意味に合う。", "勉強": "意味：「勉強はいじめの一つ」は意味が通らない。", "握手": "意味：握手は親しみを示す行為で、いじめではない。", "挨拶": "連語：「挨拶はいじめの一つ」は不自然な結びつきだ。"}, "sentence_index": 6, "correct_answer": "無視"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "無視するのはよくないだったと思う。", "explanation": "活用の誤り：「よくない」に「だった」は付かない。"}, {"text": "無視するのはよくないを思う。", "explanation": "助詞の混同：「思う」の内容は「と」で示す。"}, {"text": "よくないと無視するのは思う。", "explanation": "語順・係り受けの誤り：主題と述語の構造が壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4397dffc-9090-43ce-b166-88579989dd89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_erro