INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51588, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「ルールの無視」を主題として示す。"}, {"text": "を", "is_correct": false, "explanation": "「許されない」は受身で、主題に「を」は使えない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段を表し、ここでは非文になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、この文に合わない。"}], "correct_answer": "は", "explanations": {"は": "「ルールの無視」を主題として示す。", "を": "「許されない」は受身で、主題に「を」は使えない。", "で": "場所・手段を表し、ここでは非文になる。", "へ": "方向を表し、この文に合わない。"}, "error_tags": {"を": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "重視", "is_correct": true, "explanation": "重く見ることで、無視の反対。"}, {"text": "黙殺", "is_correct": false, "explanation": "黙って取り合わないことで、無視と近い意味。"}, {"text": "見逃し", "is_correct": false, "explanation": "気づかずに通すことで、反対ではない。"}, {"text": "出発", "is_correct": false, "explanation": "出かけることで、無視とは関係がない。"}], "correct_answer": "重視", "explanations": {"重視": "重く見ることで、無視の反対。", "黙殺": "黙って取り合わないことで、無視と近い意味。", "見逃し": "気づかずに通すことで、反対ではない。", "出発": "出かけることで、無視とは関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4397dffc-9090-43ce-b166-88579989dd89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39329, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "専門", "is_correct": true, "explanation": "正解：「専門」（せんもん）。"}, {"text": "天文", "is_correct": false, "explanation": "「天文」（てんもん）：「せ」が「て」になった語。星や宇宙のこと。"}, {"text": "正門", "is_correct": false, "explanation": "「正門」（せいもん）：「ん」が「い」になった語。正面の門。"}, {"text": "山門", "is_correct": false, "explanation": "「山門」（さんもん）：「せ」が「さ」になった語。寺の門。"}, {"text": "検問", "is_correct": false, "explanation": "「検問」（けんもん）：「せ」が「け」になった語。通る人や車を調べること。"}], "explanations": {"専門": "正解：「専門」（せんもん）。", "天文": "「天文」（てんもん）：「せ」が「て」になった語。星や宇宙のこと。", "正門": "「正門」（せいもん）：「ん」が「い」になった語。正面の門。", "山門": "「山門」（さんもん）：「せ」が「さ」になった語。寺の門。", "検問": "「検問」（けんもん）：「せ」が「け」になった語。通る人や車を調べること。"}, "sentence_index": null, "correct_answer": "専門"}, "level_3": {"options": [{"text": "専門", "is_correct": true, "explanation": "「専門」が文の意味に合う。"}, {"text": "近所", "is_correct": false, "explanation": "意味：「近所知識」は意味が通らない。"}, {"text": "家族", "is_correct": false, "explanation": "意味：機械を操作する知識として「家族知識」は合わない。"}, {"text": "天気", "is_correct": false, "explanation": "連語：「天気知識を持つ人材」は不自然な結びつきだ。"}], "explanations": {"専門": "「専門」が文の意味に合う。", "近所": "意味：「近所知識」は意味が通らない。", "家族": "意味：機械を操作する知識として「家族知識」は合わない。", "天気": "連語：「天気知識を持つ人材」は不自然な結びつきだ。"}, "sentence_index": 0, "correct_answer": "専門"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大学で経済が専門に学んでいる。", "explanation": "助詞の混同：「学ぶ」の対象は「を」で示す。"}, {"text": "大学に経済を専門に学んでいる。", "explanation": "助詞の混同：学ぶ場所は「に」ではなく「で」で示す。"}, {"text": "大学で経済を専門で学んでいる。", "explanation": "助詞の混同：「専門に学ぶ」の「に」を「で」にすると不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4397dffc-9090-43ce-b166-88579989dd89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation