INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35661, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "労働", "is_correct": true, "explanation": "正解：「労働」（ろうどう）。"}, {"text": "朗読", "is_correct": false, "explanation": "「朗読」（ろうどく）：最後の「う」が「く」になった語。声に出して読むこと。"}, {"text": "報道", "is_correct": false, "explanation": "「報道」（ほうどう）：「ろ」が「ほ」になった語。ニュースを伝えること。"}, {"text": "行動", "is_correct": false, "explanation": "「行動」（こうどう）：「ろ」が「こ」になった語。何かを行うこと。"}, {"text": "騒動", "is_correct": false, "explanation": "「騒動」（そうどう）：「ろ」が「そ」になった語。大きな騒ぎ。"}], "explanations": {"労働": "正解：「労働」（ろうどう）。", "朗読": "「朗読」（ろうどく）：最後の「う」が「く」になった語。声に出して読むこと。", "報道": "「報道」（ほうどう）：「ろ」が「ほ」になった語。ニュースを伝えること。", "行動": "「行動」（こうどう）：「ろ」が「こ」になった語。何かを行うこと。", "騒動": "「騒動」（そうどう）：「ろ」が「そ」になった語。大きな騒ぎ。"}, "sentence_index": null, "correct_answer": "労働"}, "level_3": {"options": [{"text": "労働", "is_correct": true, "explanation": "「労働」が文の意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "意味：「天気需要」は意味が通らない。"}, {"text": "趣味", "is_correct": false, "explanation": "意味：農村経済の需要として趣味は合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "連語：「年齢需要の質」は不自然な結びつきだ。"}], "explanations": {"労働": "「労働」が文の意味に合う。", "天気": "意味：「天気需要」は意味が通らない。", "趣味": "意味：農村経済の需要として趣味は合わない。", "年齢": "連語：「年齢需要の質」は不自然な結びつきだ。"}, "sentence_index": 0, "correct_answer": "労働"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "長い時間を労働はつらい。", "explanation": "助詞の混同：時間を修飾するには「の」が必要。"}, {"text": "長い時間の労働をつらい。", "explanation": "助詞の混同：「つらい」の主題は「は」で示す。"}, {"text": "長い時間の労働はつらいだ。", "explanation": "活用の誤り：形容詞「つらい」に「だ」は付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4397dffc-9090-43ce-b166-88579989dd89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLU