INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35661, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "労働", "is_correct": true, "explanation": "正解：「労働」（ろうどう）。"}, {"text": "葡萄", "is_correct": false, "explanation": "「葡萄」（ぶどう）：最初が「ぶ」の語。果物。"}, {"text": "老後", "is_correct": false, "explanation": "「老後」（ろうご）：後半が「ご」の語。年をとってからの時期。"}, {"text": "朗報", "is_correct": false, "explanation": "「朗報」（ろうほう）：後半が「ほう」の語。よい知らせ。"}, {"text": "堂々", "is_correct": false, "explanation": "「堂々」（どうどう）：最初が「ど」の語。立派な様子。"}], "explanations": {"労働": "正解：「労働」（ろうどう）。", "葡萄": "「葡萄」（ぶどう）：最初が「ぶ」の語。果物。", "老後": "「老後」（ろうご）：後半が「ご」の語。年をとってからの時期。", "朗報": "「朗報」（ろうほう）：後半が「ほう」の語。よい知らせ。", "堂々": "「堂々」（どうどう）：最初が「ど」の語。立派な様子。"}, "sentence_index": null, "correct_answer": "労働"}, "level_3": {"options": [{"text": "労働", "is_correct": true, "explanation": "「労働」が文の意味に合う。"}, {"text": "景色", "is_correct": false, "explanation": "意味：景色にお金が必要だという文は報酬の文脈に合わない。"}, {"text": "天井", "is_correct": false, "explanation": "意味：「天井にはきちんとお金が必要」は意味が通らない。"}, {"text": "夕日", "is_correct": false, "explanation": "意味：夕日はお金を払う対象ではない。"}], "explanations": {"労働": "「労働」が文の意味に合う。", "景色": "意味：景色にお金が必要だという文は報酬の文脈に合わない。", "天井": "意味：「天井にはきちんとお金が必要」は意味が通らない。", "夕日": "意味：夕日はお金を払う対象ではない。"}, "sentence_index": 6, "correct_answer": "労働"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもの労働を禁止されている。", "explanation": "助詞の混同：受身「禁止されている」の主語は「は／が」で示す。"}, {"text": "子どもの労働は禁止している。", "explanation": "活用の誤り：主語が禁止される側なので受身の形が必要。"}, {"text": "子どもの労働に禁止されている。", "explanation": "助詞の混同：禁止される対象は「に」ではなく「は」で示す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4397dffc-9090-43ce-b166-88579989dd89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
