INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38663, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのことを、どちらもだめにせずに同時に成り立たせること。", "primary_collocate": null, "pronunciation": "りょうりつ", "ipa": "ɾʲoːɾitsɯ", "syllable_count": 4, "sentences": [{"text": "単なる廃棄物としての隔離にとどまらず、炭素を資源へと転換し、あるいは地中へ封じ込めるこの技術は、経済活動と脱炭素化の両立という難題に対する、現時点での最適解たり得る。", "target_word": "両立", "complexity_tier": "T3", "furigana": "りょうりつ", "sentence_source": "mined"}, {"text": "すなわち、技術的革新は単なる効率化の道具にとどまらず、教育の公平性と個別最適化を両立させる新たな認識論的枠組みを構築し得るという点に、その本質的な教育的示唆が存すると言えよう。", "target_word": "両立", "complexity_tier": "T3", "furigana": "りょうりつ", "sentence_source": "mined"}, {"text": "勉強と部活の両立は大変だ。", "target_word": "両立", "complexity_tier": "T3", "furigana": "りょうりつ", "sentence_source": "generated"}, {"text": "姉は仕事と子育てを両立している。", "target_word": "両立", "complexity_tier": "T3", "furigana": "りょうりつ", "sentence_source": "generated"}, {"text": "趣味と勉強を両立させたい。", "target_word": "両立", "complexity_tier": "T3", "furigana": "りょうりつ", "sentence_source": "generated"}, {"text": "両立のこつを先輩に聞いた。", "target_word": "両立", "complexity_tier": "T3", "furigana": "りょうりつ", "sentence_source": "generated"}, {"text": "練習と宿題の両立に悩んでいる。", "target_word": "両立", "complexity_tier": "T3", "furigana": "りょうりつ", "sentence_source": "generated"}, {"text": "二つの夢の両立は難しい。", "target_word": "両立", "complexity_tier": "T3", "furigana": "りょうりつ", "sentence_source": "generated"}, {"text": "彼は学業とバイトを両立できた。", "target_word": "両立", "complexity_tier": "T3", "furigana": "りょうりつ", "sentence_source": "generated"}, {"text": "家族との時間と仕事の両立が大切だ。", "target_word": "両立", "complexity_tier": "T3", "furigana": "りょうりつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "両立する", "label": "派生"}, {"form": "両立させる", "label": "派生"}, {"form": "両立できる", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 二つの事を同時に成り立たせること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757a92f8-32b7-483d-9d80-db175cec7594') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35761, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の程度や範囲の、これ以上は進めないところ。", "primary_collocate": null, "pronunciation": "げんかい", "ipa": "ɡeŋkai", "syllable_count": 4, "sentences": [{"text": "我々が直面する環境的限界を超越するため、CCUSの社会実装は、産業構造の転換を支える要石として、その存在感をさらに増していくであろう。", "target_word": "限界", "complexity_tier": "T3", "furigana": "げんかい", "sentence_source": "mined"}, {"text": "単なるパンを焼き上げるという行為の域を超え、そこには古の製法への畏敬の念と、素材の潜在能力を限界まで引き出そうとする職人としての揺るぎない覚悟が、静かに宿っていたのである。", "target_word": "限界", "complexity_tier": "T3", "furigana": "げんかい", "sentence_source": "mined"}, {"text": "もう体力の限界だ。", "target_word": "限界", "complexity_tier": "T3", "furigana": "げんかい", "sentence_source": "generated"}, {"text": "自分の限界を知ることも大切だ。", "target_word": "限界", "complexity_tier": "T3", "furigana": "げんかい", "sentence_source": "generated"}, {"text": "限界まで走り続けた。", "target_word": "限界", "complexity_tier": "T3", "furigana": "げんかい", "sentence_source": "generated"}, {"text": "人の力には限界がある。", "target_word": "限界", "complexity_tier": "T3", "furigana": "げんかい", "sentence_source": "generated"}, {"text": "彼は限界を超えて練習した。", "target_word": "限界", "complexity_tier": "T3", "furigana": "げんかい", "sentence_source": "generated"}, {"text": "この方法の限界が見えてきた。", "target_word": "限界", "complexity_tier": "T3", "furigana": "げんかい", "sentence_source": "generated"}, {"text": "我慢も限界に近づいている。", "target_word": "限界", "complexity_tier": "T3", "furigana": "げんかい", "sentence_source": "generated"}, {"text": "限界を感じて、少し休んだ。", "target_word": "限界", "complexity_tier": "T3", "furigana": "げんかい", "sentence_source": "generated"}], "morphological_forms": [{"form": "限界点", "label": "派生"}, {"form": "限界的", "label": "派生"}, {"form": "限界値", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | これ以上進めない程度の果て", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 焼き上げる (Zipf 2.14), 引き出そ (Zipf 2.49)']::text[], '757a92f8-32b7-483d-9d80-db175cec7594') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35383, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物や人が、実際にそこにあること、いること。", "primary_collocate": null, "pronunciation": "そんざい", "ipa": "sonzai", "syllable_count": 4, "sentences": [{"text": "我々が直面する環境的限界を超越するため、CCUSの社会実装は、産業構造の転換を支える要石として、その存在感をさらに増していくであろう。", "target_word": "存在", "complexity_tier": "T3", "furigana": "そんざい", "sentence_source": "mined"}, {"text": "テクノロジー産業の持続的発展において、ベンチャーキャピタルの存在は極めて不可欠である。", "target_word": "存在", "complexity_tier": "T3", "furigana": "そんざい", "sentence_source": "mined"}, {"text": "彼は私にとって大切な存在だ。", "target_word": "存在", "complexity_tier": "T3", "furigana": "そんざい", "sentence_source": "generated"}, {"text": "宇宙人の存在を信じますか。", "target_word": "存在", "complexity_tier": "T3", "furigana": "そんざい", "sentence_source": "generated"}, {"text": "その店の存在を初めて知った。", "target_word": "存在", "complexity_tier": "T3", "furigana": "そんざい", "sentence_source": "generated"}, {"text": "犬の存在が家族を明るくした。", "target_word": "存在", "complexity_tier": "T3", "furigana": "そんざい", "sentence_source": "generated"}, {"text": "この問題は前から存在している。", "target_word": "存在", "complexity_tier": "T3", "furigana": "そんざい", "sentence_source": "generated"}, {"text": "彼女の存在に気づかなかった。", "target_word": "存在", "complexity_tier": "T3", "furigana": "そんざい", "sentence_source": "generated"}, {"text": "友達の存在は心の支えだ。", "target_word": "存在", "complexity_tier": "T3", "furigana": "そんざい", "sentence_source": "generated"}, {"text": "昔、ここに町が存在した。", "target_word": "存在", "complexity_tier": "T3", "furigana": "そんざい", "sentence_source": "generated"}], "morphological_forms": [{"form": "存在する", "label": "派生"}, {"form": "存在感", "label": "派生"}, {"form": "存在しない", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事が実際にあること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sens