INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37067, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人や生き物がすむ、太陽のまわりを回る星。", "primary_collocate": null, "pronunciation": "ちきゅう", "ipa": "tɕikʲɯː", "syllable_count": 3, "sentences": [{"text": "気候変動という地球的危機の緩和に向け、産業セクターにおける排出量の抑制は、持続可能性を担保する上で不可避の責務である。", "target_word": "地球", "complexity_tier": "T3", "furigana": "ちきゅう", "sentence_source": "mined"}, {"text": "地球システムにおける炭素循環は、地質学的時間軸において精緻な均衡を保ってきた。", "target_word": "地球", "complexity_tier": "T3", "furigana": "ちきゅう", "sentence_source": "mined"}, {"text": "地球は太陽のまわりを回っている。", "target_word": "地球", "complexity_tier": "T3", "furigana": "ちきゅう", "sentence_source": "generated"}, {"text": "宇宙から見た地球は青かった。", "target_word": "地球", "complexity_tier": "T3", "furigana": "ちきゅう", "sentence_source": "generated"}, {"text": "地球を大切にしよう。", "target_word": "地球", "complexity_tier": "T3", "furigana": "ちきゅう", "sentence_source": "generated"}, {"text": "地球の温度が上がっている。", "target_word": "地球", "complexity_tier": "T3", "furigana": "ちきゅう", "sentence_source": "generated"}, {"text": "月は地球より小さい。", "target_word": "地球", "complexity_tier": "T3", "furigana": "ちきゅう", "sentence_source": "generated"}, {"text": "地球には多くの生き物がいる。", "target_word": "地球", "complexity_tier": "T3", "furigana": "ちきゅう", "sentence_source": "generated"}, {"text": "私たちは地球に住んでいる。", "target_word": "地球", "complexity_tier": "T3", "furigana": "ちきゅう", "sentence_source": "generated"}, {"text": "地球の未来について話し合った。", "target_word": "地球", "complexity_tier": "T3", "furigana": "ちきゅう", "sentence_source": "generated"}], "morphological_forms": [{"form": "地球儀", "label": "派生"}, {"form": "地球人", "label": "派生"}, {"form": "地球上", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人がすむ太陽系の惑星", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'clau