INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38095, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "目や体、気持ちなどをある方向や相手の方へ向かわせる。", "primary_collocate": null, "pronunciation": "むける", "ipa": "mɯkeɾɯ", "syllable_count": 3, "sentences": [{"text": "気候変動という地球的危機の緩和に向け、産業セクターにおける排出量の抑制は、持続可能性を担保する上で不可避の責務である。", "target_word": "向け", "complexity_tier": "T3", "furigana": "む", "sentence_source": "mined"}, {"text": "秋の気配が色濃く漂う古びた縁側にて、一人の幼子が無心なる眼差しを向けているのは、掌に収められた一つの赤い果物である。", "target_word": "向け", "complexity_tier": "T3", "furigana": "む", "sentence_source": "mined"}, {"text": "彼女はカメラに笑顔を向けた。", "target_word": "向け", "complexity_tier": "T3", "furigana": "む", "sentence_source": "generated"}, {"text": "先生は生徒に目を向けた。", "target_word": "向け", "complexity_tier": "T3", "furigana": "む", "sentence_source": "generated"}, {"text": "試合に向けて毎日練習している。", "target_word": "向け", "complexity_tier": "T3", "furigana": "む", "sentence_source": "generated"}, {"text": "顔を窓の方に向ける。", "target_word": "向ける", "complexity_tier": "T3", "furigana": "む", "sentence_source": "generated"}, {"text": "弟は私に背中を向けたままだった。", "target_word": "向け", "complexity_tier": "T3", "furigana": "む", "sentence_source": "generated"}, {"text": "周りの人に関心を向けよう。", "target_word": "向け", "complexity_tier": "T3", "furigana": "む", "sentence_source": "generated"}, {"text": "みんなの目が彼に向けられた。", "target_word": "向け", "complexity_tier": "T3", "furigana": "む", "sentence_source": "generated"}, {"text": "ライトを舞台に向けてください。", "target_word": "向け", "complexity_tier": "T3", "furigana": "む", "sentence_source": "generated"}], "morphological_forms": [{"form": "向けた", "label": "活用"}, {"form": "向けて", "label": "活用"}, {"form": "向けない", "label": "活用"}, {"form": "向けられる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 目や気持ちを対象の方へ向かわせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: 6 words above tier T3 (max 3): 色濃く (Zipf 3.13), 古び (Zipf 2.76), 縁側 (Zipf 3.0), 幼子 (Zipf 2.71), 無心 (Zipf 3.09), 眼差し (Zipf 3.38)']::text[], '757a92f8-32b7-483d-9d80-db175cec7594') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35793, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "元素の一つ。記号はC。すべての生き物の体のもとになる。", "primary_collocate": null, "pronunciation": "たんそ", "ipa": "tanso", "syllable_count": 3, "sentences": [{"text": "再生可能エネルギーの導入加速にもかかわらず、製造プロセスの性質上、炭素発生をゼロ化し得ない領域において、CCUSは極めて重要な役割を担う。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "たんそ", "sentence_source": "mined"}, {"text": "単なる廃棄物としての隔離にとどまらず、炭素を資源へと転換し、あるいは地中へ封じ込めるこの技術は、経済活動と脱炭素化の両立という難題に対する、現時点での最適解たり得る。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "たんそ", "sentence_source": "mined"}, {"text": "地球システムにおける炭素循環は、地質学的時間軸において精緻な均衡を保ってきた。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "たんそ", "sentence_source": "mined"}, {"text": "ダイヤモンドは炭素でできている。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "たんそ", "sentence_source": "generated"}, {"text": "炭素は生き物の体に多い。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "たんそ", "sentence_source": "generated"}, {"text": "木を燃やすと炭素が出る。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "たんそ", "sentence_source": "generated"}, {"text": "理科で炭素について習った。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "たんそ", "sentence_source": "generated"}, {"text": "炭素の記号はCだ。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "たんそ", "sentence_source": "generated"}, {"text": "鉛筆のしんにも炭素が入っている。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "たんそ", "sentence_source": "generated"}, {"text": "工場は炭素を減らす努力をしている。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "たんそ", "sentence_source": "generated"}], "morphological_forms": [{"form": "二酸化炭素", "label": "派生"}, {"form": "炭素繊維", "label": "派生"}, {"form": "脱炭素", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 記号Cの元素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757a92f8-32b7-483d-9d80-db175cec7594') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38663, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "両立", "is_correct": true, "explanation": "正解：読み上げられた語そのもの。"}, {"text": "効率", "is_correct": false, "explanation": "「こうりつ」と読む別の語。語頭の「りょ」が「こ」に変わる一モーラ差。"}, {"text": "創立", "is_correct": false, "explanation": "「そうりつ」と読む別の語。語頭の「りょ」が「そ」に変わる一モーラ差。"}, {"text": "法律", "is_correct": false, "explanation": "「ほうりつ」と読む別の語。語頭の「りょ」が「ほ」に変わる一モーラ差。"}], "explanations": {"両立": "正解：読み上げられた語そのもの。", "効率": "「こうりつ」と読む別の語。語頭の「りょ」が「こ」に変わる一モーラ差。", "創立": "「そうりつ」と読む別の語。語頭の「りょ」が「そ」に変わる一モーラ差。", "法律": "「ほうりつ」と読む別の語。語頭の「りょ」が「ほ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "両立"}, "level_3": {"options": [{"text": "両立", "is_correct": true, "explanation": "経済活動と脱炭素化という二つを同時に成り立たせることを表す。"}, {"text": "独立", "is_correct": false, "explanation": "意味：一つのものが他から離れることで、「AとBの〜」という二者の同時成立に合わない。"}, {"text": "対立", "is_correct": false, "explanation": "意味：二つが争うことで、「難題に対する最適解」という文脈と矛盾する。"}, {"text": "孤立", "is_correct": false, "explanation": "意味：一つだけ離れることで、「AとBの〜」という二者の同時成立に合わない。"}], "explanations": {"両立": "経済活動と脱炭素化という二つを同時に成り立たせることを表す。", "独立": "意味：一つのものが他から離れることで、「AとBの〜」という二者の同時成立に合わない。", "対立": "意味：二つが争うことで、「難題に対する最適解」という文脈と矛盾する。", "孤立": "意味：一つだけ離れることで、「AとBの〜」という二者の同時成立に合わない。"}, "sentence_index": 0, "correct_answer": "両立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姉は仕事と子育てを両立を取っている。", "explanation": "連語・助詞の誤り：「両立を取る」とは言わず、「両立している」が正しい。"}, {"text": "姉は仕事が子育てに両立している。", "explanation": "助詞の混同：二つの事柄は「AとBを両立する」と並べる。"}, {"text": "姉は仕事と子育ての両立している。", "explanation": "助詞の誤り：動詞「両立する」の対象は「の」ではなく「を」で示す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38663, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "勉強と部活が両立は大変だ。", "corrected_sentence": "勉強と部活の両立は大変だ。", "error_description": "名詞「両立」を修飾するには「が」ではなく「の」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38663, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「両立させる」の目的語「公平性と個別最適化」を示す。"}, {"text": "が", "is_correct": false, "explanation": "「両立させる」は使役の他動詞で、目的語を「が」で示せない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は着点・相手を示し、両立させる対象にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、この位置では非文。"}], "correct_answer": "を", "explanations": {"を": "「両立させる」の目的語「公平性と個別最適化」を示す。", "が": "「両立させる」は使役の他動詞で、目的語を「が」で示せない。", "に": "「に」は着点・相手を示し、両立させる対象にならない。", "へ": "「へ」は方向を示し、この位置では非文。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38663, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "両立", "is_correct": true, "explanation": "正解：読み上げられた語そのもの。"}, {"text": "公立", "is_correct": false, "explanation": "「こうりつ」と読む別の語。語頭の「りょ」が「こ」に変わる一モーラ差。"}, {"text": "倒立", "is_correct": false, "explanation": "「とうりつ」と読む別の語。語頭の「りょ」が「と」に変わる一モーラ差。"}, {"text": "法律", "is_correct": false, "explanation": "「ほうりつ」と読む別の語。語頭の「りょ」が「ほ」に変わる一モーラ差。"}], "explanations": {"両立": "正解：読み上げられた語そのもの。", "公立": "「こうりつ」と読む別の語。語頭の「りょ」が「こ」に変わる一モーラ差。", "倒立": "「とうりつ」と読む別の語。語頭の「りょ」が「と」に変わる一モーラ差。", "法律": "「ほうりつ」と読む別の語。語頭の「りょ」が「ほ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "両立"}, "level_3": {"options": [{"text": "両立", "is_correct": true, "explanation": "練習と宿題の二つを同時にうまくこなすことを表す。"}, {"text": "中立", "is_correct": false, "explanation": "意味：どちらの側にもつかないことで、二つをこなす悩みに合わない。"}, {"text": "自立", "is_correct": false, "explanation": "意味：人に頼らず生活することで、「練習と宿題の」と結びつかない。"}, {"text": "成立", "is_correct": false, "explanation": "連語：契約や話が成り立つことで、「練習と宿題の成立に悩む」は不自然。"}], "explanations": {"両立": "練習と宿題の二つを同時にうまくこなすことを表す。", "中立": "意味：どちらの側にもつかないことで、二つをこなす悩みに合わない。", "自立": "意味：人に頼らず生活することで、「練習と宿題の」と結びつかない。", "成立": "連語：契約や話が成り立つことで、「練習と宿題の成立に悩む」は不自然。"}, "sentence_index": 6, "correct_answer": "両立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家族との時間と仕事の両立をが大切だ。", "explanation": "助詞の誤り：「をが」と二つの格助詞が重なり非文。"}, {"text": "家族との時間と仕事を両立が大切だ。", "explanation": "助詞の誤り：名詞「両立」を修飾するには「を」ではなく「の」を使う。"}, {"text": "家族との時間と仕事の両立するが大切だ。", "explanation": "品詞の誤り：主語にするには動詞「両立する」ではなく名詞「両立」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38663, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は学業とバイトに両立できた。", "corrected_sentence": "彼は学業とバイトを両立できた。", "error_description": "「両立する」の対象は「に」ではなく「を」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38663, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「二つの夢」が「両立」を修飾するので連体の「の」が入る。"}, {"text": "を", "is_correct": false, "explanation": "名詞「両立」の前では目的語の「を」は使えない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」では「両立」を修飾できない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」はこの位置では非文。"}], "correct_answer": "の", "explanations": {"の": "「二つの夢」が「両立」を修飾するので連体の「の」が入る。", "を": "名詞「両立」の前では目的語の「を」は使えない。", "で": "手段・場所の「で」では「両立」を修飾できない。", "へ": "方向の「へ」はこの位置では非文。"}, "error_tags": {"を": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35761, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "限界", "is_correct": true, "explanation": "正解：読み上げられた語そのもの。"}, {"text": "見解", "is_correct": false, "explanation": "「けんかい」と読む別の語。語頭の「げ」と「け」の清濁の違い。"}, {"text": "玄関", "is_correct": false, "explanation": "「げんかん」と読む別の語。最後の「い」が「ん」に変わる一モーラ差。"}, {"text": "現代", "is_correct": false, "explanation": "「げんだい」と読む別の語。「か」が「だ」に変わる一モーラ差。"}, {"text": "展開", "is_correct": false, "explanation": "「てんかい」と読む別の語。語頭の「げ」が「て」に変わる一モーラ差。"}], "explanations": {"限界": "正解：読み上げられた語そのもの。", "見解": "「けんかい」と読む別の語。語頭の「げ」と「け」の清濁の違い。", "玄関": "「げんかん」と読む別の語。最後の「い」が「ん」に変わる一モーラ差。", "現代": "「げんだい」と読む別の語。「か」が「だ」に変わる一モーラ差。", "展開": "「てんかい」と読む別の語。語頭の「げ」が「て」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "限界"}, "level_3": {"options": [{"text": "限界", "is_correct": true, "explanation": "環境がそれ以上耐えられない「終わりの線」を表す。"}, {"text": "機会", "is_correct": false, "explanation": "意味：チャンスのことで、「超越する」対象として意味が通らない。"}, {"text": "記録", "is_correct": false, "explanation": "連語：「環境的記録を超越する」は不自然。"}, {"text": "習慣", "is_correct": false, "explanation": "意味：くり返す行いのことで、環境的な制約を表さない。"}], "explanations": {"限界": "環境がそれ以上耐えられない「終わりの線」を表す。", "機会": "意味：チャンスのことで、「超越する」対象として意味が通らない。", "記録": "連語：「環境的記録を超越する」は不自然。", "習慣": "意味：くり返す行いのことで、環境的な制約を表さない。"}, "sentence_index": 0, "correct_answer": "限界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "自分の限界に知ることも大切だ。", "explanation": "助詞の混同：「知る」の目的語は「を」で示す。"}, {"text": "自分の限界するを知ることも大切だ。", "explanation": "品詞の誤り：「限界」は「する」をつけて動詞にできない。"}, {"text": "自分の限界的を知ることも大切だ。", "explanation": "語形の誤り：「限界的」は名詞として「を」の前に置けない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35761, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "もう体力に限界だ。", "corrected_sentence": "もう体力の限界だ。", "error_description": "「体力」が「限界」を修飾するので「に」ではなく「の」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35761, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "まで", "options": [{"text": "まで", "is_correct": true, "explanation": "「限界」を到達点として示し、「そこまで引き出す」意味になる。"}, {"text": "を", "is_correct": false, "explanation": "すでに「潜在能力を」があり、「限界を引き出す」では意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」では他動詞「引き出す」につながらない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示し、到達点を表せない。"}], "correct_answer": "まで", "explanations": {"まで": "「限界」を到達点として示し、「そこまで引き出す」意味になる。", "を": "すでに「潜在能力を」があり、「限界を引き出す」では意味が通らない。", "が": "主格の「が」では他動詞「引き出す」につながらない。", "より": "比較の基準を示し、到達点を表せない。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "より": "source_vs_goal"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35761, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "限界", "is_correct": true, "explanation": "正解：読み上げられた語そのもの。"}, {"text": "厳格", "is_correct": false, "explanation": "「げんかく」と読む別の語。最後の「い」が「く」に変わる一モーラ差。"}, {"text": "言外", "is_correct": false, "explanation": "「げんがい」と読む別の語。「か」と「が」の清濁の違い。"}, {"text": "旋回", "is_correct": false, "explanation": "「せんかい」と読む別の語。語頭の「げ」が「せ」に変わる一モーラ差。"}], "explanations": {"限界": "正解：読み上げられた語そのもの。", "厳格": "「げんかく」と読む別の語。最後の「い」が「く」に変わる一モーラ差。", "言外": "「げんがい」と読む別の語。「か」と「が」の清濁の違い。", "旋回": "「せんかい」と読む別の語。語頭の「げ」が「せ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "限界"}, "level_3": {"options": [{"text": "限界", "is_correct": true, "explanation": "自分の力が届く最後の線を超えて練習したことを表す。"}, {"text": "予定", "is_correct": false, "explanation": "意味：前もって決めた計画で、「超えて練習した」と意味がずれる。"}, {"text": "昼食", "is_correct": false, "explanation": "意味：食事のことで、練習の努力の程度を表さない。"}, {"text": "質問", "is_correct": false, "explanation": "連語：「質問を超える」とは言わない。"}], "explanations": {"限界": "自分の力が届く最後の線を超えて練習したことを表す。", "予定": "意味：前もって決めた計画で、「超えて練習した」と意味がずれる。", "昼食": "意味：食事のことで、練習の努力の程度を表さない。", "質問": "連語：「質問を超える」とは言わない。"}, "sentence_index": 6, "correct_answer": "限界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "限界に感じて、少し休んだ。", "explanation": "助詞の混同：「感じる」の対象は「を」で示す。"}, {"text": "限界して、少し休んだ。", "explanation": "品詞の誤り：「限界」は「する」をつけて動詞にできない。"}, {"text": "限界が感じて、少し休んだ。", "explanation": "助詞の誤り：他動詞「感じる」の対象は「が」ではなく「を」で示す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35761, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人の力には限界をある。", "corrected_sentence": "人の力には限界がある。", "error_description": "存在の「ある」の主語は「を」ではなく「が」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35761, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "自動詞「見える」の主語「限界」を示す。"}, {"text": "を", "is_correct": false, "explanation": "「見える」は自動詞なので目的語の「を」は取れない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段の「で」はこの位置では非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「見えてきた」の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "自動詞「見える」の主語「限界」を示す。", "を": "「見える」は自動詞なので目的語の「を」は取れない。", "で": "場所・手段の「で」はこの位置では非文。", "へ": "方向の「へ」は「見えてきた」の主語を示せない。"}, "error_tags": {"を": "object_marking", "で": "location_vs_target", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35383, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "存在", "is_correct": true, "explanation": "正解：読み上げられた語そのもの。"}, {"text": "損害", "is_correct": false, "explanation": "「そんがい」と読む別の語。「ざ」が「が」に変わる一モーラ差。"}, {"text": "尊大", "is_correct": false, "explanation": "「そんだい」と読む別の語。「ざ」が「だ」に変わる一モーラ差。"}, {"text": "混在", "is_correct": false, "explanation": "「こんざい」と読む別の語。語頭の「そ」が「こ」に変わる一モーラ差。"}], "explanations": {"存在": "正解：読み上げられた語そのもの。", "損害": "「そんがい」と読む別の語。「ざ」が「が」に変わる一モーラ差。", "尊大": "「そんだい」と読む別の語。「ざ」が「だ」に変わる一モーラ差。", "混在": "「こんざい」と読む別の語。語頭の「そ」が「こ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "存在"}, "level_3": {"options": [{"text": "存在", "is_correct": true, "explanation": "「存在感」として、その技術がそこにあって目立つ度合いを表す。"}, {"text": "責任", "is_correct": false, "explanation": "意味：「責任感」は人が持つ気持ちで、技術が増していくものではない。"}, {"text": "安心", "is_correct": false, "explanation": "意味：「安心感」は人の気持ちで、技術が増すものではない。"}, {"text": "満足", "is_correct": false, "explanation": "意味：「満足感」は人の気持ちで、技術の位置づけに合わない。"}], "explanations": {"存在": "「存在感」として、その技術がそこにあって目立つ度合いを表す。", "責任": "意味：「責任感」は人が持つ気持ちで、技術が増していくものではない。", "安心": "意味：「安心感」は人の気持ちで、技術が増すものではない。", "満足": "意味：「満足感」は人の気持ちで、技術の位置づけに合わない。"}, "sentence_index": 0, "correct_answer": "存在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宇宙人の存在に信じますか。", "explanation": "助詞の混同：「信じる」の対象は「を」で示す。"}, {"text": "宇宙人が存在を信じますか。", "explanation": "助詞の誤り：「存在」を修飾する「宇宙人」には「が」ではなく「の」を使う。"}, {"text": "宇宙人の存在するを信じますか。", "explanation": "品詞の誤り：「を」の前には名詞「存在」を使い、「存在する」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
