INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35383, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ベンチャーキャピタル」が「存在」を修飾する連体の「の」。"}, {"text": "を", "is_correct": false, "explanation": "名詞「存在」の前で目的語の「を」は使えない。"}, {"text": "に", "is_correct": false, "explanation": "「に」では「存在は不可欠」の主題を修飾できない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」はこの位置では非文。"}], "correct_answer": "の", "explanations": {"の": "「ベンチャーキャピタル」が「存在」を修飾する連体の「の」。", "を": "名詞「存在」の前で目的語の「を」は使えない。", "に": "「に」では「存在は不可欠」の主題を修飾できない。", "で": "手段・場所の「で」はこの位置では非文。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35383, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "存在", "is_correct": true, "explanation": "正解：読み上げられた語そのもの。"}, {"text": "ぞんざい", "is_correct": false, "explanation": "「ぞんざい」と読む別の語。語頭の「そ」と「ぞ」の清濁の違い。"}, {"text": "村内", "is_correct": false, "explanation": "「そんない」と読む別の語。「ざ」が「な」に変わる一モーラ差。"}, {"text": "散在", "is_correct": false, "explanation": "「さんざい」と読む別の語。語頭の「そ」が「さ」に変わる一モーラ差。"}], "explanations": {"存在": "正解：読み上げられた語そのもの。", "ぞんざい": "「ぞんざい」と読む別の語。語頭の「そ」と「ぞ」の清濁の違い。", "村内": "「そんない」と読む別の語。「ざ」が「な」に変わる一モーラ差。", "散在": "「さんざい」と読む別の語。語頭の「そ」が「さ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "存在"}, "level_3": {"options": [{"text": "存在", "is_correct": true, "explanation": "「存在している」で、問題が前からあることを表す。"}, {"text": "期待", "is_correct": false, "explanation": "意味：「期待している」は望むことで、「問題は」と合わない。"}, {"text": "練習", "is_correct": false, "explanation": "意味：「練習している」は人の行為で、「問題」が主語にならない。"}, {"text": "勉強", "is_correct": false, "explanation": "項構造：「勉強している」は人が主語で、「問題は」と合わない。"}], "explanations": {"存在": "「存在している」で、問題が前からあることを表す。", "期待": "意味：「期待している」は望むことで、「問題は」と合わない。", "練習": "意味：「練習している」は人の行為で、「問題」が主語にならない。", "勉強": "項構造：「勉強している」は人が主語で、「問題は」と合わない。"}, "sentence_index": 6, "correct_answer": "存在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昔、ここに町を存在した。", "explanation": "助詞の混同：「存在する」は自動詞で「を」を取らない。"}, {"text": "昔、ここに町が存在している。", "explanation": "アスペクトの誤り：「昔」と現在の「ている」が合わない。"}, {"text": "昔、ここに町が存在あった。", "explanation": "語形の誤り：「存在」は「する」で動詞になり、「存在あった」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
