INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37067, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地球", "is_correct": true, "explanation": "正解：読み上げられた語そのもの。"}, {"text": "気球", "is_correct": false, "explanation": "「ききゅう」と読む別の語。語頭の「ち」が「き」に変わる一モーラ差。"}, {"text": "至急", "is_correct": false, "explanation": "「しきゅう」と読む別の語。語頭の「ち」が「し」に変わる一モーラ差。"}, {"text": "誓う", "is_correct": false, "explanation": "「ちかう」と読む別の語。「きゅ」が「か」に変わる一モーラ差。"}], "explanations": {"地球": "正解：読み上げられた語そのもの。", "気球": "「ききゅう」と読む別の語。語頭の「ち」が「き」に変わる一モーラ差。", "至急": "「しきゅう」と読む別の語。語頭の「ち」が「し」に変わる一モーラ差。", "誓う": "「ちかう」と読む別の語。「きゅ」が「か」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "地球"}, "level_3": {"options": [{"text": "地球", "is_correct": true, "explanation": "気候変動が私たちの星全体の危機であることを表す。"}, {"text": "個人", "is_correct": false, "explanation": "意味：一人の人のことで、気候変動の規模に合わない。"}, {"text": "家庭", "is_correct": false, "explanation": "意味：家のことで、「地球的危機」の規模を表さない。"}, {"text": "学校", "is_correct": false, "explanation": "連語：「学校的危機」は不自然。"}], "explanations": {"地球": "気候変動が私たちの星全体の危機であることを表す。", "個人": "意味：一人の人のことで、気候変動の規模に合わない。", "家庭": "意味：家のことで、「地球的危機」の規模を表さない。", "学校": "連語：「学校的危機」は不自然。"}, "sentence_index": 0, "correct_answer": "地球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宇宙から見た地球を青かった。", "explanation": "助詞の混同：形容詞「青い」の主語は「を」で示せない。"}, {"text": "宇宙から見た地球に青かった。", "explanation": "助詞の誤り：形容詞「青い」の主語「地球」は「に」ではなく「は」で示す。"}, {"text": "宇宙から見た地球な青かった。", "explanation": "助詞の誤り：名詞「地球」のあとに「な」は続かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
