INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37067, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「地球システムにおける」で、範囲・場面を示す「に」。"}, {"text": "で", "is_correct": false, "explanation": "「〜でおける」という形はなく、「おける」は「に」だけをとる。"}, {"text": "を", "is_correct": false, "explanation": "「おける」は目的語をとらず、「をおける」は非文。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は「おける」に続かない。"}], "correct_answer": "に", "explanations": {"に": "「地球システムにおける」で、範囲・場面を示す「に」。", "で": "「〜でおける」という形はなく、「おける」は「に」だけをとる。", "を": "「おける」は目的語をとらず、「をおける」は非文。", "から": "起点の「から」は「おける」に続かない。"}, "error_tags": {"で": "location_vs_target", "を": "object_marking", "から": "source_vs_goal"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37067, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "地球", "is_correct": true, "explanation": "正解：読み上げられた語そのもの。"}, {"text": "支給", "is_correct": false, "explanation": "「しきゅう」と読む別の語。語頭の「ち」が「し」に変わる一モーラ差。"}, {"text": "地区", "is_correct": false, "explanation": "「ちく」と読む別の語。「きゅう」が「く」に変わる違い。"}, {"text": "知識", "is_correct": false, "explanation": "「ちしき」と読む別の語。「きゅう」が「しき」に変わる違い。"}], "explanations": {"地球": "正解：読み上げられた語そのもの。", "支給": "「しきゅう」と読む別の語。語頭の「ち」が「し」に変わる一モーラ差。", "地区": "「ちく」と読む別の語。「きゅう」が「く」に変わる違い。", "知識": "「ちしき」と読む別の語。「きゅう」が「しき」に変わる違い。"}, "sentence_index": null, "correct_answer": "地球"}, "level_3": {"options": [{"text": "地球", "is_correct": true, "explanation": "月と比べる対象として、私たちの住む星を表す。"}, {"text": "机", "is_correct": false, "explanation": "意味：家具であり、月と大きさを比べる対象として不自然。"}, {"text": "鉛筆", "is_correct": false, "explanation": "意味：文房具で、月との比較にならない。"}, {"text": "教室", "is_correct": false, "explanation": "意味：部屋のことで、天体の大きさの比較に合わない。"}], "explanations": {"地球": "月と比べる対象として、私たちの住む星を表す。", "机": "意味：家具であり、月と大きさを比べる対象として不自然。", "鉛筆": "意味：文房具で、月との比較にならない。", "教室": "意味：部屋のことで、天体の大きさの比較に合わない。"}, "sentence_index": 6, "correct_answer": "地球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地球を未来について話し合った。", "explanation": "助詞の誤り：「未来」を修飾する「地球」には「を」ではなく「の」を使う。"}, {"text": "地球に未来について話し合った。", "explanation": "助詞の混同：「地球の未来」とすべきところを「に」にしている。"}, {"text": "地球な未来について話し合った。", "explanation": "助詞の誤り：名詞「地球」が名詞を修飾するときは「な」ではなく「の」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37067, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私たちは地球で住んでいる。", "corrected_sentence": "私たちは地球に住んでいる。", "error_description": "「住む」の場所は「で」ではなく「に」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37067, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "存在の場所「地球」を示す「に」。"}, {"text": "を", "is_correct": false, "explanation": "「いる」は自動詞で「を」を取らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は存在の場所を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は「いる」の場所にならない。"}], "correct_answer": "に", "explanations": {"に": "存在の場所「地球」を示す「に」。", "を": "「いる」は自動詞で「を」を取らない。", "へ": "方向の「へ」は存在の場所を示せない。", "から": "起点の「から」は「いる」の場所にならない。"}, "error_tags": {"を": "object_marking", "へ": "direction", "から": "source_vs_goal"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38095, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "向ける", "is_correct": true, "explanation": "正解：読み上げられた語そのもの。"}, {"text": "抜ける", "is_correct": false, "explanation": "「ぬける」と読む別の語。語頭の「む」が「ぬ」に変わる一モーラ差。"}, {"text": "群れる", "is_correct": false, "explanation": "「むれる」と読む別の語。「け」が「れ」に変わる一モーラ差。"}, {"text": "むせる", "is_correct": false, "explanation": "「むせる」と読む別の語。「け」が「せ」に変わる一モーラ差。"}], "explanations": {"向ける": "正解：読み上げられた語そのもの。", "抜ける": "「ぬける」と読む別の語。語頭の「む」が「ぬ」に変わる一モーラ差。", "群れる": "「むれる」と読む別の語。「け」が「れ」に変わる一モーラ差。", "むせる": "「むせる」と読む別の語。「け」が「せ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "向ける"}, "level_3": {"options": [{"text": "向け", "is_correct": true, "explanation": "「〜に向け」で、気候変動の緩和という目標の方へ進むことを表す。"}, {"text": "比べ", "is_correct": false, "explanation": "意味：「緩和に比べ」は比較になり、目標を表さない。"}, {"text": "限り", "is_correct": false, "explanation": "連語：「緩和に限り」は限定になり、文意が通らない。"}, {"text": "似せ", "is_correct": false, "explanation": "意味：「緩和に似せ」は意味が通らない。"}], "explanations": {"向け": "「〜に向け」で、気候変動の緩和という目標の方へ進むことを表す。", "比べ": "意味：「緩和に比べ」は比較になり、目標を表さない。", "限り": "連語：「緩和に限り」は限定になり、文意が通らない。", "似せ": "意味：「緩和に似せ」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "向け"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は生徒を目に向けた。", "explanation": "助詞の混同：向ける対象は「を」、向け先は「に」で、逆になっている。"}, {"text": "先生は生徒に目が向けた。", "explanation": "助詞の誤り：他動詞「向ける」の目的語は「が」で示せない。"}, {"text": "先生は生徒に目を向かった。", "explanation": "自他の誤り：「目を」をとるのは他動詞「向ける」で、自動詞「向かう」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38095, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女はカメラを笑顔に向けた。", "corrected_sentence": "彼女はカメラに笑顔を向けた。", "error_description": "向ける物（笑顔）は「を」、向け先（カメラ）は「に」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "向け", "is_correct": true, "explanation": "「ている」に続くので連用形「向け」が必要。"}, {"text": "向ける", "is_correct": false, "explanation": "辞書形は「ている」に続かない。"}, {"text": "向けた", "is_correct": false, "explanation": "た形は「ている」に続かない。"}, {"text": "向けろ", "is_correct": false, "explanation": "命令形は「ている」に続かない。"}], "correct_form": "向け", "base_form": "向ける", "form_label": "連用形（「ている」に続く形）", "sentence_index": 1, "explanations": {"向け": "「ている」に続くので連用形「向け」が必要。", "向ける": "辞書形は「ている」に続かない。", "向けた": "た形は「ている」に続かない。", "向けろ": "命令形は「ている」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38095, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「向ける」の目的語「眼差し」を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」では他動詞「向ける」の目的語にならない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は向け先を示し、向ける物は示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」では「眼差しで向けている」となり非文。"}], "correct_answer": "を", "explanations": {"を": "他動詞「向ける」の目的語「眼差し」を示す。", "が": "主格の「が」では他動詞「向ける」の目的語にならない。", "に": "「に」は向け先を示し、向ける物は示せない。", "で": "手段の「で」では「眼差しで向けている」となり非文。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "背ける", "is_correct": true, "explanation": "視線や顔をある方へ向けるのと反対に、そらすこと。"}, {"text": "向かう", "is_correct": false, "explanation": "自分がある方へ進むことで、反対の意味ではない。"}, {"text": "注ぐ", "is_correct": false, "explanation": "気持ちや視線を集中させることで、むしろ近い意味。"}, {"text": "寄せる", "is_correct": false, "explanation": "関心などを近づけることで、反対ではない。"}], "correct_answer": "背ける", "explanations": {"背ける": "視線や顔をある方へ向けるのと反対に、そらすこと。", "向かう": "自分がある方へ進むことで、反対の意味ではない。", "注ぐ": "気持ちや視線を集中させることで、むしろ近い意味。", "寄せる": "関心などを近づけることで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38095, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "向ける", "is_correct": true, "explanation": "正解：読み上げられた語そのもの。"}, {"text": "開ける", "is_correct": false, "explanation": "「あける」と読む別の語。語頭の「む」が「あ」に変わる一モーラ差。"}, {"text": "掛ける", "is_correct": false, "explanation": "「かける」と読む別の語。語頭の「む」が「か」に変わる一モーラ差。"}, {"text": "避ける", "is_correct": false, "explanation": "「よける」と読む別の語。語頭の「む」が「よ」に変わる一モーラ差。"}], "explanations": {"向ける": "正解：読み上げられた語そのもの。", "開ける": "「あける」と読む別の語。語頭の「む」が「あ」に変わる一モーラ差。", "掛ける": "「かける」と読む別の語。語頭の「む」が「か」に変わる一モーラ差。", "避ける": "「よける」と読む別の語。語頭の「む」が「よ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "向ける"}, "level_3": {"options": [{"text": "向け", "is_correct": true, "explanation": "背中を私の方へ向けたままだったことを表す。"}, {"text": "洗っ", "is_correct": false, "explanation": "連語：「背中を洗ったまま」となり、「私に」と結びつかない。"}, {"text": "かけ", "is_correct": false, "explanation": "意味：「私に背中をかけた」は意味が通らない。"}, {"text": "売っ", "is_correct": false, "explanation": "意味：「私に背中を売った」は意味が通らない。"}], "explanations": {"向け": "背中を私の方へ向けたままだったことを表す。", "洗っ": "連語：「背中を洗ったまま」となり、「私に」と結びつかない。", "かけ": "意味：「私に背中をかけた」は意味が通らない。", "売っ": "意味：「私に背中を売った」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "向け"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ライトに舞台を向けてください。", "explanation": "助詞の混同：向ける物と向け先が逆で、ライトを舞台へ向ける意味にならない。"}, {"text": "ライトが舞台に向けてください。", "explanation": "助詞の誤り：依頼文で他動詞の目的語を「が」で示せない。"}, {"text": "ライトを舞台に向かってください。", "explanation": "自他の誤り：「ライトを」をとるのは他動詞「向ける」で、自動詞「向かう」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings =