INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39001, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が確実に行われるように保証すること。", "primary_collocate": null, "pronunciation": "たんぽ", "ipa": "tampo", "syllable_count": 3, "sentences": [{"text": "気候変動という地球的危機の緩和に向け、産業セクターにおける排出量の抑制は、持続可能性を担保する上で不可避の責務である。", "target_word": "担保", "complexity_tier": "T3", "furigana": "たんぽ", "sentence_source": "mined"}, {"text": "イールドカーブ・コントロールの下では、市場メカニズムを通じた適正なリスクプレミアムの形成が阻害され、結果として財政の持続可能性を担保するべき債務の価格的シグナルが鈍磨する懸念が拭えない。", "target_word": "担保", "complexity_tier": "T3", "furigana": "たんぽ", "sentence_source": "mined"}, {"text": "品質を担保する仕組みが必要だ。", "target_word": "担保", "complexity_tier": "T3", "furigana": "ひんしつ たんぽ しくみ ひつよう", "sentence_source": "generated"}, {"text": "安全の担保が何より大切だ。", "target_word": "担保", "complexity_tier": "T3", "furigana": "あんぜん たんぽ なに たいせつ", "sentence_source": "generated"}, {"text": "この制度で公平さが担保される。", "target_word": "担保", "complexity_tier": "T3", "furigana": "せいど こうへい たんぽ", "sentence_source": "generated"}, {"text": "信頼は約束で担保されている。", "target_word": "担保", "complexity_tier": "T3", "furigana": "しんらい やくそく たんぽ", "sentence_source": "generated"}, {"text": "透明性を担保するため公開した。", "target_word": "担保", "complexity_tier": "T3", "furigana": "とうめいせい たんぽ こうかい", "sentence_source": "generated"}, {"text": "正確さの担保が課題になった。", "target_word": "担保", "complexity_tier": "T3", "furigana": "せいかく たんぽ かだい", "sentence_source": "generated"}, {"text": "質を担保できる方法を考える。", "target_word": "担保", "complexity_tier": "T3", "furigana": "しつ たんぽ ほうほう かんが", "sentence_source": "generated"}, {"text": "担保のない計画は不安だ。", "target_word": "担保", "complexity_tier": "T3", "furigana": "たんぽ けいかく ふあん", "sentence_source": "generated"}], "morphological_forms": [{"form": "担保する", "label": "派生"}, {"form": "担保される", "label": "活用"}, {"form": "担保した", "label": "活用"}, {"form": "担保できる", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 確実さを保証すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d7ccd7-38e8-4ed7-83ac-bc82fee685e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38235, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "数や量、程度が大きくなる。また、大きくする。", "primary_collocate": null, "pronunciation": "ます", "ipa": "masɯ", "syllable_count": 2, "sentences": [{"text": "我々が直面する環境的限界を超越するため、CCUSの社会実装は、産業構造の転換を支える要石として、その存在感をさらに増していくであろう。", "target_word": "増し", "complexity_tier": "T3", "furigana": "ます", "sentence_source": "mined"}, {"text": "その後、長時間にわたる低温発酵を経ることで、グルテンの網目は緻密さを増し、消化吸収にも優れた変容を遂げる。", "target_word": "増し", "complexity_tier": "T3", "furigana": "ます", "sentence_source": "mined"}, {"text": "雨で川の水の量が増した。", "target_word": "増し", "complexity_tier": "T3", "furigana": "あめ かわ みず りょう ま", "sentence_source": "generated"}, {"text": "春になり日差しが強さを増す。", "target_word": "増す", "complexity_tier": "T3", "furigana": "はる ひざ つよ ま", "sentence_source": "generated"}, {"text": "練習で自信が増していった。", "target_word": "増し", "complexity_tier": "T3", "furigana": "れんしゅう じしん ま", "sentence_source": "generated"}, {"text": "人気が日ごとに増している。", "target_word": "増し", "complexity_tier": "T3", "furigana": "にんき ひ ま", "sentence_source": "generated"}, {"text": "不安が増して眠れなかった。", "target_word": "増し", "complexity_tier": "T3", "furigana": "ふあん ま ねむ", "sentence_source": "generated"}, {"text": "速度を増す車に驚いた。", "target_word": "増す", "complexity_tier": "T3", "furigana": "そくど ま くるま おどろ", "sentence_source": "generated"}, {"text": "友情はさらに深みを増した。", "target_word": "増し", "complexity_tier": "T3", "furigana": "ゆうじょう ふか ま", "sentence_source": "generated"}, {"text": "緊張が増すと声がふるえる。", "target_word": "増す", "complexity_tier": "T3", "furigana": "きんちょう ま こえ", "sentence_source": "generated"}], "morphological_forms": [{"form": "増した", "label": "活用"}, {"form": "増して", "label": "活用"}, {"form": "増さない", "label": "活用"}, {"form": "増し", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 数量や程度が大きくなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: 6 words above tier T3 (max 3): 経る (Zipf 2.96), グルテン (Zipf 2.78), 網目 (Zipf 2.67), 緻密 (Zipf 3.25), 変容 (Zipf 3.25), 遂げる (Zipf 3.13)']::text[], 'f3d7ccd7-38e8-4ed7-83ac-bc82fee685e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52448, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事が及ぶ範囲や分野。", "primary_collocate": null, "pronunciation": "りょういき", "ipa": "ɾʲoːiki", "syllable_count": 4, "sentences": [{"text": "再生可能エネルギーの導入加速にもかかわらず、製造プロセスの性質上、炭素発生をゼロ化し得ない領域において、CCUSは極めて重要な役割を担う。", "target_word": "領域", "complexity_tier": "T3", "furigana": "りょういき", "sentence_source": "mined"}, {"text": "凍てつく空気の中、ボタンを一つひとつ留める仕草には、未知の領域へ挑む戦士のような厳粛ささえ漂っていた。", "target_word": "領域", "complexity_tier": "T3", "furigana": "りょういき", "sentence_source": "mined"}, {"text": "彼は新しい領域に挑んでいる。", "target_word": "領域", "complexity_tier": "T3", "furigana": "かれ あたら りょういき いど", "sentence_source": "generated"}, {"text": "それは私の専門領域ではない。", "target_word": "領域", "complexity_tier": "T3", "furigana": "わたし せんもん りょういき", "sentence_source": "generated"}, {"text": "この問題は心理学の領域に入る。", "target_word": "領域", "complexity_tier": "T3", "furigana": "もんだい しんりがく りょういき はい", "sentence_source": "generated"}, {"text": "研究の領域が広がってきた。", "target_word": "領域", "complexity_tier": "T3", "furigana": "けんきゅう りょういき ひろ", "sentence_source": "generated"}, {"text": "未知の領域に足を踏み入れた。", "target_word": "領域", "complexity_tier": "T3", "furigana": "みち りょういき あし ふ い", "sentence_source": "generated"}, {"text": "この領域では経験が大切だ。", "target_word": "領域", "complexity_tier": "T3", "furigana": "りょういき けいけん たいせつ", "sentence_source": "generated"}, {"text": "二つの領域を結ぶ仕事をする。", "target_word": "領域", "complexity_tier": "T3", "furigana": "ふた りょういき むす しごと", "sentence_source": "generated"}, {"text": "領域を越えて協力し合う。", "target_word": "領域", "complexity_tier": "T3", "furigana": "りょういき こ きょうりょく あ", "sentence_source": "generated"}], "morphological_forms": [{"form": "領域外", "label": "派生"}, {"form": "専門領域", "label": "派生"}, {"form": "研究領域", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事が及ぶ範囲や分野", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 凍てつく (Zipf 2.35)']::text[], 'f3d7ccd7-38e8-4ed7-83ac-bc82fee685e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35427, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の状態や数量が時とともに変わること。", "primary_collocate": null, "pronunciation": "へんどう", "ipa": "hendoː", "syllable_count": 4, "sentences": [{"text": "気候変動という地球的危機の緩和に向け、産業セクターにおける排出量の抑制は、持続可能性を担保する上で不可避の責務である。", "target_word": "変動", "complexity_tier": "T3", "furigana": "へんどう", "sentence_source": "mined"}, {"text": "人為的な要因によって大気中に放出された過剰な温室効果ガスは、放射強制力を変化させ、全球規模での気候変動を加速させている。", "target_word": "変動", "complexity_tier": "T3", "furigana": "へんどう", "sentence_source": "mined"}, {"text": "物価の変動が大きい年だった。", "target_word": "変動", "complexity_tier": "T3", "furigana": "ぶっか へんどう おお とし", "sentence_source": "generated"}, {"text": "気温が一日で大きく変動した。", "target_word": "変動", "complexity_tier": "T3", "furigana": "きおん いちにち おお へんどう", "sentence_source": "generated"}, {"text": "株価は毎日変動している。", "target_word": "変動", "complexity_tier": "T3", "furigana": "かぶか まいにち へんどう", "sentence_source": "generated"}, {"text": "人口の変動を調べてみた。", "target_word": "変動", "complexity_tier": "T3", "furigana": "じんこう へんどう しら", "sentence_source": "generated"}, {"text": "変動する数字を記録した。", "target_word": "変動", "complexity_tier": "T3", "furigana": "へんどう すうじ きろく", "sentence_source": "generated"}, {"text": "為替の変動に注意が必要だ。", "target_word": "変動", "complexity_tier": "T3", "furigana": "かわせ へんどう ちゅうい ひつよう", "sentence_source": "generated"}, {"text": "天候の変動で収穫が減った。", "target_word": "変動", "complexity_tier": "T3", "furigana": "てんこう へんどう しゅうかく へ", "sentence_source": "generated"}, {"text": "価格が変動しやすい商品だ。", "target_word": "変動", "complexity_tier": "T3", "furigana": "かかく へんどう しょうひん", "sentence_source": "generated"}], "morphological_forms": [{"form": "変動する", "label": "派生"}, {"form": "変動した", "label": "活用"}, {"form": "価格変動", "label": "派生"}, {"form": "変動制", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 状態や数量が時と共に変わる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d7ccd7-38e8-4ed7-83ac-bc82fee685e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36337, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人の生活や産業に役立てられるもの。自然のものや人材、時間なども含む。", "primary_collocate": null, "pronunciation": "しげん", "ipa": "ɕiɡeɴ", "syllable_count": 3, "sentences": [{"text": "単なる廃棄物としての隔離にとどまらず、炭素を資源へと転換し、あるいは地中へ封じ込めるこの技術は、経済活動と脱炭素化の両立という難題に対する、現時点での最適解たり得る。", "target_word": "資源", "complexity_tier": "T3", "furigana": "しげん", "sentence_source": "mined"}, {"text": "また、限られた環境で効率的に生産を行う「資源管理」の観点からも、持続可能な食料供給の実現において重要な役割を果たしています。", "target_word": "資源", "complexity_tier": "T3", "furigana": "しげん", "sentence_source": "mined"}, {"text": "日本は資源が少ない国だ。", "target_word": "資源", "complexity_tier": "T3", "furigana": "にほん しげん すく くに", "sentence_source": "generated"}, {"text": "水は大切な資源の一つだ。", "target_word": "資源", "complexity_tier": "T3", "furigana": "みず たいせつ しげん ひと", "sentence_source": "generated"}, {"text": "資源を大事に使おう。", "target_word": "資源", "complexity_tier": "T3", "furigana": "しげん だいじ つか", "sentence_source": "generated"}, {"text": "この国は資源に恵まれている。", "target_word": "資源", "complexity_tier": "T3", "furigana": "くに しげん めぐ", "sentence_source": "generated"}, {"text": "資源ごみは月曜日に出す。", "target_word": "資源", "complexity_tier": "T3", "furigana": "しげん げつようび だ", "sentence_source": "generated"}, {"text": "時間も限られた資源だと思う。", "target_word": "資源", "complexity_tier": "T3", "furigana": "じかん かぎ しげん おも", "sentence_source": "generated"}, {"text": "海の資源を守る活動をする。", "target_word": "資源", "complexity_tier": "T3", "furigana": "うみ しげん まも かつどう", "sentence_source": "generated"}, {"text": "資源の取り合いが問題になる。", "target_word": "資源", "complexity_tier": "T3", "furigana": "しげん と あ もんだい", "sentence_source": "generated"}], "morphological_forms": [{"form": "天然資源", "label": "派生"}, {"form": "資源ごみ", "label": "派生"}, {"form": "人的資源", "label": "派生"}, {"form": "地下資源", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 生活や産業に役立つ物や力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 4 words above tier T2 (max 3): とどまら (Zipf 3.23), 地中 (Zipf 3.61), 封じ込める (Zipf 2.62), 難題 (Zipf 3.21)']::text[], 'f3d7ccd7-38e8-4ed7-83ac-bc82fee685e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37245, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "厳しさや苦しさをやわらげること。", "primary_collocate": null, "pronunciation": "かんわ", "ipa": "kaɴwa", "syllable_count": 3, "sentences": [{"text": "気候変動という地球的危機の緩和に向け、産業セクターにおける排出量の抑制は、持続可能性を担保する上で不可避の責務である。", "target_word": "緩和", "complexity_tier": "T3", "furigana": "かんわ", "sentence_source": "mined"}, {"text": "中央銀行による大規模な資産買入オペレーション、すなわち量的緩和政策は、単なる流動性の供給にとどまらず、国債市場における価格発見機能を歪曲せしめる側面を孕んでいる。", "target_word": "緩和", "complexity_tier": "T3", "furigana": "かんわ", "sentence_source": "mined"}, {"text": "薬で痛みが緩和された。", "target_word": "緩和", "complexity_tier": "T3", "furigana": "くすり いた かんわ", "sentence_source": "generated"}, {"text": "規制の緩和が進んでいる。", "target_word": "緩和", "complexity_tier": "T3", "furigana": "きせい かんわ すす", "sentence_source": "generated"}, {"text": "渋滞を緩和する工夫をした。", "target_word": "緩和", "complexity_tier": "T3", "furigana": "じゅうたい かんわ くふう", "sentence_source": "generated"}, {"text": "緊張の緩和に音楽が役立つ。", "target_word": "緩和", "complexity_tier": "T3", "furigana": "きんちょう かんわ おんがく やくだ", "sentence_source": "generated"}, {"text": "制限が少し緩和された。", "target_word": "緩和", "complexity_tier": "T3", "furigana": "せいげん すこ かんわ", "sentence_source": "generated"}, {"text": "混雑の緩和を目指している。", "target_word": "緩和", "complexity_tier": "T3", "furigana": "こんざつ かんわ めざ", "sentence_source": "generated"}, {"text": "運動はストレスを緩和する。", "target_word": "緩和", "complexity_tier": "T3", "furigana": "うんどう かんわ", "sentence_source": "generated"}, {"text": "暑さを緩和するため木を植えた。", "target_word": "緩和", "complexity_tier": "T3", "furigana": "あつ かんわ き う", "sentence_source": "generated"}], "morphological_forms": [{"form": "緩和する", "label": "派生"}, {"form": "緩和された", "label": "活用"}, {"form": "規制緩和", "label": "派生"}, {"form": "緩和ケア", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 厳しさや苦しさを和らげる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: 6 words above tier T3 (max 3): オペレーション (Zipf 3.24), 量的 (Zipf 3.1), とどまら (Zipf 3.23), 歪曲 (Zipf 3.06), せしめる (Zipf 2.46), 孕ん (Zipf 2.81)']::text[], 'f3d7ccd7-38e8-4ed7-83ac-bc82fee685e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39001, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "担保", "is_correct": true, "explanation": "正解。「担保（たんぽ）」の音。"}, {"text": "田んぼ", "is_correct": false, "explanation": "「田んぼ（たんぼ）」。最後の「ぽ」が濁音「ぼ」になる清濁の違い。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩（さんぽ）」。最初の「た」が「さ」に変わる一モーラ差。"}, {"text": "担架", "is_correct": false, "explanation": "「担架（たんか）」。最後の「ぽ」が「か」に変わる一モーラ差。"}, {"text": "単語", "is_correct": false, "explanation": "「単語（たんご）」。最後の「ぽ」が「ご」に変わる一モーラ差。"}], "explanations": {"担保": "正解。「担保（たんぽ）」の音。", "田んぼ": "「田んぼ（たんぼ）」。最後の「ぽ」が濁音「ぼ」になる清濁の違い。", "散歩": "「散歩（さんぽ）」。最初の「た」が「さ」に変わる一モーラ差。", "担架": "「担架（たんか）」。最後の「ぽ」が「か」に変わる一モーラ差。", "単語": "「単語（たんご）」。最後の「ぽ」が「ご」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "担保"}, "level_3": {"options": [{"text": "担保", "is_correct": true, "explanation": "文脈に合う唯一の語。"}, {"text": "妨害", "is_correct": false, "explanation": "持続可能性を妨げることは責務にならない。"}, {"text": "放棄", "is_correct": false, "explanation": "持続可能性を捨てるのは責務と矛盾する。"}, {"text": "無視", "is_correct": false, "explanation": "持続可能性を無視するのは文意に反する。"}], "explanations": {"担保": "文脈に合う唯一の語。", "妨害": "持続可能性を妨げることは責務にならない。", "放棄": "持続可能性を捨てるのは責務と矛盾する。", "無視": "持続可能性を無視するのは文意に反する。"}, "sentence_index": 0, "correct_answer": "担保"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、窓を担保して部屋の空気を入れかえる。", "explanation": "「開ける」の意味で誤用している。"}, {"text": "彼は毎朝、犬を担保して公園を歩く。", "explanation": "「連れる」の意味で使っており、保証の意味にならない。"}, {"text": "この料理は塩を担保すると味がよくなる。", "explanation": "「加える」の意味で誤用している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99349385-2231-496d-a689-4c46ca1b4bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors,