INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52448, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "領域", "is_correct": true, "explanation": "正解。「領域（りょういき）」の音。"}, {"text": "流域", "is_correct": false, "explanation": "「流域（りゅういき）」。「りょ」が「りゅ」になる一モーラ差。"}, {"text": "療育", "is_correct": false, "explanation": "「療育（りょういく）」。最後の「き」が「く」になる一モーラ差。"}, {"text": "両院", "is_correct": false, "explanation": "「両院（りょういん）」。最後の「き」が「ん」になる一モーラ差。"}], "explanations": {"領域": "正解。「領域（りょういき）」の音。", "流域": "「流域（りゅういき）」。「りょ」が「りゅ」になる一モーラ差。", "療育": "「療育（りょういく）」。最後の「き」が「く」になる一モーラ差。", "両院": "「両院（りょういん）」。最後の「き」が「ん」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "領域"}, "level_3": {"options": [{"text": "領域", "is_correct": true, "explanation": "文脈に合う唯一の語。"}, {"text": "時刻", "is_correct": false, "explanation": "「炭素発生をゼロ化し得ない時刻」は範囲・分野の意味にならない。"}, {"text": "人物", "is_correct": false, "explanation": "製造プロセスの性質について語る文脈に合わない。"}, {"text": "値段", "is_correct": false, "explanation": "「値段においてCCUSが役割を担う」は意味が通らない。"}], "explanations": {"領域": "文脈に合う唯一の語。", "時刻": "「炭素発生をゼロ化し得ない時刻」は範囲・分野の意味にならない。", "人物": "製造プロセスの性質について語る文脈に合わない。", "値段": "「値段においてCCUSが役割を担う」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "領域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この領域はとても甘くておいしい。", "explanation": "食べ物の味の意味で誤用している。"}, {"text": "明日の領域は雨が降るらしい。", "explanation": "「天気」の意味で誤用している。"}, {"text": "彼は領域を三杯も飲んだ。", "explanation": "飲み物の意味で誤用している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99349385-2231-496d-a689-4c46ca1b4bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
