INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35427, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "変動", "is_correct": true, "explanation": "正解。「変動（へんどう）」の音。"}, {"text": "運動", "is_correct": false, "explanation": "「運動（うんどう）」。語頭「へ」が「う」になる一モーラ差。"}, {"text": "返答", "is_correct": false, "explanation": "「返答（へんとう）」。「ど」と「と」の清濁の違い。"}, {"text": "本堂", "is_correct": false, "explanation": "「本堂（ほんどう）」。語頭「へ」が「ほ」になる一モーラ差。"}, {"text": "船頭", "is_correct": false, "explanation": "「船頭（せんどう）」。語頭「へ」が「せ」になる一モーラ差。"}], "explanations": {"変動": "正解。「変動（へんどう）」の音。", "運動": "「運動（うんどう）」。語頭「へ」が「う」になる一モーラ差。", "返答": "「返答（へんとう）」。「ど」と「と」の清濁の違い。", "本堂": "「本堂（ほんどう）」。語頭「へ」が「ほ」になる一モーラ差。", "船頭": "「船頭（せんどう）」。語頭「へ」が「せ」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "変動"}, "level_3": {"options": [{"text": "変動", "is_correct": true, "explanation": "文脈に合う唯一の語。"}, {"text": "帰宅", "is_correct": false, "explanation": "「帰宅する数字」は意味が通らない。"}, {"text": "睡眠", "is_correct": false, "explanation": "「睡眠する数字」は非文。"}, {"text": "料理", "is_correct": false, "explanation": "「料理する数字」は文意に合わない。"}], "explanations": {"変動": "文脈に合う唯一の語。", "帰宅": "「帰宅する数字」は意味が通らない。", "睡眠": "「睡眠する数字」は非文。", "料理": "「料理する数字」は文意に合わない。"}, "sentence_index": 6, "correct_answer": "変動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は毎晩、変動を読んでから寝る。", "explanation": "本の意味で誤用している。"}, {"text": "彼は変動が上手で、よく歌う。", "explanation": "技能・歌の意味で誤用している。"}, {"text": "この変動に座ってください。", "explanation": "家具の意味で誤用している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99349385-2231-496d-a689-4c46ca1b4bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
