INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35427, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "この位置に入る正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「変動を注意が必要」は非文。"}, {"text": "が", "is_correct": false, "explanation": "「変動が注意が必要だ」は非文。"}, {"text": "と", "is_correct": false, "explanation": "「変動と注意」では並列になり文意が崩れる。"}], "correct_answer": "に", "explanations": {"に": "この位置に入る正しい助詞。", "を": "「変動を注意が必要」は非文。", "が": "「変動が注意が必要だ」は非文。", "と": "「変動と注意」では並列になり文意が崩れる。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "と": "listing"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "固定", "is_correct": true, "explanation": "この語義の対義語。"}, {"text": "上昇", "is_correct": false, "explanation": "変動の一部で、対義ではない。"}, {"text": "変更", "is_correct": false, "explanation": "変えることで、対義ではない。"}, {"text": "流動", "is_correct": false, "explanation": "似た意味で、対義ではない。"}], "correct_answer": "固定", "explanations": {"固定": "この語義の対義語。", "上昇": "変動の一部で、対義ではない。", "変更": "変えることで、対義ではない。", "流動": "似た意味で、対義ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99349385-2231-496d-a689-4c46ca1b4bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36337, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "資源", "is_correct": true, "explanation": "正解。「資源（しげん）」の音。"}, {"text": "試験", "is_correct": false, "explanation": "「試験（しけん）」。「げ」が清音「け」になる清濁の違い。"}, {"text": "期限", "is_correct": false, "explanation": "「期限（きげん）」。「し」が「き」になる一モーラ差。"}, {"text": "次元", "is_correct": false, "explanation": "「次元（じげん）」。「し」が濁音「じ」になる清濁の違い。"}], "explanations": {"資源": "正解。「資源（しげん）」の音。", "試験": "「試験（しけん）」。「げ」が清音「け」になる清濁の違い。", "期限": "「期限（きげん）」。「し」が「き」になる一モーラ差。", "次元": "「次元（じげん）」。「し」が濁音「じ」になる清濁の違い。"}, "sentence_index": null, "correct_answer": "資源"}, "level_3": {"options": [{"text": "資源", "is_correct": true, "explanation": "文脈に合う唯一の語。"}, {"text": "気分", "is_correct": false, "explanation": "「炭素を気分へと転換」は意味が通らない。"}, {"text": "年齢", "is_correct": false, "explanation": "炭素を年齢に変えることはできない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気へと転換」は文脈に合わない。"}], "explanations": {"資源": "文脈に合う唯一の語。", "気分": "「炭素を気分へと転換」は意味が通らない。", "年齢": "炭素を年齢に変えることはできない。", "天気": "「天気へと転換」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "資源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "資源がうるさくて眠れなかった。", "explanation": "音を出すものの意味で誤用している。"}, {"text": "彼の資源はとても優しい。", "explanation": "性格の意味で誤用している。"}, {"text": "明日、資源と映画に行く。", "explanation": "人物の意味で誤用している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99349385-2231-496d-a689-4c46ca1b4bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
