INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39301, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "暑いときや運動したときに、皮膚から出る塩分を含んだ水。", "primary_collocate": "かく", "pronunciation": "あせ", "ipa": "ase", "syllable_count": 2, "sentences": [{"text": "汗が滴る中でも、その表情は穏やかだ。", "target_word": "汗", "complexity_tier": "T3", "furigana": "あせ したた ひょうじょう おだ", "sentence_source": "mined"}, {"text": "彼は汗を拭いながら、通行人に丁寧に声をかけていた。", "target_word": "汗", "complexity_tier": "T3", "furigana": "かれ あせ ぬぐ つうこうにん ていねい こえ", "sentence_source": "mined"}, {"text": "走ったら、たくさん汗をかいた。", "target_word": "汗", "complexity_tier": "T3", "furigana": "はし あせ", "sentence_source": "generated"}, {"text": "夏は汗でシャツがぬれてしまう。", "target_word": "汗", "complexity_tier": "T3", "furigana": "なつ あせ", "sentence_source": "generated"}, {"text": "額の汗をタオルでふいた。", "target_word": "汗", "complexity_tier": "T3", "furigana": "ひたい あせ", "sentence_source": "generated"}, {"text": "試合のあと、汗のにおいが気になった。", "target_word": "汗", "complexity_tier": "T3", "furigana": "しあい あせ き", "sentence_source": "generated"}, {"text": "緊張して手に汗をかいている。", "target_word": "汗", "complexity_tier": "T3", "furigana": "きんちょう て あせ", "sentence_source": "generated"}, {"text": "汗が目に入って痛かった。", "target_word": "汗", "complexity_tier": "T3", "furigana": "あせ め はい いた", "sentence_source": "generated"}, {"text": "この服は汗をよく吸う。", "target_word": "汗", "complexity_tier": "T3", "furigana": "ふく あせ す", "sentence_source": "generated"}, {"text": "父は汗だらけで畑から戻った。", "target_word": "汗", "complexity_tier": "T3", "furigana": "ちち あせ はたけ もど", "sentence_source": "generated"}], "morphological_forms": [{"form": "汗っかき", "label": "派生"}, {"form": "汗水", "label": "派生"}, {"form": "冷や汗", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 皮膚から出る塩分を含む水", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e5a87c9-fccb-4b92-9351-f65058cd2fc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37537, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "実際にやってみたり、その場にいたりして身につけた知識や技能。", "primary_collocate": "積む", "pronunciation": "けいけん", "ipa": "keːken", "syllable_count": 4, "sentences": [{"text": "経験豊富な農家は、広大な畑の土壌を丁寧に耕し、野菜の種を植える。", "target_word": "経験", "complexity_tier": "T3", "furigana": "けいけん ほうふ のうか こうだい はたけ どじょう ていねい たがや やさい たね う", "sentence_source": "mined"}, {"text": "この販売活動は、単にお金を稼ぐためだけでなく、自分で計画を立てて実行するという貴重な経験を積むことが目的だった。", "target_word": "経験", "complexity_tier": "T3", "furigana": "はんばい かつどう たん かね かせ じぶん けいかく た じっこう きちょう けいけん つ もくてき", "sentence_source": "mined"}, {"text": "留学はいい経験になった。", "target_word": "経験", "complexity_tier": "T3", "furigana": "りゅうがく けいけん", "sentence_source": "generated"}, {"text": "彼女は教える経験が長い。", "target_word": "経験", "complexity_tier": "T3", "furigana": "かのじょ おし けいけん なが", "sentence_source": "generated"}, {"text": "失敗も大切な経験だと思う。", "target_word": "経験", "complexity_tier": "T3", "furigana": "しっぱい たいせつ けいけん おも", "sentence_source": "generated"}, {"text": "部活で多くの経験を積んだ。", "target_word": "経験", "complexity_tier": "T3", "furigana": "ぶかつ おお けいけん つ", "sentence_source": "generated"}, {"text": "経験のない仕事は少し不安だ。", "target_word": "経験", "complexity_tier": "T3", "furigana": "けいけん しごと すこ ふあん", "sentence_source": "generated"}, {"text": "祖父の経験から学ぶことは多い。", "target_word": "経験", "complexity_tier": "T3", "furigana": "そふ けいけん まな おお", "sentence_source": "generated"}, {"text": "経験を生かして後輩を助けた。", "target_word": "経験", "complexity_tier": "T3", "furigana": "けいけん い こうはい たす", "sentence_source": "generated"}, {"text": "あの日の経験は忘れられない。", "target_word": "経験", "complexity_tier": "T3", "furigana": "ひ けいけん わす", "sentence_source": "generated"}], "morphological_forms": [{"form": "経験する", "label": "派生"}, {"form": "経験者", "label": "派生"}, {"form": "経験的", "label": "派生"}, {"form": "未経験", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 実際に行って得た知識や技能", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 4 words above tier T1 (max 2): 広大 (Zipf 3.81), 土壌 (Zipf 3.83), 耕し (Zipf 2.82), 植える (Zipf 3.15)']::text[], '5e5a87c9-fccb-4b92-9351-f65058cd2fc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51506, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "細かいところまで気をつけて、心をこめて物事を行うようす。礼儀正しいようす。", "primary_collocate": null, "pronunciation": "ていねい", "ipa": "teːneː", "syllable_count": 4, "sentences": [{"text": "経験豊富な農家は、広大な畑の土壌を丁寧に耕し、野菜の種を植える。", "target_word": "丁寧", "complexity_tier": "T3", "furigana": "けいけん ほうふ のうか こうだい はたけ どじょう ていねい たがや やさい たね う", "sentence_source": "mined"}, {"text": "彼は汗を拭いながら、通行人に丁寧に声をかけていた。", "target_word": "丁寧", "complexity_tier": "T3", "furigana": "かれ あせ ぬぐ つうこうにん ていねい こえ", "sentence_source": "mined"}, {"text": "先生は丁寧に説明してくれた。", "target_word": "丁寧", "complexity_tier": "T3", "furigana": "せんせい ていねい せつめい", "sentence_source": "generated"}, {"text": "彼女の字はとても丁寧だ。", "target_word": "丁寧", "complexity_tier": "T3", "furigana": "かのじょ じ ていねい", "sentence_source": "generated"}, {"text": "店員の丁寧な対応がうれしかった。", "target_word": "丁寧", "complexity_tier": "T3", "furigana": "てんいん ていねい たいおう", "sentence_source": "generated"}, {"text": "丁寧な言葉で手紙を書いた。", "target_word": "丁寧", "complexity_tier": "T3", "furigana": "ていねい ことば てがみ か", "sentence_source": "generated"}, {"text": "皿を丁寧に洗っている。", "target_word": "丁寧", "complexity_tier": "T3", "furigana": "さら ていねい あら", "sentence_source": "generated"}, {"text": "兄の仕事はいつも丁寧だ。", "target_word": "丁寧", "complexity_tier": "T3", "furigana": "あに しごと ていねい", "sentence_source": "generated"}, {"text": "丁寧に包んだプレゼントを渡した。", "target_word": "丁寧", "complexity_tier": "T3", "furigana": "ていねい つつ わた", "sentence_source": "generated"}, {"text": "もっと丁寧に話しなさい。", "target_word": "丁寧", "complexity_tier": "T3", "furigana": "ていねい はな", "sentence_source": "generated"}], "morphological_forms": [{"form": "丁寧に", "label": "活用"}, {"form": "丁寧な", "label": "活用"}, {"form": "丁寧だった", "label": "活用"}, {"form": "丁寧さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 細部まで注意し礼儀正しいようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e5a87c9-fccb-4b92-9351-f65058cd2fc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35129, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たくさんの人。いろいろな人たち。", "primary_collocate": null, "pronunciation": "ひとびと", "ipa": "çitobito", "syllable_count": 4, "sentences": [{"text": "冷たくて甘いレモネードは、暑さに疲れた人々の喉を潤し、少年の努力は小さな売上となって確実に実を結んでいった。", "target_word": "人々", "complexity_tier": "T3", "furigana": "つめ あま あつ つか ひとびと のど うるお しょうねん どりょく ちい うりあげ かくじつ み むす", "sentence_source": "mined"}, {"text": "中世ヨーロッパで発展したゴシック様式の大聖堂は、その圧倒的な高さと美しさで人々を魅了しました。", "target_word": "人々", "complexity_tier": "T3", "furigana": "ちゅうせい はってん ようしき だいせいどう あっとうてき たか うつく ひとびと みりょう", "sentence_source": "mined"}, {"text": "駅には多くの人々が集まっていた。", "target_word": "人々", "complexity_tier": "T3", "furigana": "えき おお ひとびと あつ", "sentence_source": "generated"}, {"text": "町の人々はとても親切だ。", "target_word": "人々", "complexity_tier": "T3", "furigana": "まち ひとびと しんせつ", "sentence_source": "generated"}, {"text": "祭りで人々が楽しそうに踊る。", "target_word": "人々", "complexity_tier": "T3", "furigana": "まつ ひとびと たの おど", "sentence_source": "generated"}, {"text": "人々の声が広場に響いた。", "target_word": "人々", "complexity_tier": "T3", "furigana": "ひとびと こえ ひろば ひび", "sentence_source": "generated"}, {"text": "その歌は世界の人々に愛された。", "target_word": "人々", "complexity_tier": "T3", "furigana": "うた せかい ひとびと あい", "sentence_source": "generated"}, {"text": "困っている人々を助けたい。", "target_word": "人々", "complexity_tier": "T3", "furigana": "こま ひとびと たす", "sentence_source": "generated"}, {"text": "雨の中、人々は傘をさして歩く。", "target_word": "人々", "complexity_tier": "T3", "furigana": "あめ なか ひとびと かさ ある", "sentence_source": "generated"}, {"text": "村の人々と一緒に米を作った。", "target_word": "人々", "complexity_tier": "T3", "furigana": "むら ひとびと いっしょ こめ つく", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 多くの人・人たち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e5a87c9-fccb-4b92-9351-f65058cd2fc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39301, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "汗", "is_correct": true, "explanation": "正解：汗（あせ）"}, {"text": "朝", "is_correct": false, "explanation": "朝（あさ）：「せ」が「さ」になる一モーラ差"}, {"text": "雨", "is_correct": false, "explanation": "雨（あめ）：「せ」が「め」になる一モーラ差"}, {"text": "姉", "is_correct": false, "explanation": "姉（あね）：「せ」が「ね」になる一モーラ差"}, {"text": "足", "is_correct": false, "explanation": "足（あし）：「せ」が「し」になる一モーラ差"}, {"text": "畦", "is_correct": false, "explanation": "畦（あぜ）：「せ」と「ぜ」の清濁の違い"}], "explanations": {"汗": "正解：汗（あせ）", "朝": "朝（あさ）：「せ」が「さ」になる一モーラ差", "雨": "雨（あめ）：「せ」が「め」になる一モーラ差", "姉": "姉（あね）：「せ」が「ね」になる一モーラ差", "足": "足（あし）：「せ」が「し」になる一モーラ差", "畦": "畦（あぜ）：「せ」と「ぜ」の清濁の違い"}, "sentence_index": null, "correct_answer": "汗"}, "level_3": {"options": [{"text": "汗", "is_correct": true, "explanation": "汗が滴るのは暑さや緊張のときで自然。"}, {"text": "声", "is_correct": false, "explanation": "意味：声は滴らない。"}, {"text": "風", "is_correct": false, "explanation": "意味：風は滴るものではない。"}, {"text": "影", "is_correct": false, "explanation": "意味：影は液体ではなく滴らない。"}], "explanations": {"汗": "汗が滴るのは暑さや緊張のときで自然。", "声": "意味：声は滴らない。", "風": "意味：風は滴るものではない。", "影": "意味：影は液体ではなく滴らない。"}, "sentence_index": 0, "correct_answer": "汗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この本は汗が多くて読みにくい。", "explanation": "意味：本の文字や内容を汗とは言わない。"}, {"text": "彼は汗を一枚着て出かけた。", "explanation": "意味：汗は衣服ではない。"}, {"text": "試験の汗が発表された。", "explanation": "意味：結果を汗とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b43d77-809b-4ba9-96c7-abddad126418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
