INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39301, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「を」がこの位置で正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「汗が拭う」では汗が動作主になり非文。"}, {"text": "に", "is_correct": false, "explanation": "「汗に拭う」は目的語を示せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「を」がこの位置で正しい助詞。", "が": "「汗が拭う」では汗が動作主になり非文。", "に": "「汗に拭う」は目的語を示せず不自然。", "へ": "方向を表し、目的語にならない。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b43d77-809b-4ba9-96c7-abddad126418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
