INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35129, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人々", "is_correct": true, "explanation": "正解：人々（ひとびと）"}, {"text": "他人事", "is_correct": false, "explanation": "他人事（ひとごと）：三拍目「び」が「ご」になる"}, {"text": "一言", "is_correct": false, "explanation": "一言（ひとこと）：三拍目「び」が「こ」になる"}, {"text": "一時", "is_correct": false, "explanation": "一時（ひととき）：三拍目「び」が「と」になる"}], "explanations": {"人々": "正解：人々（ひとびと）", "他人事": "他人事（ひとごと）：三拍目「び」が「ご」になる", "一言": "一言（ひとこと）：三拍目「び」が「こ」になる", "一時": "一時（ひととき）：三拍目「び」が「と」になる"}, "sentence_index": null, "correct_answer": "人々"}, "level_3": {"options": [{"text": "人々", "is_correct": true, "explanation": "暑さに疲れた人々の喉を潤す。"}, {"text": "机", "is_correct": false, "explanation": "意味：机は暑さに疲れない。"}, {"text": "石", "is_correct": false, "explanation": "意味：石に喉はない。"}, {"text": "道", "is_correct": false, "explanation": "意味：道は疲れない。"}], "explanations": {"人々": "暑さに疲れた人々の喉を潤す。", "机": "意味：机は暑さに疲れない。", "石": "意味：石に喉はない。", "道": "意味：道は疲れない。"}, "sentence_index": 0, "correct_answer": "人々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人々を一本買ってきた。", "explanation": "意味：人々は買う物ではない。"}, {"text": "この人々は甘くておいしい。", "explanation": "意味：人々を食べ物のように扱っている。"}, {"text": "人々がテーブルの上で溶けた。", "explanation": "意味：人々は溶けない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b43d77-809b-4ba9-96c7-abddad126418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
