INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35165, 3, 'prompt1_core', '{"pos": "代名詞", "semantic_class": "function", "definition": "その人自身。話し手や書き手自身のこと。", "primary_collocate": null, "pronunciation": "じぶん", "ipa": "dʑibɯɴ", "syllable_count": 3, "sentences": [{"text": "私にとってこの行為は、自分自身と対話するための重要な手段なのだ。", "target_word": "自分", "complexity_tier": "T3", "furigana": "わたし こうい じぶんじしん たいわ じゅうよう しゅだん", "sentence_source": "mined"}, {"text": "この販売活動は、単にお金を稼ぐためだけでなく、自分で計画を立てて実行するという貴重な経験を積むことが目的だった。", "target_word": "自分", "complexity_tier": "T3", "furigana": "はんばいかつどう たん かね かせ じぶん けいかく た じっこう きちょう けいけん つ もくてき", "sentence_source": "mined"}, {"text": "自分の部屋を掃除した。", "target_word": "自分", "complexity_tier": "T3", "furigana": "じぶん へや そうじ", "sentence_source": "generated"}, {"text": "宿題は自分でやりなさい。", "target_word": "自分", "complexity_tier": "T3", "furigana": "しゅくだい じぶん", "sentence_source": "generated"}, {"text": "自分が正しいと思っている。", "target_word": "自分", "complexity_tier": "T3", "furigana": "じぶん ただ おも", "sentence_source": "generated"}, {"text": "彼は自分のことをよく話す。", "target_word": "自分", "complexity_tier": "T3", "furigana": "かれ じぶん はな", "sentence_source": "generated"}, {"text": "自分を信じることが大切だ。", "target_word": "自分", "complexity_tier": "T3", "furigana": "じぶん しん たいせつ", "sentence_source": "generated"}, {"text": "自分らしく生きたい。", "target_word": "自分", "complexity_tier": "T3", "furigana": "じぶん い", "sentence_source": "generated"}, {"text": "失敗したのは自分のせいだ。", "target_word": "自分", "complexity_tier": "T3", "furigana": "しっぱい じぶん", "sentence_source": "generated"}, {"text": "自分で作った料理はおいしい。", "target_word": "自分", "complexity_tier": "T3", "furigana": "じぶん つく りょうり", "sentence_source": "generated"}], "morphological_forms": [{"form": "自分自身", "label": "派生"}, {"form": "自分たち", "label": "派生"}, {"form": "自分勝手", "label": "派生"}], "register": "plain", "sense_fingerprint": "代名詞 | その人自身を指す言葉", "collocate_grou