INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37357, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "実現しようとして目指すこと。行動のねらい。", "primary_collocate": null, "pronunciation": "もくてき", "ipa": "mokɯteki", "syllable_count": 4, "sentences": [{"text": "犯行の客観的裏付けという目的のため、この緻密な照合作業を経て、初めて不可謬な身元特定が達成されるのである。", "target_word": "目的", "complexity_tier": "T3", "furigana": "はんこう きゃっかんてき うらづ もくてき ちみつ しょうごうさぎょう へ はじ ふかびゅう みもととくてい たっせい", "sentence_source": "mined"}, {"text": "この販売活動は、単にお金を稼ぐためだけでなく、自分で計画を立てて実行するという貴重な経験を積むことが目的だった。", "target_word": "目的", "complexity_tier": "T3", "furigana": "はんばいかつどう たん かね かせ じぶん けいかく た じっこう きちょう けいけん つ もくてき", "sentence_source": "mined"}, {"text": "旅行の目的は何ですか。", "target_word": "目的", "complexity_tier": "T3", "furigana": "りょこう もくてき なん", "sentence_source": "generated"}, {"text": "目的を持って勉強している。", "target_word": "目的", "complexity_tier": "T3", "furigana": "もくてき も べんきょう", "sentence_source": "generated"}, {"text": "会議の目的がわからない。", "target_word": "目的", "complexity_tier": "T3", "furigana": "かいぎ もくてき", "sentence_source": "generated"}, {"text": "彼はついに目的を果たした。", "target_word": "目的", "complexity_tier": "T3", "furigana": "かれ もくてき は", "sentence_source": "generated"}, {"text": "健康のための運動が目的だ。", "target_word": "目的", "complexity_tier": "T3", "furigana": "けんこう うんどう もくてき", "sentence_source": "generated"}, {"text": "目的もなく町を歩いた。", "target_word": "目的", "complexity_tier": "T3", "furigana": "もくてき まち ある", "sentence_source": "generated"}, {"text": "同じ目的の仲間が集まった。", "target_word": "目的", "complexity_tier": "T3", "furigana": "おな もくてき なかま あつ", "sentence_source": "generated"}, {"text": "目的に合った方法を選ぶ。", "target_word": "目的", "complexity_tier": "T3", "furigana": "もくてき あ ほうほう えら", "sentence_source": "generated"}], "morphological_forms": [{"form": "目的地", "label": "派生"}, {"form": "目的語", "label": "派生"}, {"form": "目的意識", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 実現を目指す行動のねらい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: 謬 (Zipf 2.26)']::text[], '5e718609-9871-4bd6-abdf-e563d329fa7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38281, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お金を貸したり借りたり、運用したりする経済活動。", "primary_collocate": null, "pronunciation": "きんゆう", "ipa": "kiɴjɯː", "syllable_count": 4, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "金融", "complexity_tier": "T3", "furigana": "きんゆうせいさく", "sentence_source": "mined"}, {"text": "グローバルな金融市場やサプライチェーンといった社会経済的文脈において、個々の企業や投資家といったミクロな主体による局所的な意思決定は、決して単純な線形モデルでは捉えきれない。", "target_word": "金融", "complexity_tier": "T3", "furigana": "きんゆうしじょう", "sentence_source": "mined"}, {"text": "姉は金融の仕事をしている。", "target_word": "金融", "complexity_tier": "T3", "furigana": "あね きんゆう しごと", "sentence_source": "generated"}, {"text": "金融について学びたい。", "target_word": "金融", "complexity_tier": "T3", "furigana": "きんゆう まな", "sentence_source": "generated"}, {"text": "銀行は金融の中心だ。", "target_word": "金融", "complexity_tier": "T3", "furigana": "ぎんこう きんゆう ちゅうしん", "sentence_source": "generated"}, {"text": "金融の世界は変化が速い。", "target_word": "金融", "complexity_tier": "T3", "furigana": "きんゆう せかい へんか はや", "sentence_source": "generated"}, {"text": "父は金融に詳しい。", "target_word": "金融", "complexity_tier": "T3", "furigana": "ちち きんゆう くわ", "sentence_source": "generated"}, {"text": "金融のニュースを毎日読む。", "target_word": "金融", "complexity_tier": "T3", "furigana": "きんゆう まいにち よ", "sentence_source": "generated"}, {"text": "金融が不安定になっている。", "target_word": "金融", "complexity_tier": "T3", "furigana": "きんゆう ふあんてい", "sentence_source": "generated"}, {"text": "大学で金融を勉強した。", "target_word": "金融", "complexity_tier": "T3", "furigana": "だいがく きんゆう べんきょう", "sentence_source": "generated"}], "morphological_forms": [{"form": "金融機関", "label": "派生"}, {"form": "金融政策", "label": "派生"}, {"form": "金融市場", "la