INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36635, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "必要な量や程度を超えて、多すぎること。", "primary_collocate": null, "pronunciation": "かじょう", "ipa": "kadʑoː", "syllable_count": 3, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "過剰", "complexity_tier": "T3", "furigana": "かじょう", "sentence_source": "mined"}, {"text": "人為的な要因によって大気中に放出された過剰な温室効果ガスは、放射強制力を変化させ、全球規模での気候変動を加速させている。", "target_word": "過剰", "complexity_tier": "T3", "furigana": "かじょう", "sentence_source": "mined"}, {"text": "過剰な期待はしないでほしい。", "target_word": "過剰", "complexity_tier": "T3", "furigana": "かじょう きたい", "sentence_source": "generated"}, {"text": "彼は少し過剰に反応した。", "target_word": "過剰", "complexity_tier": "T3", "furigana": "かれ すこ かじょう はんのう", "sentence_source": "generated"}, {"text": "塩分のとりすぎは過剰だ。", "target_word": "過剰", "complexity_tier": "T3", "furigana": "えんぶん かじょう", "sentence_source": "generated"}, {"text": "過剰な包装をやめよう。", "target_word": "過剰", "complexity_tier": "T3", "furigana": "かじょう ほうそう", "sentence_source": "generated"}, {"text": "この店は商品が過剰になった。", "target_word": "過剰", "complexity_tier": "T3", "furigana": "みせ しょうひん かじょう", "sentence_source": "generated"}, {"text": "過剰に心配する必要はない。", "target_word": "過剰", "complexity_tier": "T3", "furigana": "かじょう しんぱい ひつよう", "sentence_source": "generated"}, {"text": "練習が過剰で体を痛めた。", "target_word": "過剰", "complexity_tier": "T3", "furigana": "れんしゅう かじょう からだ いた", "sentence_source": "generated"}, {"text": "過剰な運動は体に悪い。", "target_word": "過剰", "complexity_tier": "T3", "furigana": "かじょう うんどう からだ わる", "sentence_source": "generated"}], "morphological_forms": [{"form": "過剰な", "label": "活用"}, {"form": "過剰に", "label": "活用"}, {"form": "過剰だ", "label": "活用"}, {"form": "過剰さ", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 必要な程度を超えて多すぎる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: スタグフレーション (Zipf 1.93)']::text[], '5e718609-9871-4bd6-abdf-e563d329fa7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51926, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "立てる", "is_correct": true, "explanation": "正解：音声どおりの語"}, {"text": "食べる", "is_correct": false, "explanation": "たべる：二拍目「て」が「べ」に変わる一モーラ差"}, {"text": "当てる", "is_correct": false, "explanation": "あてる：一拍目「た」が「あ」に変わる一モーラ差"}, {"text": "捨てる", "is_correct": false, "explanation": "すてる：一拍目「た」が「す」に変わる一モーラ差"}, {"text": "果てる", "is_correct": false, "explanation": "はてる：一拍目「た」が「は」に変わる一モーラ差"}], "explanations": {"立てる": "正解：音声どおりの語", "食べる": "たべる：二拍目「て」が「べ」に変わる一モーラ差", "当てる": "あてる：一拍目「た」が「あ」に変わる一モーラ差", "捨てる": "すてる：一拍目「た」が「す」に変わる一モーラ差", "果てる": "はてる：一拍目「た」が「は」に変わる一モーラ差"}, "sentence_index": null, "correct_answer": "立てる"}, "level_3": {"options": [{"text": "立て", "is_correct": true, "explanation": "文脈に合う正しい語"}, {"text": "閉じ", "is_correct": false, "explanation": "連語：「歯を閉じる」とは言わない"}, {"text": "抜き", "is_correct": false, "explanation": "意味：歯を抜いてから食べる場面ではない"}, {"text": "見せ", "is_correct": false, "explanation": "項構造：「表皮に歯を見せる」は格の取り方が合わない"}], "explanations": {"立て": "文脈に合う正しい語", "閉じ": "連語：「歯を閉じる」とは言わない", "抜き": "意味：歯を抜いてから食べる場面ではない", "見せ": "項構造：「表皮に歯を見せる」は格の取り方が合わない"}, "sentence_index": 0, "correct_answer": "立て"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄は毎朝、一日の予定に立てている。", "explanation": "助詞の混同：予定は目的語なので「を」が必要"}, {"text": "兄は来週、一日の予定を立てた。", "explanation": "アスペクトの誤り：「来週」と過去形「た」が矛盾する"}, {"text": "兄は毎朝、ご飯を立てている。", "explanation": "意味の誤り：ご飯は計画のように「立てる」ものではない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8819faf8-cf25-4d9e-a1be-e3e0d7121491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, gen