INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36139, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "長い歴史の中で受け継がれてきた、特定の社会や集団に特有の習慣や考え方。", "primary_collocate": null, "pronunciation": "でんとう", "ipa": "deɴtoː", "syllable_count": 4, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "しかし現代ファッションの文脈では、この伝統的な職人技はデジタルデザインという新たなパラダイムと衝突し、あるいは融合しつつある。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "この祭りには長い伝統がある。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "まつ なが でんとう", "sentence_source": "generated"}, {"text": "村の伝統を守りたい。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "むら でんとう まも", "sentence_source": "generated"}, {"text": "伝統は大切にするべきだ。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "でんとう たいせつ", "sentence_source": "generated"}, {"text": "祖母が伝統の料理を作った。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "そぼ でんとう りょうり つく", "sentence_source": "generated"}, {"text": "この学校の伝統は合唱です。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "がっこう でんとう がっしょう", "sentence_source": "generated"}, {"text": "新しい伝統を作っている。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "あたら でんとう つく", "sentence_source": "generated"}, {"text": "伝統的な家に住んでいる。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "でんとうてき いえ す", "sentence_source": "generated"}, {"text": "古い伝統が消えつつある。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "ふる でんとう き", "sentence_source": "generated"}], "morphological_forms": [{"form": "伝統的", "label": "派生"}, {"form": "伝統文化", "label": "派生"}, {"form": "伝統行事", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 昔から受け継がれた習慣や考え方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: スタグフレーション (Zipf 1.93)']::text[], 'dd6db8c8-4352-4a02-a6c5-6cd14ceeb388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39471, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "まんなかの位置や部分。", "primary_collocate": null, "pronunciation": "ちゅうおう", "ipa": "tɕɯːoː", "syllable_count": 4, "sentences": [{"text": "中央銀行による大規模な資産買入オペレーション、すなわち量的緩和政策は、単なる流動性の供給にとどまらず、国債市場における価格発見機能を歪曲せしめる側面を孕んでいる。", "target_word": "中央", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "私はそのクレヨンで、紙の中央に大きな丸い太陽を描き始めた。", "target_word": "中央", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "部屋の中央にテーブルがある。", "target_word": "中央", "complexity_tier": "T3", "furigana": "へや ちゅうおう", "sentence_source": "generated"}, {"text": "中央に立ってください。", "target_word": "中央", "complexity_tier": "T3", "furigana": "ちゅうおう た", "sentence_source": "generated"}, {"text": "公園の中央には池がある。", "target_word": "中央", "complexity_tier": "T3", "furigana": "こうえん ちゅうおう いけ", "sentence_source": "generated"}, {"text": "彼は舞台の中央で歌った。", "target_word": "中央", "complexity_tier": "T3", "furigana": "かれ ぶたい ちゅうおう うた", "sentence_source": "generated"}, {"text": "中央の席に座りたい。", "target_word": "中央", "complexity_tier": "T3", "furigana": "ちゅうおう せき すわ", "sentence_source": "generated"}, {"text": "町の中央を川が流れている。", "target_word": "中央", "complexity_tier": "T3", "furigana": "まち ちゅうおう かわ なが", "sentence_source": "generated"}, {"text": "中央は人が多くて歩けない。", "target_word": "中央", "complexity_tier": "T3", "furigana": "ちゅうおう ひと おお ある", "sentence_source": "generated"}, {"text": "円の中央に点を書いた。", "target_word": "中央", "complexity_tier": "T3", "furigana": "えん ちゅうおう てん か", "sentence_source": "generated"}], "morphological_forms": [{"form": "中央部", "label": "派生"}, {"form": "中央線", "label": "派生"}, {"form": "中央口", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | まんなかの位置や部分", "collocate_grounding": {"status": "no_source", "reason": "no co