INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52040, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "表面や名目ではなく、実際に存在する本当の姿や中身。", "primary_collocate": null, "pronunciation": "じったい", "ipa": "dʑittai", "syllable_count": 4, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "実体", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "無機質な素材が自律的実体へと昇華する奇跡を、自らの双手で紡ぎ出す営み。", "target_word": "実体", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "その会社には実体がない。", "target_word": "実体", "complexity_tier": "T3", "furigana": "かいしゃ じったい", "sentence_source": "generated"}, {"text": "幽霊の実体は影だった。", "target_word": "実体", "complexity_tier": "T3", "furigana": "ゆうれい じったい かげ", "sentence_source": "generated"}, {"text": "噂の実体を調べている。", "target_word": "実体", "complexity_tier": "T3", "furigana": "うわさ じったい しら", "sentence_source": "generated"}, {"text": "実体のない不安に悩む。", "target_word": "実体", "complexity_tier": "T3", "furigana": "じったい ふあん なや", "sentence_source": "generated"}, {"text": "実体が見えないのは怖い。", "target_word": "実体", "complexity_tier": "T3", "furigana": "じったい み こわ", "sentence_source": "generated"}, {"text": "彼はその実体を知らない。", "target_word": "実体", "complexity_tier": "T3", "furigana": "かれ じったい し", "sentence_source": "generated"}, {"text": "実体を確かめてから話そう。", "target_word": "実体", "complexity_tier": "T3", "furigana": "じったい たし はな", "sentence_source": "generated"}, {"text": "夢には実体がないと思う。", "target_word": "実体", "complexity_tier": "T3", "furigana": "ゆめ じったい おも", "sentence_source": "generated"}], "morphological_forms": [{"form": "実体的", "label": "派生"}, {"form": "実体経済", "label": "派生"}, {"form": "実体化", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 実際に存在する本当の姿や中身", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: スタグフレーション (Zipf 1.93)','sentence 1 above tier T3: 4 words above tier T3 (max 3): 無機質 (Zipf 2.84), 昇華 (Zipf 3.35), 紡ぎ (Zipf 2.82), 営み (Zipf 3.27)']::text[], 'dd6db8c8-4352-4a02-a6c5-6cd14ceeb388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36603, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある現象や動作が起こるための、内部の仕組みや過程。", "primary_collocate": null, "pronunciation": "めかにずむ", "ipa": "mekanizɯmɯ", "syllable_count": 5, "sentences": [{"text": "イールドカーブ・コントロールの下では、市場メカニズムを通じた適正なリスクプレミアムの形成が阻害され、結果として財政の持続可能性を担保するべき債務の価格的シグナルが鈍磨する懸念が拭えない。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "さらに、こうした資金供給メカニズムは、エコシステム全体に好循環をもたらす。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "時計のメカニズムを調べた。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "とけい しら", "sentence_source": "generated"}, {"text": "地震のメカニズムを学ぶ。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "じしん まな", "sentence_source": "generated"}, {"text": "そのメカニズムはまだ謎だ。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "なぞ", "sentence_source": "generated"}, {"text": "メカニズムが分かると面白い。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "わ おもしろ", "sentence_source": "generated"}, {"text": "雨が降るメカニズムを話す。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "あめ ふ はな", "sentence_source": "generated"}, {"text": "体のメカニズムは複雑だ。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "からだ ふくざつ", "sentence_source": "generated"}, {"text": "先生がメカニズムを説明した。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "せんせい せつめい", "sentence_source": "generated"}, {"text": "このメカニズムを知りたい。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "し", "sentence_source": "generated"}], "morphological_forms": [{"form": "市場メカニズム", "label": "派生"}, {"form": "防御メカニズム", "label": "派生"}, {"form": "発生メカニズム", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事が起こる内部の仕組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6db8c8-4352-4a02-a6c5-6cd14ceeb388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37605, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "位置や方向が、高いところから見て低い方。", "primary_collocate": null, "pronunciation": "した", "ipa": "ɕita", "syllable_count": 2, "sentences": [{"text": "イールドカーブ・コントロールの下では、市場メカニズムを通じた適正なリスクプレミアムの形成が阻害され、結果として財政の持続可能性を担保するべき債務の価格的シグナルが鈍磨する懸念が拭えない。", "target_word": "下", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "教師の指示のもと、静寂を保ちつつも頭脳をフル回転させる学習の時間。", "target_word": "もと", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "猫が机の下で寝ている。", "target_word": "下", "complexity_tier": "T3", "furigana": "ねこ つくえ した ね", "sentence_source": "generated"}, {"text": "下を見ると怖い。", "target_word": "下", "complexity_tier": "T3", "furigana": "した み こわ", "sentence_source": "generated"}, {"text": "箱の下に手紙があった。", "target_word": "下", "complexity_tier": "T3", "furigana": "はこ した てがみ", "sentence_source": "generated"}, {"text": "下の階に友達が住んでいる。", "target_word": "下", "complexity_tier": "T3", "furigana": "した かい ともだち す", "sentence_source": "generated"}, {"text": "ボールが下に落ちた。", "target_word": "下", "complexity_tier": "T3", "furigana": "お", "sentence_source": "generated"}, {"text": "木の下で本を読んだ。", "target_word": "下", "complexity_tier": "T3", "furigana": "き した ほん よ", "sentence_source": "generated"}, {"text": "下から声が聞こえる。", "target_word": "下", "complexity_tier": "T3", "furigana": "した こえ き", "sentence_source": "generated"}, {"text": "下の引き出しを開けて。", "target_word": "下", "complexity_tier": "T3", "furigana": "した ひ だ あ", "sentence_source": "generated"}], "morphological_forms": [{"form": "下着", "label": "派生"}, {"form": "下見", "label": "派生"}, {"form": "下向き", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 低い方の位置や方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'