INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35445, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を知覚し、理解する心の働き。また、その内容。", "primary_collocate": null, "pronunciation": "にんしき", "ipa": "ɲiɴɕiki", "syllable_count": 4, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "認識", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "すなわち、技術的革新は単なる効率化の道具にとどまらず、教育の公平性と個別最適化を両立させる新たな認識論的枠組みを構築し得るという点に、その本質的な教育的示唆が存すると言えよう。", "target_word": "認識", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "問題の大きさを認識した。", "target_word": "認識", "complexity_tier": "T3", "furigana": "もんだい おお にんしき", "sentence_source": "generated"}, {"text": "彼の認識は間違っている。", "target_word": "認識", "complexity_tier": "T3", "furigana": "かれ にんしき まちが", "sentence_source": "generated"}, {"text": "危険を認識していなかった。", "target_word": "認識", "complexity_tier": "T3", "furigana": "きけん にんしき", "sentence_source": "generated"}, {"text": "二人の認識が違うようだ。", "target_word": "認識", "complexity_tier": "T3", "furigana": "ふたり にんしき ちが", "sentence_source": "generated"}, {"text": "みんなで認識を合わせよう。", "target_word": "認識", "complexity_tier": "T3", "furigana": "にんしき あ", "sentence_source": "generated"}, {"text": "自分の弱さを認識できた。", "target_word": "認識", "complexity_tier": "T3", "furigana": "じぶん よわ にんしき", "sentence_source": "generated"}, {"text": "その認識は正しいと思う。", "target_word": "認識", "complexity_tier": "T3", "furigana": "にんしき ただ おも", "sentence_source": "generated"}, {"text": "環境への認識が高まった。", "target_word": "認識", "complexity_tier": "T3", "furigana": "かんきょう にんしき たか", "sentence_source": "generated"}], "morphological_forms": [{"form": "認識する", "label": "活用"}, {"form": "認識した", "label": "活用"}, {"form": "認識論", "label": "派生"}, {"form": "再認識", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事を見分け理解すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: スタグフレーション (Zipf 1.93)']::text[], 'dd6db8c8-4352-4a02-a6c5-6cd14ceeb388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36139, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "伝統", "is_correct": true, "explanation": "正解。読みは「でんとう」。"}, {"text": "銭湯", "is_correct": false, "explanation": "読みは「せんとう」。「で」が「せ」に変わる一モーラ差。"}, {"text": "検討", "is_correct": false, "explanation": "読みは「けんとう」。「で」が「け」に変わる一モーラ差。"}, {"text": "転倒", "is_correct": false, "explanation": "読みは「てんとう」。「で」が「て」に変わる一モーラ差。"}, {"text": "電光", "is_correct": false, "explanation": "読みは「でんこう」。「と」が「こ」に変わる一モーラ差。"}, {"text": "円筒", "is_correct": false, "explanation": "読みは「えんとう」。「で」が「え」に変わる一モーラ差。"}], "explanations": {"伝統": "正解。読みは「でんとう」。", "銭湯": "読みは「せんとう」。「で」が「せ」に変わる一モーラ差。", "検討": "読みは「けんとう」。「で」が「け」に変わる一モーラ差。", "転倒": "読みは「てんとう」。「で」が「て」に変わる一モーラ差。", "電光": "読みは「でんこう」。「と」が「こ」に変わる一モーラ差。", "円筒": "読みは「えんとう」。「で」が「え」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "伝統"}, "level_3": {"options": [{"text": "伝統", "is_correct": true, "explanation": "「非伝統的な金融政策」で、従来の慣習的なやり方ではない政策を表す。"}, {"text": "天気", "is_correct": false, "explanation": "「非天気的な政策」という語は存在しない。"}, {"text": "階段", "is_correct": false, "explanation": "政策を「非階段的」と形容することはできない。"}, {"text": "果物", "is_correct": false, "explanation": "「非果物的な金融政策」は意味が通らない。"}], "explanations": {"伝統": "「非伝統的な金融政策」で、従来の慣習的なやり方ではない政策を表す。", "天気": "「非天気的な政策」という語は存在しない。", "階段": "政策を「非階段的」と形容することはできない。", "果物": "「非果物的な金融政策」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "伝統"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "伝統を食べたらおいしかった。", "explanation": "伝統は食べ物ではないので「食べる」の対象にならない。"}, {"text": "机の上に伝統が三つ置いてある。", "explanation": "伝統は物ではなく、置いたり数えたりできない。"}, {"text": "昨日買った伝統がもう壊れた。", "explanation": "伝統は買ったり壊れたりする品物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c95e541-ea0e-452e-8900-36e3506d76bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCL