INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36139, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「パラダイムと衝突する」で、衝突の相手を示す。"}, {"text": "を", "is_correct": false, "explanation": "「衝突する」は自動詞で、目的語の「を」はとらない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表し、衝突の相手を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表し、「〜から衝突する」は不自然。"}], "correct_answer": "と", "explanations": {"と": "「パラダイムと衝突する」で、衝突の相手を示す。", "を": "「衝突する」は自動詞で、目的語の「を」はとらない。", "で": "手段・場所を表し、衝突の相手を示せない。", "から": "起点を表し、「〜から衝突する」は不自然。"}, "error_tags": {"を": "object_marking", "で": "instrument", "から": "source_vs_goal"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "革新", "is_correct": true, "explanation": "古いしきたりを守る「伝統」に対し、新しく改める「革新」は対義語。"}, {"text": "習慣", "is_correct": false, "explanation": "伝統に近い意味で、対義ではない。"}, {"text": "文化", "is_correct": false, "explanation": "伝統と同じ分野の語で、対義関係にない。"}, {"text": "歴史", "is_correct": false, "explanation": "伝統と関わりが深いが、反対の意味ではない。"}], "correct_answer": "革新", "explanations": {"革新": "古いしきたりを守る「伝統」に対し、新しく改める「革新」は対義語。", "習慣": "伝統に近い意味で、対義ではない。", "文化": "伝統と同じ分野の語で、対義関係にない。", "歴史": "伝統と関わりが深いが、反対の意味ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c95e541-ea0e-452e-8900-36e3506d76bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
