INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39471, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中央", "is_correct": true, "explanation": "正解。読みは「ちゅうおう」。"}, {"text": "中東", "is_correct": false, "explanation": "読みは「ちゅうとう」。「お」が「と」に変わる一モーラ差。"}, {"text": "中庸", "is_correct": false, "explanation": "読みは「ちゅうよう」。「お」が「よ」に変わる一モーラ差。"}, {"text": "抽象", "is_correct": false, "explanation": "読みは「ちゅうしょう」。「お」が「しょ」に変わる一モーラ差。"}, {"text": "中興", "is_correct": false, "explanation": "読みは「ちゅうこう」。「お」が「こ」に変わる一モーラ差。"}], "explanations": {"中央": "正解。読みは「ちゅうおう」。", "中東": "読みは「ちゅうとう」。「お」が「と」に変わる一モーラ差。", "中庸": "読みは「ちゅうよう」。「お」が「よ」に変わる一モーラ差。", "抽象": "読みは「ちゅうしょう」。「お」が「しょ」に変わる一モーラ差。", "中興": "読みは「ちゅうこう」。「お」が「こ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "中央"}, "level_3": {"options": [{"text": "中央", "is_correct": true, "explanation": "「中央銀行」で、国の金融の中心となる銀行を表す。"}, {"text": "海岸", "is_correct": false, "explanation": "「海岸銀行」は国の金融政策を担う銀行の名ではない。"}, {"text": "台所", "is_correct": false, "explanation": "「台所銀行」という語は存在しない。"}, {"text": "屋根", "is_correct": false, "explanation": "「屋根銀行」は意味が通らない。"}], "explanations": {"中央": "「中央銀行」で、国の金融の中心となる銀行を表す。", "海岸": "「海岸銀行」は国の金融政策を担う銀行の名ではない。", "台所": "「台所銀行」という語は存在しない。", "屋根": "「屋根銀行」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "中央"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この中央はとても甘い。", "explanation": "中央は位置を表す語で、味を持たない。"}, {"text": "中央を二枚買ってきた。", "explanation": "中央は品物ではなく、買ったり枚で数えたりできない。"}, {"text": "昨日、中央と話した。", "explanation": "中央は人ではないので話し相手にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c95e541-ea0e-452e-8900-36e3506d76bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
