INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52040, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "実体", "is_correct": true, "explanation": "正解。読みは「じったい」。"}, {"text": "絶対", "is_correct": false, "explanation": "読みは「ぜったい」。「じ」が「ぜ」に変わる一モーラ差。"}, {"text": "熱帯", "is_correct": false, "explanation": "読みは「ねったい」。「じ」が「ね」に変わる一モーラ差。"}, {"text": "一体", "is_correct": false, "explanation": "読みは「いったい」。「じ」が「い」に変わる一モーラ差。"}, {"text": "実際", "is_correct": false, "explanation": "読みは「じっさい」。「た」が「さ」に変わる一モーラ差。"}], "explanations": {"実体": "正解。読みは「じったい」。", "絶対": "読みは「ぜったい」。「じ」が「ぜ」に変わる一モーラ差。", "熱帯": "読みは「ねったい」。「じ」が「ね」に変わる一モーラ差。", "一体": "読みは「いったい」。「じ」が「い」に変わる一モーラ差。", "実際": "読みは「じっさい」。「た」が「さ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "実体"}, "level_3": {"options": [{"text": "実体", "is_correct": true, "explanation": "「実体経済」で、お金の取引ではなく実際の生産や消費の経済を表す。"}, {"text": "夕食", "is_correct": false, "explanation": "「夕食経済」という語はない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "「鉛筆経済」は意味が通らない。"}, {"text": "背中", "is_correct": false, "explanation": "「背中経済」は存在しない語。"}], "explanations": {"実体": "「実体経済」で、お金の取引ではなく実際の生産や消費の経済を表す。", "夕食": "「夕食経済」という語はない。", "鉛筆": "「鉛筆経済」は意味が通らない。", "背中": "「背中経済」は存在しない語。"}, "sentence_index": 0, "correct_answer": "実体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "実体をコップに注いで飲んだ。", "explanation": "実体は液体ではなく、注いだり飲んだりできない。"}, {"text": "実体が三匹庭で遊んでいる。", "explanation": "実体は動物ではなく、匹で数えない。"}, {"text": "実体を着て出かけた。", "explanation": "実体は服ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c95e541-ea0e-452e-8900-36e3506d76bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
