INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52040, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "「実体へと昇華する」で、変化の行き着く先を示す。"}, {"text": "を", "is_correct": false, "explanation": "「昇華する」の変化の結果を目的語では表せない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表し、変化先を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表し、変化の着点と逆になる。"}], "correct_answer": "へ", "explanations": {"へ": "「実体へと昇華する」で、変化の行き着く先を示す。", "を": "「昇華する」の変化の結果を目的語では表せない。", "で": "手段・場所を表し、変化先を示せない。", "から": "起点を表し、変化の着点と逆になる。"}, "error_tags": {"を": "object_marking", "で": "instrument", "から": "source_vs_goal"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "名目", "is_correct": true, "explanation": "中身の「実体」に対し、名前だけの「名目」は対義語。"}, {"text": "中身", "is_correct": false, "explanation": "実体に近い意味で、対義ではない。"}, {"text": "本質", "is_correct": false, "explanation": "実体と近い意味の語。"}, {"text": "現実", "is_correct": false, "explanation": "実体と同じ側の意味で、反対ではない。"}], "correct_answer": "名目", "explanations": {"名目": "中身の「実体」に対し、名前だけの「名目」は対義語。", "中身": "実体に近い意味で、対義ではない。", "本質": "実体と近い意味の語。", "現実": "実体と同じ側の意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c95e541-ea0e-452e-8900-36e3506d76bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52040, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "実体", "is_correct": true, "explanation": "正解。読みは「じったい」。"}, {"text": "失態", "is_correct": false, "explanation": "読みは「しったい」。「じ」が「し」（清濁）に変わる一モーラ差。"}, {"text": "接待", "is_correct": false, "explanation": "読みは「せったい」。「じ」が「せ」に変わる一モーラ差。"}, {"text": "一帯", "is_correct": false, "explanation": "読みは「いったい」。「じ」が「い」に変わる一モーラ差。"}], "explanations": {"実体": "正解。読みは「じったい」。", "失態": "読みは「しったい」。「じ」が「し」（清濁）に変わる一モーラ差。", "接待": "読みは「せったい」。「じ」が「せ」に変わる一モーラ差。", "一帯": "読みは「いったい」。「じ」が「い」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "実体"}, "level_3": {"options": [{"text": "実体", "is_correct": true, "explanation": "本当の姿や中身が見えないことを表す。"}, {"text": "匂い", "is_correct": false, "explanation": "匂いはもともと目に見えないもので、「見えないのが怖い」は意味をなさない。"}, {"text": "味", "is_correct": false, "explanation": "味は目で見るものではなく、文意が通らない。"}, {"text": "昨日", "is_correct": false, "explanation": "「昨日が見えない」は意味が通らない。"}], "explanations": {"実体": "本当の姿や中身が見えないことを表す。", "匂い": "匂いはもともと目に見えないもので、「見えないのが怖い」は意味をなさない。", "味": "味は目で見るものではなく、文意が通らない。", "昨日": "「昨日が見えない」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "実体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夢には実体を三杯入れた。", "explanation": "実体は液体ではなく、杯で数えない。"}, {"text": "実体が夢の中で走っている。", "explanation": "実体は生き物ではなく、走らない。"}, {"text": "実体で夢の絵を描いた。", "explanation": "実体は絵の道具ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c95e541-ea0e-452e-8900-36e3506d76bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
