INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36603, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "メカニズム", "is_correct": true, "explanation": "正解。読みは「めかにずむ」。"}, {"text": "エゴイズム", "is_correct": false, "explanation": "読みは「えごいずむ」。前半「めかに」が「えごい」が違う。"}, {"text": "ヒロイズム", "is_correct": false, "explanation": "読みは「ひろいずむ」。前半「めかに」が「ひろい」が違う。"}, {"text": "メカトロニクス", "is_correct": false, "explanation": "読みは「めかとろにくす」。「めか」以降が違う。"}], "explanations": {"メカニズム": "正解。読みは「めかにずむ」。", "エゴイズム": "読みは「えごいずむ」。前半「めかに」が「えごい」が違う。", "ヒロイズム": "読みは「ひろいずむ」。前半「めかに」が「ひろい」が違う。", "メカトロニクス": "読みは「めかとろにくす」。「めか」以降が違う。"}, "sentence_index": null, "correct_answer": "メカニズム"}, "level_3": {"options": [{"text": "メカニズム", "is_correct": true, "explanation": "雨が降る仕組みを表す。"}, {"text": "パジャマ", "is_correct": false, "explanation": "「雨が降るパジャマ」は意味が通らない。"}, {"text": "フォーク", "is_correct": false, "explanation": "「雨が降るフォークを話す」は不自然。"}, {"text": "ポスト", "is_correct": false, "explanation": "「雨が降るポストを話す」は意味をなさない。"}], "explanations": {"メカニズム": "雨が降る仕組みを表す。", "パジャマ": "「雨が降るパジャマ」は意味が通らない。", "フォーク": "「雨が降るフォークを話す」は不自然。", "ポスト": "「雨が降るポストを話す」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "メカニズム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このメカニズムを食べたい。", "explanation": "メカニズムは食べ物ではない。"}, {"text": "メカニズムが庭で寝ている。", "explanation": "メカニズムは生き物ではなく、寝ない。"}, {"text": "このメカニズムを三枚買った。", "explanation": "メカニズムは品物ではなく、枚で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c95e541-ea0e-452e-8900-36e3506d76bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
