INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37605, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "下", "is_correct": true, "explanation": "正解。読みは「した」。"}, {"text": "板", "is_correct": false, "explanation": "読みは「いた」。「し」が「い」に変わる一モーラ差。"}, {"text": "肩", "is_correct": false, "explanation": "読みは「かた」。「し」が「か」に変わる一モーラ差。"}, {"text": "島", "is_correct": false, "explanation": "読みは「しま」。「た」が「ま」に変わる一モーラ差。"}, {"text": "蓋", "is_correct": false, "explanation": "読みは「ふた」。「し」が「ふ」に変わる一モーラ差。"}, {"text": "鹿", "is_correct": false, "explanation": "読みは「しか」。「た」が「か」に変わる一モーラ差。"}], "explanations": {"下": "正解。読みは「した」。", "板": "読みは「いた」。「し」が「い」に変わる一モーラ差。", "肩": "読みは「かた」。「し」が「か」に変わる一モーラ差。", "島": "読みは「しま」。「た」が「ま」に変わる一モーラ差。", "蓋": "読みは「ふた」。「し」が「ふ」に変わる一モーラ差。", "鹿": "読みは「しか」。「た」が「か」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "下"}, "level_3": {"options": [{"text": "下", "is_correct": true, "explanation": "「コントロールの下では」で、その支配や影響のもとにある状態を表す。"}, {"text": "横", "is_correct": false, "explanation": "「コントロールの横では」は意味が通らない。"}, {"text": "裏", "is_correct": false, "explanation": "「コントロールの裏では」は別の意味になり文脈に合わない。"}, {"text": "外", "is_correct": false, "explanation": "「コントロールの外では」では支配を受けないことになり、阻害の文脈と合わない。"}], "explanations": {"下": "「コントロールの下では」で、その支配や影響のもとにある状態を表す。", "横": "「コントロールの横では」は意味が通らない。", "裏": "「コントロールの裏では」は別の意味になり文脈に合わない。", "外": "「コントロールの外では」では支配を受けないことになり、阻害の文脈と合わない。"}, "sentence_index": 0, "correct_answer": "下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下を食べると怖い。", "explanation": "「下」は位置で、食べる対象ではない。"}, {"text": "下が笑うと怖い。", "explanation": "「下」は人ではないので笑わない。"}, {"text": "下を二本買うと怖い。", "explanation": "「下」は品物ではなく、本で数えられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c95e541-ea0e-452e-8900-36e3506d76bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
