INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35707, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "商品やサービスを買うときに払うお金の量。値段。", "primary_collocate": null, "pronunciation": "かかく", "ipa": "kakakɯ", "syllable_count": 3, "sentences": [{"text": "中央銀行による大規模な資産買入オペレーション、すなわち量的緩和政策は、単なる流動性の供給にとどまらず、国債市場における価格発見機能を歪曲せしめる側面を孕んでいる。", "target_word": "価格", "complexity_tier": "T3", "furigana": "かかく", "sentence_source": "mined"}, {"text": "イールドカーブ・コントロールの下では、市場メカニズムを通じた適正なリスクプレミアムの形成が阻害され、結果として財政の持続可能性を担保するべき債務の価格的シグナルが鈍磨する懸念が拭えない。", "target_word": "価格", "complexity_tier": "T3", "furigana": "かかく", "sentence_source": "mined"}, {"text": "この憧れの感情は、やがてグローバルな大衆向けブランドによって巧妙に咀嚼され、誰もが手が届く価格帯へと昇華されるのだ。", "target_word": "価格", "complexity_tier": "T3", "furigana": "かかく", "sentence_source": "mined"}, {"text": "この店の野菜は価格が安い。", "target_word": "価格", "complexity_tier": "T3", "furigana": "かかく", "sentence_source": "generated"}, {"text": "新しいゲームの価格を調べている。", "target_word": "価格", "complexity_tier": "T3", "furigana": "かかく", "sentence_source": "generated"}, {"text": "ガソリンの価格が上がってきた。", "target_word": "価格", "complexity_tier": "T3", "furigana": "かかく", "sentence_source": "generated"}, {"text": "価格の高い服はあまり買えない。", "target_word": "価格", "complexity_tier": "T3", "furigana": "かかく", "sentence_source": "generated"}, {"text": "二つの店で価格を比べてみた。", "target_word": "価格", "complexity_tier": "T3", "furigana": "かかく", "sentence_source": "generated"}, {"text": "この本の価格は千円です。", "target_word": "価格", "complexity_tier": "T3", "furigana": "かかく", "sentence_source": "generated"}, {"text": "価格が下がるのを待っている。", "target_word": "価格", "complexity_tier": "T3", "furigana": "かかく", "sentence_source": "generated"}], "morphological_forms": [{"form": "価格表", "label": "派生"}, {"form": "低価格", "label": "派生"}, {"form": "価格帯", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 商品を買うときに払うお金の量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: せしめる (Zipf 2.46)']::text[], '5afa0d7c-1a23-48fc-bd1f-216f8be8e73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
