INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51856, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "他にはない、そのものだけが持っていること。", "primary_collocate": null, "pronunciation": "どくじ", "ipa": "dokɯdʑi", "syllable_count": 3, "sentences": [{"text": "生徒たちが繊維の纹理に想いを込め、独自のプロットを紡ぎ出すとき、それは単なる被服製作ではなく、記号的な自己主張の確立へと昇華されるのである。", "target_word": "独自", "complexity_tier": "T3", "furigana": "どくじ", "sentence_source": "mined"}, {"text": "浮世絵は、日本で発展した独自の工芸であり、世界的に評価される芸術です。", "target_word": "独自", "complexity_tier": "T3", "furigana": "どくじ", "sentence_source": "mined"}, {"text": "彼は独自の方法で練習している。", "target_word": "独自", "complexity_tier": "T3", "furigana": "どくじ", "sentence_source": "generated"}, {"text": "この町には独自の祭りがある。", "target_word": "独自", "complexity_tier": "T3", "furigana": "どくじ", "sentence_source": "generated"}, {"text": "私たちは独自に調べてみた。", "target_word": "独自", "complexity_tier": "T3", "furigana": "どくじ", "sentence_source": "generated"}, {"text": "その店は独自のメニューが人気だ。", "target_word": "独自", "complexity_tier": "T3", "furigana": "どくじ", "sentence_source": "generated"}, {"text": "独自のルールで遊ぶのが楽しい。", "target_word": "独自", "complexity_tier": "T3", "furigana": "どくじ", "sentence_source": "generated"}, {"text": "彼女は独自の考えを持っている。", "target_word": "独自", "complexity_tier": "T3", "furigana": "どくじ", "sentence_source": "generated"}, {"text": "学校で独自の行事を作った。", "target_word": "独自", "complexity_tier": "T3", "furigana": "どくじ", "sentence_source": "generated"}, {"text": "この国には独自の文化がある。", "target_word": "独自", "complexity_tier": "T3", "furigana": "どくじ", "sentence_source": "generated"}], "morphological_forms": [{"form": "独自の", "label": "派生"}, {"form": "独自に", "label": "派生"}, {"form": "独自性", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 他になくそれだけが持つさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}':