INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37267, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "事実や状態が正しいかを確かめること。", "primary_collocate": null, "pronunciation": "かくにん", "ipa": "kakɯɲiɴ", "syllable_count": 4, "sentences": [{"text": "既製品への安易な依存を排し、自らの手でカスタマイズを通じて素材と対話する行為は、DIYファッションの本質的な愉楽であり、自己効力感の再確認でもある。", "target_word": "確認", "complexity_tier": "T3", "furigana": "かくにん", "sentence_source": "mined"}, {"text": "毎朝の天気予報を確認し、気温や湿度に合わせて水を調整する。", "target_word": "確認", "complexity_tier": "T3", "furigana": "かくにん", "sentence_source": "mined"}, {"text": "出かける前に忘れ物を確認した。", "target_word": "確認", "complexity_tier": "T3", "furigana": "かくにん", "sentence_source": "generated"}, {"text": "答えをもう一度確認してください。", "target_word": "確認", "complexity_tier": "T3", "furigana": "かくにん", "sentence_source": "generated"}, {"text": "先生に時間の確認をした。", "target_word": "確認", "complexity_tier": "T3", "furigana": "かくにん", "sentence_source": "generated"}, {"text": "確認が終わったら帰っていいよ。", "target_word": "確認", "complexity_tier": "T3", "furigana": "かくにん", "sentence_source": "generated"}, {"text": "メールの内容を確認している。", "target_word": "確認", "complexity_tier": "T3", "furigana": "かくにん", "sentence_source": "generated"}, {"text": "駅で電車の時間を確認できる。", "target_word": "確認", "complexity_tier": "T3", "furigana": "かくにん", "sentence_source": "generated"}, {"text": "確認のために電話をかけた。", "target_word": "確認", "complexity_tier": "T3", "furigana": "かくにん", "sentence_source": "generated"}, {"text": "地図で道を確認しながら歩いた。", "target_word": "確認", "complexity_tier": "T3", "furigana": "かくにん", "sentence_source": "generated"}], "morphological_forms": [{"form": "確認する", "label": "派生"}, {"form": "確認した", "label": "活用"}, {"form": "再確認", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 事実や状態を確かめること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}