INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52392, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の地位や段階の上下の重なり。", "primary_collocate": null, "pronunciation": "かいそう", "ipa": "kaisoː", "syllable_count": 4, "sentences": [{"text": "学校イベントという儀礼的空間において、Tシャツデザインは単なる装飾を超え、集団内の微細な階層や個性の顕現として機能し得る。", "target_word": "階層", "complexity_tier": "T3", "furigana": "かいそう", "sentence_source": "mined"}, {"text": "かかる感覚的知見の蓄積は、単一品種を基準とした旧来の分類体系を相対化し、微細な区画ごとの個性を階層的に位置づけるアペラシオンの概念を、より厳密かつ動的なヒエラルキーへと昇華させ、ワインの価値評価基準そのものを哲学的かつ実践的に再定義しているのである。", "target_word": "階層", "complexity_tier": "T3", "furigana": "かいそう", "sentence_source": "mined"}, {"text": "会社にはいくつもの階層がある。", "target_word": "階層", "complexity_tier": "T3", "furigana": "かいそう", "sentence_source": "generated"}, {"text": "社会の階層について授業で学んだ。", "target_word": "階層", "complexity_tier": "T3", "furigana": "かいそう", "sentence_source": "generated"}, {"text": "階層の違いで生活も変わる。", "target_word": "階層", "complexity_tier": "T3", "furigana": "かいそう", "sentence_source": "generated"}, {"text": "この図は階層を表している。", "target_word": "階層", "complexity_tier": "T3", "furigana": "かいそう", "sentence_source": "generated"}, {"text": "古い国には厳しい階層があった。", "target_word": "階層", "complexity_tier": "T3", "furigana": "かいそう", "sentence_source": "generated"}, {"text": "階層の上の人が決めることが多い。", "target_word": "階層", "complexity_tier": "T3", "furigana": "かいそう", "sentence_source": "generated"}, {"text": "フォルダを階層ごとに分けた。", "target_word": "階層", "complexity_tier": "T3", "furigana": "かいそう", "sentence_source": "generated"}, {"text": "いろいろな階層の人が集まった。", "target_word": "階層", "complexity_tier": "T3", "furigana": "かいそう", "sentence_source": "generated"}], "morphological_forms": [{"form": "階層的", "label": "派生"}, {"form": "社会階層", "label": "派生"}, {"form": "階層化", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 地位や段階の上下の重なり", "collocate_gr