INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35707, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "価格", "is_correct": true, "explanation": "正解。「価格（かかく）」。"}, {"text": "化学", "is_correct": false, "explanation": "「化学（かがく）」。二拍目「か」が濁音「が」になる清濁の対立。"}, {"text": "踵", "is_correct": false, "explanation": "「踵（かかと）」。三拍目「く」が「と」に変わる一モーラ差。"}, {"text": "案山子", "is_correct": false, "explanation": "「案山子（かかし）」。三拍目「く」が「し」に変わる一モーラ差。"}, {"text": "係", "is_correct": false, "explanation": "「係（かかり）」。三拍目「く」が「り」に変わる一モーラ差。"}], "explanations": {"価格": "正解。「価格（かかく）」。", "化学": "「化学（かがく）」。二拍目「か」が濁音「が」になる清濁の対立。", "踵": "「踵（かかと）」。三拍目「く」が「と」に変わる一モーラ差。", "案山子": "「案山子（かかし）」。三拍目「く」が「し」に変わる一モーラ差。", "係": "「係（かかり）」。三拍目「く」が「り」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "価格"}, "level_3": {"options": [{"text": "価格", "is_correct": true, "explanation": "正解。文脈に合うのは「価格」。"}, {"text": "気温", "is_correct": false, "explanation": "意味：気温は市場で発見されるものではなく、国債市場とは無関係。"}, {"text": "面積", "is_correct": false, "explanation": "意味：面積は国債市場で決まる値ではない。"}, {"text": "体重", "is_correct": false, "explanation": "意味：体重は市場の機能と結びつかない。"}], "explanations": {"価格": "正解。文脈に合うのは「価格」。", "気温": "意味：気温は市場で発見されるものではなく、国債市場とは無関係。", "面積": "意味：面積は国債市場で決まる値ではない。", "体重": "意味：体重は市場の機能と結びつかない。"}, "sentence_index": 0, "correct_answer": "価格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店の野菜は価格を安い。", "explanation": "助詞の混同：形容詞「安い」の主語は「が」で示す。「を」は不可。"}, {"text": "この店の野菜は価格が軽い。", "explanation": "連語の誤り：「価格」は「安い／高い」で表し、「軽い」とは言わない。"}, {"text": "この店の野菜は価格が安くている。", "explanation": "活用の誤り：形容詞に「ている」は付かない。「安い」が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35707, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この本の価格を千円です。", "corrected_sentence": "この本の価格は千円です。", "error_description": "「価格」を主題にする助詞は「は」。「を」では述語「です」と結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35707, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。この位置には「を」が必要。"}, {"text": "が", "is_correct": false, "explanation": "「メカニズムが通じた」では意味が変わり、「を通じた」という手段の表現にならない。"}, {"text": "に", "is_correct": false, "explanation": "「に通じた」は「詳しい」の意味になり、この文脈に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で通じた」は非文。"}], "correct_answer": "を", "explanations": {"を": "正解。この位置には「を」が必要。", "が": "「メカニズムが通じた」では意味が変わり、「を通じた」という手段の表現にならない。", "に": "「に通じた」は「詳しい」の意味になり、この文脈に合わない。", "で": "「で通じた」は非文。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35707, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "価格", "is_correct": true, "explanation": "正解。「価格（かかく）」。"}, {"text": "比較", "is_correct": false, "explanation": "「比較（ひかく）」。一拍目「か」が「ひ」に変わる一モーラ差。"}, {"text": "資格", "is_correct": false, "explanation": "「資格（しかく）」。一拍目「か」が「し」に変わる一モーラ差。"}, {"text": "近く", "is_correct": false, "explanation": "「近く（ちかく）」。一拍目「か」が「ち」に変わる一モーラ差。"}, {"text": "威嚇", "is_correct": false, "explanation": "「威嚇（いかく）」。一拍目「か」が「い」に変わる一モーラ差。"}], "explanations": {"価格": "正解。「価格（かかく）」。", "比較": "「比較（ひかく）」。一拍目「か」が「ひ」に変わる一モーラ差。", "資格": "「資格（しかく）」。一拍目「か」が「し」に変わる一モーラ差。", "近く": "「近く（ちかく）」。一拍目「か」が「ち」に変わる一モーラ差。", "威嚇": "「威嚇（いかく）」。一拍目「か」が「い」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "価格"}, "level_3": {"options": [{"text": "価格", "is_correct": true, "explanation": "正解。文脈に合うのは「価格」。"}, {"text": "背中", "is_correct": false, "explanation": "意味：服の「背中が高い」は意味をなさず、買えない理由にならない。"}, {"text": "温度", "is_correct": false, "explanation": "連語：服の「温度が高い」は不自然で、買えない理由と結びつかない。"}, {"text": "天井", "is_correct": false, "explanation": "意味：天井は服の性質ではない。"}], "explanations": {"価格": "正解。文脈に合うのは「価格」。", "背中": "意味：服の「背中が高い」は意味をなさず、買えない理由にならない。", "温度": "連語：服の「温度が高い」は不自然で、買えない理由と結びつかない。", "天井": "意味：天井は服の性質ではない。"}, "sentence_index": 6, "correct_answer": "価格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "価格を下がるのを待っている。", "explanation": "助詞の混同：自動詞「下がる」の主語は「が」。「を」は不可。"}, {"text": "価格が痩せるのを待っている。", "explanation": "意味の不一致：「価格」は「下がる」もので、「痩せる」ことはない。"}, {"text": "価格が下がるのに待っている。", "explanation": "助詞の誤り：待つ対象は「のを」で示す。「のに」は不可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35707, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ガソリンの価格に上がってきた。", "corrected_sentence": "ガソリンの価格が上がってきた。", "error_description": "「上がる」の主語を示すのは「が」。「に」では主語にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35707, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。この位置には「を」が必要。"}, {"text": "が", "is_correct": false, "explanation": "他動詞「比べる」の目的語を「が」では示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は目的語にならない。"}, {"text": "の", "is_correct": false, "explanation": "「価格の比べてみた」は非文。"}], "correct_answer": "を", "explanations": {"を": "正解。この位置には「を」が必要。", "が": "他動詞「比べる」の目的語を「が」では示せない。", "へ": "方向を表す「へ」は目的語にならない。", "の": "「価格の比べてみた」は非文。"}, "error_tags": {"が": "object_marking", "へ": "direction", "の": "other"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36099, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "装飾", "is_correct": true, "explanation": "正解。「装飾（そうしょく）」。"}, {"text": "増殖", "is_correct": false, "explanation": "「増殖（ぞうしょく）」。一拍目「そ」が濁音「ぞ」になる清濁の対立。"}, {"text": "葬式", "is_correct": false, "explanation": "「葬式（そうしき）」。四拍目「く」が「き」に変わる一モーラ差。"}, {"text": "朝食", "is_correct": false, "explanation": "「朝食（ちょうしょく）」。一拍目「そ」が「ちょ」に変わる一モーラ差。"}, {"text": "公職", "is_correct": false, "explanation": "「公職（こうしょく）」。一拍目「そ」が「こ」に変わる一モーラ差。"}], "explanations": {"装飾": "正解。「装飾（そうしょく）」。", "増殖": "「増殖（ぞうしょく）」。一拍目「そ」が濁音「ぞ」になる清濁の対立。", "葬式": "「葬式（そうしき）」。四拍目「く」が「き」に変わる一モーラ差。", "朝食": "「朝食（ちょうしょく）」。一拍目「そ」が「ちょ」に変わる一モーラ差。", "公職": "「公職（こうしょく）」。一拍目「そ」が「こ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "装飾"}, "level_3": {"options": [{"text": "装飾", "is_correct": true, "explanation": "正解。文脈に合うのは「装飾」。"}, {"text": "睡眠", "is_correct": false, "explanation": "意味：Tシャツデザインが「睡眠を超える」は意味をなさない。"}, {"text": "天気", "is_correct": false, "explanation": "意味：天気はデザインの役割ではない。"}, {"text": "運賃", "is_correct": false, "explanation": "連語：デザインと運賃は結びつかない。"}], "explanations": {"装飾": "正解。文脈に合うのは「装飾」。", "睡眠": "意味：Tシャツデザインが「睡眠を超える」は意味をなさない。", "天気": "意味：天気はデザインの役割ではない。", "運賃": "連語：デザインと運賃は結びつかない。"}, "sentence_index": 0, "correct_answer": "装飾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱は装飾をとてもきれいだ。", "explanation": "助詞の混同：「きれいだ」の主語は「が」で示す。"}, {"text": "この箱は装飾がとてもおいしい。", "explanation": "意味の不一致：「装飾」は味わうものではなく、「おいしい」とは結びつかない。"}, {"text": "この箱はとても装飾がきれいている。", "explanation": "活用の誤り：「きれいだ」に「ている」は付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_