INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36099, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教室の装飾がみんなで考えた。", "corrected_sentence": "教室の装飾をみんなで考えた。", "error_description": "「考える」の目的語は「を」で示す。「が」では主語になってしまう。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36099, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "正解。この位置には「から」が必要。"}, {"text": "を", "is_correct": false, "explanation": "「観点を」では後の動詞と結びつかず非文。"}, {"text": "が", "is_correct": false, "explanation": "「観点が」は主語になり文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では観点を根拠として表せない。"}], "correct_answer": "から", "explanations": {"から": "正解。この位置には「から」が必要。", "を": "「観点を」では後の動詞と結びつかず非文。", "が": "「観点が」は主語になり文が成立しない。", "へ": "方向の「へ」では観点を根拠として表せない。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "へ": "source_vs_goal"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36099, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "装飾", "is_correct": true, "explanation": "正解。「装飾（そうしょく）」。"}, {"text": "夕食", "is_correct": false, "explanation": "「夕食（ゆうしょく）」。一拍目「そ」が「ゆ」に変わる一モーラ差。"}, {"text": "昼食", "is_correct": false, "explanation": "「昼食（ちゅうしょく）」。一拍目「そ」が「ちゅ」に変わる一モーラ差。"}, {"text": "就職", "is_correct": false, "explanation": "「就職（しゅうしょく）」。一拍目「そ」が「しゅ」に変わる一モーラ差。"}], "explanations": {"装飾": "正解。「装飾（そうしょく）」。", "夕食": "「夕食（ゆうしょく）」。一拍目「そ」が「ゆ」に変わる一モーラ差。", "昼食": "「昼食（ちゅうしょく）」。一拍目「そ」が「ちゅ」に変わる一モーラ差。", "就職": "「就職（しゅうしょく）」。一拍目「そ」が「しゅ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "装飾"}, "level_3": {"options": [{"text": "装飾", "is_correct": true, "explanation": "正解。文脈に合うのは「装飾」。"}, {"text": "返事", "is_correct": false, "explanation": "意味：窓に返事はつけられない。"}, {"text": "宿題", "is_correct": false, "explanation": "意味：花の宿題を窓につけるのは意味をなさない。"}, {"text": "値段", "is_correct": false, "explanation": "連語：「花の値段を窓につけた」は不自然。"}], "explanations": {"装飾": "正解。文脈に合うのは「装飾」。", "返事": "意味：窓に返事はつけられない。", "宿題": "意味：花の宿題を窓につけるのは意味をなさない。", "値段": "連語：「花の値段を窓につけた」は不自然。"}, "sentence_index": 6, "correct_answer": "装飾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "派手な装飾は飲みたくないと思う。", "explanation": "意味の不一致：「装飾」は飲むものではない。"}, {"text": "派手な装飾にいらないと思う。", "explanation": "助詞の誤り：「いらない」の対象は「は／が」で示し、「に」は不可。"}, {"text": "派手な装飾はいらないに思う。", "explanation": "助詞の誤り：思う内容を引用するには「と」が必要。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
