INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36099, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。この位置には「に」が必要。"}, {"text": "を", "is_correct": false, "explanation": "「感動する」は自動詞で「を」を取らない。"}, {"text": "が", "is_correct": false, "explanation": "「装飾が感動した」では装飾が感動する意味になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は感動の対象を示せない。"}], "correct_answer": "に", "explanations": {"に": "正解。この位置には「に」が必要。", "を": "「感動する」は自動詞で「を」を取らない。", "が": "「装飾が感動した」では装飾が感動する意味になる。", "へ": "方向の「へ」は感動の対象を示せない。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51856, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "独自", "is_correct": true, "explanation": "正解。「独自（どくじ）」。"}, {"text": "毒蛇", "is_correct": false, "explanation": "「毒蛇（どくじゃ）」。三拍目「じ」が「じゃ」に変わる一モーラ差。"}, {"text": "読者", "is_correct": false, "explanation": "「読者（どくしゃ）」。三拍目「じ」が「しゃ」に変わる一モーラ差。"}, {"text": "六時", "is_correct": false, "explanation": "「六時（ろくじ）」。一拍目「ど」が「ろ」に変わる一モーラ差。"}, {"text": "同時", "is_correct": false, "explanation": "「同時（どうじ）」。二拍目「く」が「う」に変わる一モーラ差。"}], "explanations": {"独自": "正解。「独自（どくじ）」。", "毒蛇": "「毒蛇（どくじゃ）」。三拍目「じ」が「じゃ」に変わる一モーラ差。", "読者": "「読者（どくしゃ）」。三拍目「じ」が「しゃ」に変わる一モーラ差。", "六時": "「六時（ろくじ）」。一拍目「ど」が「ろ」に変わる一モーラ差。", "同時": "「同時（どうじ）」。二拍目「く」が「う」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "独自"}, "level_3": {"options": [{"text": "独自", "is_correct": true, "explanation": "正解。文脈に合うのは「独自」。"}, {"text": "満腹", "is_correct": false, "explanation": "意味：「満腹のプロット」は意味をなさない。"}, {"text": "真冬", "is_correct": false, "explanation": "意味：プロットに季節の語は合わない。"}, {"text": "無料", "is_correct": false, "explanation": "連語：「無料のプロットを紡ぎ出す」は不自然。"}], "explanations": {"独自": "正解。文脈に合うのは「独自」。", "満腹": "意味：「満腹のプロット」は意味をなさない。", "真冬": "意味：プロットに季節の語は合わない。", "無料": "連語：「無料のプロットを紡ぎ出す」は不自然。"}, "sentence_index": 0, "correct_answer": "独自"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町には独自を祭りがある。", "explanation": "助詞の混同：名詞を修飾するには「の」が必要。"}, {"text": "この町には独自に祭りがある。", "explanation": "形の誤り：名詞を修飾するのは「独自の」。「独自に」は動詞を修飾する形。"}, {"text": "この町には独自の祭りがあっている。", "explanation": "活用の誤り：「ある」に「ている」は付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCL