INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51856, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私たちは独自を調べてみた。", "corrected_sentence": "私たちは独自に調べてみた。", "error_description": "動詞を修飾するときは「独自に」。「独自を」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "独自", "is_correct": true, "explanation": "後ろの「の」に続くのは語幹「独自」。"}, {"text": "独自に", "is_correct": false, "explanation": "「独自にの」は非文。"}, {"text": "独自だ", "is_correct": false, "explanation": "終止形「独自だ」は「の」に続かない。"}, {"text": "独自な", "is_correct": false, "explanation": "「独自なの工芸」は非文。"}], "correct_form": "独自", "base_form": "独自", "form_label": "語幹（「の」接続）", "sentence_index": 1, "explanations": {"独自": "後ろの「の」に続くのは語幹「独自」。", "独自に": "「独自にの」は非文。", "独自だ": "終止形「独自だ」は「の」に続かない。", "独自な": "「独自なの工芸」は非文。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
