INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52382, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "個性", "is_correct": true, "explanation": "正解。「個性（こせい）」。"}, {"text": "構成", "is_correct": false, "explanation": "「構成（こうせい）」。一拍目が長音「こう」になる長短の対立。"}, {"text": "戸籍", "is_correct": false, "explanation": "「戸籍（こせき）」。三拍目「い」が「き」に変わる一モーラ差。"}, {"text": "火星", "is_correct": false, "explanation": "「火星（かせい）」。一拍目「こ」が「か」に変わる一モーラ差。"}], "explanations": {"個性": "正解。「個性（こせい）」。", "構成": "「構成（こうせい）」。一拍目が長音「こう」になる長短の対立。", "戸籍": "「戸籍（こせき）」。三拍目「い」が「き」に変わる一モーラ差。", "火星": "「火星（かせい）」。一拍目「こ」が「か」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "個性"}, "level_3": {"options": [{"text": "個性", "is_correct": true, "explanation": "正解。文脈に合うのは「個性」。"}, {"text": "食欲", "is_correct": false, "explanation": "意味：集団内の食欲の顕現は文脈に合わない。"}, {"text": "天候", "is_correct": false, "explanation": "意味：天候は集団内の性質ではない。"}, {"text": "距離", "is_correct": false, "explanation": "連語：「距離の顕現」は不自然。"}], "explanations": {"個性": "正解。文脈に合うのは「個性」。", "食欲": "意味：集団内の食欲の顕現は文脈に合わない。", "天候": "意味：天候は集団内の性質ではない。", "距離": "連語：「距離の顕現」は不自然。"}, "sentence_index": 0, "correct_answer": "個性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "クラスのみんなの個性が大切にしたい。", "explanation": "助詞の混同：「大切にする」の対象は「を」。"}, {"text": "クラスのみんなの個性を飲みたい。", "explanation": "意味の不一致：「個性」は飲むものではない。"}, {"text": "クラスのみんなの個性を大切だしたい。", "explanation": "活用の誤り：「大切にしたい」が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
