INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52392, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "階層", "is_correct": true, "explanation": "正解。「階層（かいそう）」。"}, {"text": "快速", "is_correct": false, "explanation": "「快速（かいそく）」。四拍目「う」が「く」に変わる一モーラ差。"}, {"text": "改造", "is_correct": false, "explanation": "「改造（かいぞう）」。三拍目「そ」が濁音「ぞ」になる清濁の対立。"}, {"text": "回答", "is_correct": false, "explanation": "「回答（かいとう）」。三拍目「そ」が「と」に変わる一モーラ差。"}], "explanations": {"階層": "正解。「階層（かいそう）」。", "快速": "「快速（かいそく）」。四拍目「う」が「く」に変わる一モーラ差。", "改造": "「改造（かいぞう）」。三拍目「そ」が濁音「ぞ」になる清濁の対立。", "回答": "「回答（かいとう）」。三拍目「そ」が「と」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "階層"}, "level_3": {"options": [{"text": "階層", "is_correct": true, "explanation": "正解。文脈に合うのは「階層」。"}, {"text": "昼食", "is_correct": false, "explanation": "意味：集団内の昼食は個性と並ぶ社会的差異にならない。"}, {"text": "湿度", "is_correct": false, "explanation": "意味：湿度は集団内の地位ではない。"}, {"text": "速度", "is_correct": false, "explanation": "連語：「微細な速度や個性」は不自然。"}], "explanations": {"階層": "正解。文脈に合うのは「階層」。", "昼食": "意味：集団内の昼食は個性と並ぶ社会的差異にならない。", "湿度": "意味：湿度は集団内の地位ではない。", "速度": "連語：「微細な速度や個性」は不自然。"}, "sentence_index": 0, "correct_answer": "階層"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "社会の階層について授業が学んだ。", "explanation": "助詞の混同：学ぶ場所は「で」。"}, {"text": "社会の階層にについて授業で学んだ。", "explanation": "助詞の誤り：「について」の前に「に」を重ねることはできない。"}, {"text": "学んだ社会の階層について授業で。", "explanation": "語順の誤り：述語が文頭に来ている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
