INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52392, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "階層", "is_correct": true, "explanation": "正解。「階層（かいそう）」。"}, {"text": "外装", "is_correct": false, "explanation": "「外装（がいそう）」。一拍目「か」が濁音「が」になる清濁の対立。"}, {"text": "開講", "is_correct": false, "explanation": "「開講（かいこう）」。三拍目「そ」が「こ」に変わる一モーラ差。"}, {"text": "街道", "is_correct": false, "explanation": "「街道（かいどう）」。三拍目「そ」が「ど」に変わる一モーラ差。"}], "explanations": {"階層": "正解。「階層（かいそう）」。", "外装": "「外装（がいそう）」。一拍目「か」が濁音「が」になる清濁の対立。", "開講": "「開講（かいこう）」。三拍目「そ」が「こ」に変わる一モーラ差。", "街道": "「街道（かいどう）」。三拍目「そ」が「ど」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "階層"}, "level_3": {"options": [{"text": "階層", "is_correct": true, "explanation": "正解。文脈に合うのは「階層」。"}, {"text": "天気", "is_correct": false, "explanation": "意味：国に「厳しい天気」があったは文脈に合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "意味：国に宿題はない。"}, {"text": "味", "is_correct": false, "explanation": "連語：「厳しい味」は不自然。"}], "explanations": {"階層": "正解。文脈に合うのは「階層」。", "天気": "意味：国に「厳しい天気」があったは文脈に合わない。", "宿題": "意味：国に宿題はない。", "味": "連語：「厳しい味」は不自然。"}, "sentence_index": 6, "correct_answer": "階層"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "いろいろな階層を人が集まった。", "explanation": "助詞の混同：名詞を修飾するには「の」。"}, {"text": "いろいろな階層だ人が集まった。", "explanation": "形の誤り：名詞「階層」が名詞を修飾するには「の」が必要。「だ」は不可。"}, {"text": "集まったいろいろな階層の人が。", "explanation": "語順の誤り：述語が文頭に来ている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
