INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52652, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "目に見えなかったものが、はっきりと形をとって現れること。", "primary_collocate": null, "pronunciation": "けんげん", "ipa": "keŋgeɴ", "syllable_count": 4, "sentences": [{"text": "学校イベントという儀礼的空間において、Tシャツデザインは単なる装飾を超え、集団内の微細な階層や個性の顕現として機能し得る。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "けんげん", "sentence_source": "mined"}, {"text": "なぜならば、無数の主体が限られた情報に基づき絶えず適応を繰り返す過程で、意図せぬイノベーションやシステミック・リスクが突発的に顕現するからに他ならない。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "けんげん", "sentence_source": "mined"}, {"text": "彼の本心が言葉の端々に顕現した。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "かれ ほんしん ことば はしばし けんげん", "sentence_source": "generated"}, {"text": "その絵は作者の心の顕現だ。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "え さくしゃ こころ けんげん", "sentence_source": "generated"}, {"text": "問題が表に顕現し始めている。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "もんだい おもて けんげん はじ", "sentence_source": "generated"}, {"text": "努力の成果が形として顕現した。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "どりょく せいか かたち けんげん", "sentence_source": "generated"}, {"text": "顕現した不安が皆に広がった。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "けんげん ふあん みな ひろ", "sentence_source": "generated"}, {"text": "友情の顕現を彼の行動に見た。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "ゆうじょう けんげん かれ こうどう み", "sentence_source": "generated"}, {"text": "顕現の仕方は人それぞれだ。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "けんげん しかた ひと", "sentence_source": "generated"}, {"text": "小さな変化に危機が顕現する。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "ちい へんか きき けんげん", "sentence_source": "generated"}], "morphological_forms": [{"form": "顕現する", "label": "派生"}, {"form": "顕現した", "label": "活用"}, {"form": "顕現させる", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 隠れたものがはっきり現れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb22e58c-0163-453a-ab1b-82dc4bfc15e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52538, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物語や音楽、考えなどを、時間をかけて丁寧に作り出す。", "primary_collocate": null, "pronunciation": "つむぎだす", "ipa": "tsɯmɯɡidasɯ", "syllable_count": 5, "sentences": [{"text": "生徒たちが繊維の纹理に想いを込め、独自のプロットを紡ぎ出すとき、それは単なる被服製作ではなく、記号的な自己主張の確立へと昇華されるのである。", "target_word": "紡ぎ出す", "complexity_tier": "T3", "furigana": "せんい おも こ どくじ つむ だ", "sentence_source": "mined"}, {"text": "無機質な素材が自律的実体へと昇華する奇跡を、自らの双手で紡ぎ出す営み。", "target_word": "紡ぎ出す", "complexity_tier": "T3", "furigana": "つむ だ", "sentence_source": "mined"}, {"text": "彼女は美しい物語を紡ぎ出した。", "target_word": "紡ぎ出した", "complexity_tier": "T3", "furigana": "かのじょ うつく ものがたり つむ だ", "sentence_source": "generated"}, {"text": "言葉を紡ぎ出すのは難しい。", "target_word": "紡ぎ出す", "complexity_tier": "T3", "furigana": "ことば つむ だ むずか", "sentence_source": "generated"}, {"text": "彼はピアノで音を紡ぎ出している。", "target_word": "紡ぎ出して", "complexity_tier": "T3", "furigana": "かれ おと つむ だ", "sentence_source": "generated"}, {"text": "自分の言葉で詩を紡ぎ出せる。", "target_word": "紡ぎ出せる", "complexity_tier": "T3", "furigana": "じぶん ことば し つむ だ", "sentence_source": "generated"}, {"text": "二人で紡ぎ出した思い出だ。", "target_word": "紡ぎ出した", "complexity_tier": "T3", "furigana": "ふたり つむ だ おも で", "sentence_source": "generated"}, {"text": "作家は毎日文章を紡ぎ出す。", "target_word": "紡ぎ出す", "complexity_tier": "T3", "furigana": "さっか まいにち ぶんしょう つむ だ", "sentence_source": "generated"}, {"text": "歌手が紡ぎ出す声に涙が出た。", "target_word": "紡ぎ出す", "complexity_tier": "T3", "furigana": "かしゅ つむ だ こえ なみだ で", "sentence_source": "generated"}, {"text": "新しい考えを紡ぎ出してみよう。", "target_word": "紡ぎ出して", "complexity_tier": "T3", "furigana": "あたら かんが つむ だ", "sentence_source": "generated"}], "morphological_forms": [{"form": "紡ぎ出した", "label": "活用"}, {"form": "紡ぎ出して", "label": "活用"}, {"form": "紡ぎ出さない", "label": "活用"}, {"form": "紡ぎ出せる", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 物語や言葉を丁寧に作り出す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb22e58c-0163-453a-ab1b-82dc4bfc15e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52472, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の形や様子が、すっかり別のものに変わること。", "primary_collocate": null, "pronunciation": "へんぼう", "ipa": "hembo̞ː", "syllable_count": 4, "sentences": [{"text": "この創造的プロセスこそが、行事の記憶を永続的なものへと変貌させ、参加者の帰属意識を強固なものへと昇華させるのである。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "へんぼう", "sentence_source": "mined"}, {"text": "苛烈な寒風が頬を打つ外の世界へと、無垢な好奇心を携えて駆け出していくその背中には、人間が本来備えている、過酷な環境をも楽しみへと変貌させる逞しさが凝縮されていたのである。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "へんぼう", "sentence_source": "mined"}, {"text": "町は十年で大きく変貌した。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "まち じゅうねん おお へんぼう", "sentence_source": "generated"}, {"text": "彼の変貌に皆が驚いた。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "かれ へんぼう みな おどろ", "sentence_source": "generated"}, {"text": "駅前の変貌ぶりがすごい。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "えきまえ へんぼう", "sentence_source": "generated"}, {"text": "村は観光地へと変貌している。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "むら かんこうち へんぼう", "sentence_source": "generated"}, {"text": "変貌した故郷を見て悲しくなった。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "へんぼう こきょう み かな", "sentence_source": "generated"}, {"text": "彼女は別人のように変貌した。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "かのじょ べつじん へんぼう", "sentence_source": "generated"}, {"text": "その店の変貌は急だった。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "みせ へんぼう きゅう", "sentence_source": "generated"}, {"text": "技術が社会を変貌させている。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "ぎじゅつ しゃかい へんぼう", "sentence_source": "generated"}], "morphological_forms": [{"form": "変貌する", "label": "派生"}, {"form": "変貌した", "label": "活用"}, {"form": "変貌させる", "label": "活用"}, {"form": "変貌ぶり", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 姿や様子がすっかり変わること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb22e58c-0163-453a-ab1b-82dc4bfc15e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37465, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "その人自身。他人ではない、自分。", "primary_collocate": null, "pronunciation": "じこ", "ipa": "dʑiko", "syllable_count": 2, "sentences": [{"text": "既製品への安易な依存を排し、自らの手でカスタマイズを通じて素材と対話する行為は、DIYファッションの本質的な愉楽であり、自己効力感の再確認でもある。", "target_word": "自己", "complexity_tier": "T3", "furigana": "じこ", "sentence_source": "mined"}, {"text": "生徒たちが繊維の纹理に想いを込め、独自のプロットを紡ぎ出すとき、それは単なる被服製作ではなく、記号的な自己主張の確立へと昇華されるのである。", "target_word": "自己", "complexity_tier": "T3", "furigana": "じこ", "sentence_source": "mined"}, {"text": "それは、確立された安住の地からの離脱であり、新たな社会的文脈における自己の再構築を迫られる、極めて重要な通過儀礼なのである。", "target_word": "自己", "complexity_tier": "T3", "furigana": "じこ", "sentence_source": "mined"}, {"text": "自己を知ることは大切だ。", "target_word": "自己", "complexity_tier": "T3", "furigana": "じこ し たいせつ", "sentence_source": "generated"}, {"text": "彼は自己の考えを話した。", "target_word": "自己", "complexity_tier": "T3", "furigana": "かれ じこ かんが はな", "sentence_source": "generated"}, {"text": "自己の責任で決めなさい。", "target_word": "自己", "complexity_tier": "T3", "furigana": "じこ せきにん き", "sentence_source": "generated"}, {"text": "日記は自己と向き合う時間だ。", "target_word": "自己", "complexity_tier": "T3", "furigana": "にっき じこ む あ じかん", "sentence_source": "generated"}, {"text": "自己の弱さを認めた。", "target_word": "自己", "complexity_tier": "T3", "furigana": "じこ よわ みと", "sentence_source": "generated"}, {"text": "音楽で自己を表現している。", "target_word": "自己", "complexity_tier": "T3", "furigana": "おんがく じこ ひょうげん", "sentence_source": "generated"}, {"text": "新しい自己を見つけたい。", "target_word": "自己", "complexity_tier": "T3", "furigana": "あたら じこ み", "sentence_source": "generated"}], "morphological_forms": [{"form": "自己紹介", "label": "派生"}, {"form": "自己主張", "label": "派生"}, {"form": "自己満足", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 他人ではない