INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36203, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "時間。時の流れや、そのある一区切り。", "primary_collocate": null, "pronunciation": "とき", "ipa": "toki", "syllable_count": 2, "sentences": [{"text": "生徒たちが繊維の纹理に想いを込め、独自のプロットを紡ぎ出すとき、それは単なる被服製作ではなく、記号的な自己主張の確立へと昇華されるのである。", "target_word": "とき", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "鉢という限定された宇宙の中で、命は水という恩恵を糧に、時を重ねてその緑を深めていく。", "target_word": "時", "complexity_tier": "T3", "furigana": "とき", "sentence_source": "mined"}, {"text": "時がたつのは早い。", "target_word": "時", "complexity_tier": "T3", "furigana": "とき はや", "sentence_source": "generated"}, {"text": "楽しい時はすぐ過ぎる。", "target_word": "時", "complexity_tier": "T3", "furigana": "とき たの す", "sentence_source": "generated"}, {"text": "時が解決してくれるよ。", "target_word": "時", "complexity_tier": "T3", "furigana": "とき かいけつ", "sentence_source": "generated"}, {"text": "子どもの時をよく思い出す。", "target_word": "時", "complexity_tier": "T3", "furigana": "とき こ おも だ", "sentence_source": "generated"}, {"text": "時の流れは止められない。", "target_word": "時", "complexity_tier": "T3", "furigana": "とき なが と", "sentence_source": "generated"}, {"text": "寝る時に本を読む。", "target_word": "時", "complexity_tier": "T3", "furigana": "とき ね ほん よ", "sentence_source": "generated"}, {"text": "時を忘れて遊んだ。", "target_word": "時", "complexity_tier": "T3", "furigana": "とき わす あそ", "sentence_source": "generated"}, {"text": "あの時はありがとう。", "target_word": "時", "complexity_tier": "T3", "furigana": "とき", "sentence_source": "generated"}], "morphological_forms": [{"form": "時々", "label": "派生"}, {"form": "時間", "label": "派生"}, {"form": "時代", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 流れていく時間やその区切り", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code