INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52652, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "顕現", "is_correct": true, "explanation": "正解。「けんげん」と読む対象語。"}, {"text": "軽減", "is_correct": false, "explanation": "けいげん：二拍目が「ん」→「い」に違う一モーラ差。"}, {"text": "検眼", "is_correct": false, "explanation": "けんがん：三拍目「げ」→「が」の一モーラ差。"}, {"text": "還元", "is_correct": false, "explanation": "かんげん：一拍目「け」→「か」の一モーラ差。"}, {"text": "宣言", "is_correct": false, "explanation": "せんげん：一拍目「け」→「せ」の一モーラ差。"}, {"text": "賢人", "is_correct": false, "explanation": "けんじん：三拍目「げ」→「じ」の一モーラ差。"}], "explanations": {"顕現": "正解。「けんげん」と読む対象語。", "軽減": "けいげん：二拍目が「ん」→「い」に違う一モーラ差。", "検眼": "けんがん：三拍目「げ」→「が」の一モーラ差。", "還元": "かんげん：一拍目「け」→「か」の一モーラ差。", "宣言": "せんげん：一拍目「け」→「せ」の一モーラ差。", "賢人": "けんじん：三拍目「げ」→「じ」の一モーラ差。"}, "sentence_index": null, "correct_answer": "顕現"}, "level_3": {"options": [{"text": "顕現", "is_correct": true, "explanation": "隠れていた個性がはっきり現れることを表す。"}, {"text": "消滅", "is_correct": false, "explanation": "意味：消えてなくなることで、個性が現れる文脈に合わない。"}, {"text": "予約", "is_correct": false, "explanation": "連語：「個性の予約」とは言わない。"}, {"text": "往復", "is_correct": false, "explanation": "意味：行き来を表し、この文脈と無関係。"}], "explanations": {"顕現": "隠れていた個性がはっきり現れることを表す。", "消滅": "意味：消えてなくなることで、個性が現れる文脈に合わない。", "予約": "連語：「個性の予約」とは言わない。", "往復": "意味：行き来を表し、この文脈と無関係。"}, "sentence_index": 0, "correct_answer": "顕現"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は駅で顕現を待った。", "explanation": "意味の誤り：顕現は人や乗り物ではなく、待つ対象にならない。"}, {"text": "パンを顕現して食べた。", "explanation": "意味の誤り：顕現は食べ物の調理に使えない。"}, {"text": "机の上に顕現が三冊ある。", "explanation": "助数詞の誤り：抽象名詞の顕現は「冊」で数えられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947ae890-b488-4549-a2e9-3831b9c404c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, 