INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52652, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "自動詞「顕現する」の主語「リスク」を示す。"}, {"text": "を", "is_correct": false, "explanation": "「顕現する」は自動詞なので目的語の「を」はとらない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所・手段を表し、主語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、主語の位置に入らない。"}], "correct_answer": "が", "explanations": {"が": "自動詞「顕現する」の主語「リスク」を示す。", "を": "「顕現する」は自動詞なので目的語の「を」はとらない。", "で": "「で」は場所・手段を表し、主語を示せない。", "へ": "「へ」は方向を表し、主語の位置に入らない。"}, "error_tags": {"を": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "潜在", "is_correct": true, "explanation": "表に出ず内にひそむこと。顕現の対義語。"}, {"text": "出現", "is_correct": false, "explanation": "現れることで、顕現と似た意味。対義語ではない。"}, {"text": "発見", "is_correct": false, "explanation": "見つけることで、対の関係にない。"}, {"text": "実現", "is_correct": false, "explanation": "かなうことで、対の関係にない。"}], "correct_answer": "潜在", "explanations": {"潜在": "表に出ず内にひそむこと。顕現の対義語。", "出現": "現れることで、顕現と似た意味。対義語ではない。", "発見": "見つけることで、対の関係にない。", "実現": "かなうことで、対の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947ae890-b488-4549-a2e9-3831b9c404c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
