INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52538, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "紡ぎ出す", "is_correct": true, "explanation": "正解。「つむぎだす」と読む対象語。"}, {"text": "担ぎ出す", "is_correct": false, "explanation": "かつぎだす：前半の「つむ」と「かつ」の音が違う。"}, {"text": "研ぎ出す", "is_correct": false, "explanation": "とぎだす：「つむ」が「と」に替わる。"}, {"text": "突き出す", "is_correct": false, "explanation": "つきだす：「むぎ」が「き」に替わる。"}, {"text": "摘み出す", "is_correct": false, "explanation": "つまみだす：「むぎ」が「まみ」に替わる。"}], "explanations": {"紡ぎ出す": "正解。「つむぎだす」と読む対象語。", "担ぎ出す": "かつぎだす：前半の「つむ」と「かつ」の音が違う。", "研ぎ出す": "とぎだす：「つむ」が「と」に替わる。", "突き出す": "つきだす：「むぎ」が「き」に替わる。", "摘み出す": "つまみだす：「むぎ」が「まみ」に替わる。"}, "sentence_index": null, "correct_answer": "紡ぎ出す"}, "level_3": {"options": [{"text": "紡ぎ出す", "is_correct": true, "explanation": "物語の筋を丁寧に作り出すことを表す。"}, {"text": "食べる", "is_correct": false, "explanation": "意味：プロットは食べられない。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "項構造：自動詞で「プロットを」をとれない。"}, {"text": "壊れる", "is_correct": false, "explanation": "項構造：自動詞で目的語をとれない。"}], "explanations": {"紡ぎ出す": "物語の筋を丁寧に作り出すことを表す。", "食べる": "意味：プロットは食べられない。", "泳ぐ": "項構造：自動詞で「プロットを」をとれない。", "壊れる": "項構造：自動詞で目的語をとれない。"}, "sentence_index": 0, "correct_answer": "紡ぎ出す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎朝コーヒーを紡ぎ出す。", "explanation": "意味の誤り：コーヒーを入れることには使わない。"}, {"text": "雨が空から紡ぎ出した。", "explanation": "意味の誤り：雨が降ることに使えず、目的語もない。"}, {"text": "言葉が紡ぎ出すのは難しい。", "explanation": "助詞の誤り：言葉は目的語なので「が」ではなく「を」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947ae890-b488-4549-a2e9-3831b9c404c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warni