INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52472, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "変貌", "is_correct": true, "explanation": "正解。「へんぼう」と読む対象語。"}, {"text": "変更", "is_correct": false, "explanation": "へんこう：三拍目「ぼ」→「こ」の一モーラ差。"}, {"text": "返答", "is_correct": false, "explanation": "へんとう：三拍目「ぼ」→「と」の一モーラ差。"}, {"text": "返報", "is_correct": false, "explanation": "へんぽう：三拍目の濁音「ぼ」と半濁音「ぽ」の差。"}, {"text": "羨望", "is_correct": false, "explanation": "せんぼう：一拍目「へ」→「せ」の一モーラ差。"}], "explanations": {"変貌": "正解。「へんぼう」と読む対象語。", "変更": "へんこう：三拍目「ぼ」→「こ」の一モーラ差。", "返答": "へんとう：三拍目「ぼ」→「と」の一モーラ差。", "返報": "へんぽう：三拍目の濁音「ぼ」と半濁音「ぽ」の差。", "羨望": "せんぼう：一拍目「へ」→「せ」の一モーラ差。"}, "sentence_index": null, "correct_answer": "変貌"}, "level_3": {"options": [{"text": "変貌", "is_correct": true, "explanation": "記憶をまったく別のものに変えることを表す。"}, {"text": "散歩", "is_correct": false, "explanation": "連語：記憶を「散歩させる」とは言わない。"}, {"text": "入学", "is_correct": false, "explanation": "意味：記憶は入学しない。"}, {"text": "停止", "is_correct": false, "explanation": "意味：「永続的なものへと」停止させるは矛盾する。"}], "explanations": {"変貌": "記憶をまったく別のものに変えることを表す。", "散歩": "連語：記憶を「散歩させる」とは言わない。", "入学": "意味：記憶は入学しない。", "停止": "意味：「永続的なものへと」停止させるは矛盾する。"}, "sentence_index": 0, "correct_answer": "変貌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本屋で変貌を一冊買った。", "explanation": "助詞・助数詞の誤り：変貌は本ではなく「冊」で数えない。"}, {"text": "彼はご飯を変貌して食べた。", "explanation": "意味の誤り：料理の加熱などには使わない。"}, {"text": "彼の変貌が皆に驚いた。", "explanation": "助詞の誤り：驚くのは皆なので「皆が彼の変貌に驚いた」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947ae890-b488-4549-a2e9-3831b9c404c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
