INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37465, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自己", "is_correct": true, "explanation": "正解。「じこ」と読む対象語。"}, {"text": "時価", "is_correct": false, "explanation": "じか：二拍目「こ」→「か」の一モーラ差。"}, {"text": "軸", "is_correct": false, "explanation": "じく：二拍目「こ」→「く」の一モーラ差。"}, {"text": "事後", "is_correct": false, "explanation": "じご：二拍目の清音「こ」と濁音「ご」の差。"}, {"text": "四股", "is_correct": false, "explanation": "しこ：一拍目の濁音「じ」と清音「し」の差。"}], "explanations": {"自己": "正解。「じこ」と読む対象語。", "時価": "じか：二拍目「こ」→「か」の一モーラ差。", "軸": "じく：二拍目「こ」→「く」の一モーラ差。", "事後": "じご：二拍目の清音「こ」と濁音「ご」の差。", "四股": "しこ：一拍目の濁音「じ」と清音「し」の差。"}, "sentence_index": null, "correct_answer": "自己"}, "level_3": {"options": [{"text": "自己", "is_correct": true, "explanation": "自分自身の力を感じる「自己効力感」になる。"}, {"text": "天気", "is_correct": false, "explanation": "意味：「天気効力感」という語はない。"}, {"text": "机", "is_correct": false, "explanation": "意味：物を表し、この文脈に合わない。"}, {"text": "駅", "is_correct": false, "explanation": "意味：場所を表し、文意が通らない。"}], "explanations": {"自己": "自分自身の力を感じる「自己効力感」になる。", "天気": "意味：「天気効力感」という語はない。", "机": "意味：物を表し、この文脈に合わない。", "駅": "意味：場所を表し、文意が通らない。"}, "sentence_index": 0, "correct_answer": "自己"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "図書館で自己を三冊借りた。", "explanation": "助数詞・意味の誤り：自己は本ではない。"}, {"text": "自己が雨に降った。", "explanation": "意味・助詞の誤り：自己は降るものではない。"}, {"text": "自己を窓から捨てた。", "explanation": "意味の誤り：自己は物ではなく捨てられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947ae890-b488-4549-a2e9-3831b9c404c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch