INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52850, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の状態や効果が、長い間変わらずに続くこと。", "primary_collocate": null, "pronunciation": "えいぞく", "ipa": "eːzokɯ", "syllable_count": 4, "sentences": [{"text": "この創造的プロセスこそが、行事の記憶を永続的なものへと変貌させ、参加者の帰属意識を強固なものへと昇華させるのである。", "target_word": "永続", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "すなわち、限られた特権階級のみに奉仕することを潔しとしない独占的な美学こそが、地上に降り立つトレンドの羅針盤としての役割を担い、現代のファッション産業における生態系を永続的に循環させているのである。", "target_word": "永続", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "平和の永続を心から願っている。", "target_word": "永続", "complexity_tier": "T3", "furigana": "えいぞく", "sentence_source": "generated"}, {"text": "この効果は永続しないそうだ。", "target_word": "永続", "complexity_tier": "T3", "furigana": "えいぞく", "sentence_source": "generated"}, {"text": "永続する友情などあるのだろうか。", "target_word": "永続", "complexity_tier": "T3", "furigana": "えいぞく", "sentence_source": "generated"}, {"text": "会社の永続には若い力がいる。", "target_word": "永続", "complexity_tier": "T3", "furigana": "えいぞく", "sentence_source": "generated"}, {"text": "彼は店の永続を考えている。", "target_word": "永続", "complexity_tier": "T3", "furigana": "えいぞく", "sentence_source": "generated"}, {"text": "この制度は永続的に使える。", "target_word": "永続", "complexity_tier": "T3", "furigana": "えいぞく", "sentence_source": "generated"}, {"text": "永続的な関係を作りたい。", "target_word": "永続", "complexity_tier": "T3", "furigana": "えいぞく", "sentence_source": "generated"}, {"text": "自然の永続を守る活動をしている。", "target_word": "永続", "complexity_tier": "T3", "furigana": "えいぞく", "sentence_source": "generated"}], "morphological_forms": [{"form": "永続的", "label": "派生"}, {"form": "永続性", "label": "派生"}, {"form": "永続する", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 状態が長く変わらず続くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65746631-d687-4201-9b73-f7c0f60d853b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37917, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのものに挟まれた時間や空間。また、ちょうどよい時間の隔たり。", "primary_collocate": null, "pronunciation": "ま", "ipa": "ma", "syllable_count": 1, "sentences": [{"text": "水は瞬く間に闇色の大地へと吸い込まれ、やがて目に見えぬ根の網目へと伝わっていくだろう。", "target_word": "間", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "仮想空間上で構築される3Dモデリングやアルゴリズムによる生成物は、かつての「仕立て屋」の矜持をどう書き換えているのか。そこには、アナログな温もりとデジタルな冷徹さの間の絶え間ない緊張関係が見て取れ、それは創造性の本質を問うている。", "target_word": "間", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "休む間もなく働いている。", "target_word": "間", "complexity_tier": "T3", "furigana": "ま", "sentence_source": "generated"}, {"text": "話の間の取り方が上手だ。", "target_word": "間", "complexity_tier": "T3", "furigana": "ま", "sentence_source": "generated"}, {"text": "少し間を置いてから答えた。", "target_word": "間", "complexity_tier": "T3", "furigana": "ま", "sentence_source": "generated"}, {"text": "あっという間に夏が終わった。", "target_word": "間", "complexity_tier": "T3", "furigana": "ま", "sentence_source": "generated"}, {"text": "知らない間に雨がやんでいた。", "target_word": "間", "complexity_tier": "T3", "furigana": "ま", "sentence_source": "generated"}, {"text": "間が悪くて言えなかった。", "target_word": "間", "complexity_tier": "T3", "furigana": "ま", "sentence_source": "generated"}, {"text": "彼は間を空けて話し始めた。", "target_word": "間", "complexity_tier": "T3", "furigana": "ま", "sentence_source": "generated"}, {"text": "間があいて、みんな笑った。", "target_word": "間", "complexity_tier": "T3", "furigana": "ま", "sentence_source": "generated"}], "morphological_forms": [{"form": "間合い", "label": "派生"}, {"form": "間取り", "label": "派生"}, {"form": "間もなく", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事の間の時間的・空間的隔たり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 瞬く (Zipf 3.21), 吸い込ま (Zipf 3.35), 網目 (Zipf 2.67)','sentence 1 above tier T1: contains vocabulary far above tier T1: 見て取れ (Zipf 2.23)']::text[], '65746631-d687-4201-9b73-f7c0f60d853b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53382, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "線や糸などが縦と横に交わってできた格子状の構造。また、その模様。", "primary_collocate": null, "pronunciation": "あみめ", "ipa": "amime", "syllable_count": 3, "sentences": [{"text": "水は瞬く間に闇色の大地へと吸い込まれ、やがて目に見えぬ根の網目へと伝わっていくだろう。", "target_word": "網目", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "その後、長時間にわたる低温発酵を経ることで、グルテンの網目は緻密さを増し、消化吸収にも優れた変容を遂げる。", "target_word": "網目", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "魚が網目から逃げてしまった。", "target_word": "網目", "complexity_tier": "T3", "furigana": "あみめ", "sentence_source": "generated"}, {"text": "このかごは網目が細かい。", "target_word": "網目", "complexity_tier": "T3", "furigana": "あみめ", "sentence_source": "generated"}, {"text": "網目の大きいネットを使う。", "target_word": "網目", "complexity_tier": "T3", "furigana": "あみめ", "sentence_source": "generated"}, {"text": "セーターの網目がほつれている。", "target_word": "網目", "complexity_tier": "T3", "furigana": "あみめ", "sentence_source": "generated"}, {"text": "網目模様のシャツを買った。", "target_word": "網目", "complexity_tier": "T3", "furigana": "あみめ", "sentence_source": "generated"}, {"text": "網目にごみが引っかかった。", "target_word": "網目", "complexity_tier": "T3", "furigana": "あみめ", "sentence_source": "generated"}, {"text": "網目を通して光が入る。", "target_word": "網目", "complexity_tier": "T3", "furigana": "あみめ", "sentence_source": "generated"}, {"text": "細い網目で小さな虫を防ぐ。", "target_word": "網目", "complexity_tier": "T3", "furigana": "あみめ", "sentence_source": "generated"}], "morphological_forms": [{"form": "網目模様", "label": "派生"}, {"form": "網目状", "label": "派生"}, {"form": "網", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 糸や線が交わる格子状の構造", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code: