INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36147, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "目に映る。視覚で認識できる状態にある。", "primary_collocate": null, "pronunciation": "みえる", "ipa": "mieɾɯ", "syllable_count": 3, "sentences": [{"text": "水は瞬く間に闇色の大地へと吸い込まれ、やがて目に見えぬ根の網目へと伝わっていくだろう。", "target_word": "見え", "complexity_tier": "T3", "furigana": "み", "sentence_source": "mined"}, {"text": "指先を通じて伝わる生地の微妙な弾力や発酵の進行具合を唯一の羅針盤とし、彼は温度と湿度という変数を緻密に制御することで、微生物という目に見えぬパートナーとの静かなる対話を試みる。", "target_word": "見え", "complexity_tier": "T3", "furigana": "み", "sentence_source": "mined"}, {"text": "窓から富士山がよく見える。", "target_word": "見える", "complexity_tier": "T3", "furigana": "まど ふじさん み", "sentence_source": "generated"}, {"text": "暗くて前が何も見えない。", "target_word": "見え", "complexity_tier": "T3", "furigana": "くら まえ なに み", "sentence_source": "generated"}, {"text": "遠くに小さな島が見えてきた。", "target_word": "見え", "complexity_tier": "T3", "furigana": "とお ちい しま み", "sentence_source": "generated"}, {"text": "ここから見える海はとてもきれいだ。", "target_word": "見える", "complexity_tier": "T3", "furigana": "み うみ", "sentence_source": "generated"}, {"text": "眼鏡をかけると字がはっきり見える。", "target_word": "見える", "complexity_tier": "T3", "furigana": "めがね じ み", "sentence_source": "generated"}, {"text": "霧で山の頂上が見えなかった。", "target_word": "見え", "complexity_tier": "T3", "furigana": "きり やま ちょうじょう み", "sentence_source": "generated"}, {"text": "星が見える夜に散歩した。", "target_word": "見える", "complexity_tier": "T3", "furigana": "ほし み よる さんぽ", "sentence_source": "generated"}, {"text": "教室の後ろからでも黒板が見えます。", "target_word": "見え", "complexity_tier": "T3", "furigana": "きょうしつ うし こくばん み", "sentence_source": "generated"}], "morphological_forms": [{"form": "見えた", "label": "活用"}, {"form": "見えて", "label": "活用"}, {"form": "見えない", "label": "活用"}, {"form": "見え方", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 物が目に映り視覚で認識できる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 瞬く (Zipf 3.21), 吸い込ま (Zipf 3.35), 網目 (Zipf 2.67)','sentence 1 above tier T1: 10 words above tier T1 (max 2): 指先 (Zipf 3.6), 生地 (Zipf 3.93), 弾力 (Zipf 3.23), 発酵 (Zipf 3.73), 羅針盤 (Zipf 3.09), 湿度 (Zipf 3.81)']::text[], '37890ce6-5c8d-466c-9024-e7b599e72d5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39227, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "植物の根を土の中に入れて、そこから成長させること。", "primary_collocate": null, "pronunciation": "うえる", "ipa": "ɯeɾɯ", "syllable_count": 3, "sentences": [{"text": "陽だまりの縁側にて、幼き童子は陶器の鉢に植えられた一株の植物へと、無心なる眼差しを注いでいる。", "target_word": "植え", "complexity_tier": "T3", "furigana": "う", "sentence_source": "mined"}, {"text": "経験豊富な農家は、広大な畑の土壌を丁寧に耕し、野菜の種を植える。", "target_word": "植える", "complexity_tier": "T3", "furigana": "う", "sentence_source": "mined"}, {"text": "春になったら庭に花を植えよう。", "target_word": "植え", "complexity_tier": "T3", "furigana": "はる にわ はな う", "sentence_source": "generated"}, {"text": "祖父と一緒に桜の木を植えた。", "target_word": "植え", "complexity_tier": "T3", "furigana": "そふ いっしょ さくら き う", "sentence_source": "generated"}, {"text": "学校の花壇にチューリップを植えている。", "target_word": "植え", "complexity_tier": "T3", "furigana": "がっこう かだん う", "sentence_source": "generated"}, {"text": "植えたばかりの苗に水をやる。", "target_word": "植え", "complexity_tier": "T3", "furigana": "う なえ みず", "sentence_source": "generated"}, {"text": "この木は十年前に父が植えたものだ。", "target_word": "植え", "complexity_tier": "T3", "furigana": "き じゅうねんまえ ちち う", "sentence_source": "generated"}, {"text": "トマトを植える時期はいつですか。", "target_word": "植える", "complexity_tier": "T3", "furigana": "う じき", "sentence_source": "generated"}, {"text": "道に沿って木が植えられている。", "target_word": "植え", "complexity_tier": "T3", "furigana": "みち そ き う", "sentence_source": "generated"}, {"text": "鉢に植えた種から芽が出た。", "target_word": "植え", "complexity_tier": "T3", "furigana": "はち う たね め で", "sentence_source": "generated"}], "morphological_forms": [{"form": "植えた", "label": "活用"}, {"form": "植えて", "label": "活用"}, {"form": "植えられる", "label": "活用"}, {"form": "植木", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 植物の根や種を土に入れて育てる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37890ce6-5c8d-466c-9024-e7b599e72d5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35159, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "情報や気持ち、振動などが、人や物の間を移って相手や先に届くこと。また、受け継がれること。", "primary_collocate": null, "pronunciation": "つたわる", "ipa": "tsɯtawaɾɯ", "syllable_count": 4, "sentences": [{"text": "水は瞬く間に闇色の大地へと吸い込まれ、やがて目に見えぬ根の網目へと伝わっていくだろう。", "target_word": "伝わっ", "complexity_tier": "T3", "furigana": "つた", "sentence_source": "mined"}, {"text": "指先を通じて伝わる生地の微妙な弾力や発酵の進行具合を唯一の羅針盤とし、彼は温度と湿度という変数を緻密に制御することで、微生物という目に見えぬパートナーとの静かなる対話を試みる。", "target_word": "伝わる", "complexity_tier": "T3", "furigana": "つた", "sentence_source": "mined"}, {"text": "彼の気持ちがみんなに伝わった。", "target_word": "伝わっ", "complexity_tier": "T3", "furigana": "かれ きも つた", "sentence_source": "generated"}, {"text": "このお祭りは昔から村に伝わっている。", "target_word": "伝わっ", "complexity_tier": "T3", "furigana": "まつ むかし むら つた", "sentence_source": "generated"}, {"text": "言いたいことがうまく伝わらない。", "target_word": "伝わ", "complexity_tier": "T3", "furigana": "い つた", "sentence_source": "generated"}, {"text": "ニュースはすぐに町中に伝わった。", "target_word": "伝わっ", "complexity_tier": "T3", "furigana": "まちじゅう つた", "sentence_source": "generated"}, {"text": "床から電車の振動が伝わってくる。", "target_word": "伝わっ", "complexity_tier": "T3", "furigana": "ゆか でんしゃ しんどう つた", "sentence_source": "generated"}, {"text": "音は空気を通して伝わる。", "target_word": "伝わる", "complexity_tier": "T3", "furigana": "おと くうき とお つた", "sentence_source": "generated"}, {"text": "先生の熱意が生徒に伝わる授業だった。", "target_word": "伝わる", "complexity_tier": "T3", "furigana": "せんせい ねつい せいと つた じゅぎょう", "sentence_source": "generated"}, {"text": "手紙で感謝が伝わるといいな。", "target_word": "伝わる", "complexity_tier": "T3", "furigana": "てがみ かんしゃ つた", "sentence_source": "generated"}], "morphological_forms": [{"form": "伝わった", "label": "活用"}, {"form": "伝わって", "label": "活用"}, {"form": "伝わらない", "label": "活用"}, {"form": "伝える", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 物事や気持ちが移って相手や先に届く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37890ce6-5c8d-466c-9024-e7b599e72d5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52568, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "気高くて立派で、普通の人の考えや行いよりもずっとすぐれていること。また、そのさま。", "primary_collocate": null, "pronunciation": "すうこう", "ipa": "sɯːkoː", "syllable_count": 4, "sentences": [{"text": "童子の行為は、単なる日常的な営みの模倣を超え、生命の循環に対する原初的な祈りにも似た、崇高な儀式としてそこに刻まれるのである。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "すうこう", "sentence_source": "mined"}, {"text": "この製作の全工程は、まさに宇宙の理を机の上に縮図として描き出す、崇高な知的探究なのである。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "すうこう", "sentence_source": "mined"}, {"text": "彼は人を助けるという崇高な目標を持っている。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "かれ ひと たす すうこう もくひょう も", "sentence_source": "generated"}, {"text": "夜明けの山は崇高な美しさに満ちていた。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "よあ やま すうこう うつく み", "sentence_source": "generated"}, {"text": "その医師の生き方は崇高だと思う。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "いし い かた すうこう おも", "sentence_source": "generated"}, {"text": "平和を願う崇高な気持ちを忘れない。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "へいわ ねが すうこう きも わす", "sentence_source": "generated"}, {"text": "音楽の崇高さに心を打たれた。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "おんがく すうこう こころ う", "sentence_source": "generated"}, {"text": "自分を犠牲にする姿は崇高に見えた。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "じぶん ぎせい すがた すうこう み", "sentence_source": "generated"}, {"text": "彼女の理想はとても崇高だ。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "かのじょ りそう すうこう", "sentence_source": "generated"}, {"text": "教育は崇高な仕事だと言われる。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "きょういく すうこう しごと い", "sentence_source": "generated"}], "morphological_forms": [{"form": "崇高な", "label": "活用"}, {"form": "崇高だ", "label": "活用"}, {"form": "崇高さ", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 気高く立派で尊いさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37890ce6-5c8d-466c-9024-e7b599e72d5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52066, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "日本の伝統的な家屋で、部屋と庭の間に設けられた細長い板敷きの廊下。", "primary_collocate": null, "pronunciation": "えんがわ", "ipa": "eŋɡawa", "syllable_count": 4, "sentences": [{"text": "陽だまりの縁側にて、幼き童子は陶器の鉢に植えられた一株の植物へと、無心なる眼差しを注いでいる。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "えんがわ", "sentence_source": "mined"}, {"text": "秋の気配が色濃く漂う古びた縁側にて、一人の幼子が無心なる眼差しを向けているのは、掌に収められた一つの赤い果物である。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "えんがわ", "sentence_source": "mined"}, {"text": "祖母は縁側でお茶を飲んでいる。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "そぼ えんがわ ちゃ の", "sentence_source": "generated"}, {"text": "夏は縁側に座ってスイカを食べた。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "なつ えんがわ すわ た", "sentence_source": "generated"}, {"text": "縁側から庭の花がよく見える。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "えんがわ にわ はな み", "sentence_source": "generated"}, {"text": "猫が縁側で昼寝をしている。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "ねこ えんがわ ひるね", "sentence_source": "generated"}, {"text": "この家には広い縁側がある。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "いえ ひろ えんがわ", "sentence_source": "generated"}, {"text": "雨の日は縁側で本を読む。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "あめ ひ えんがわ ほん よ", "sentence_source": "generated"}, {"text": "縁側の床をぞうきんでふいた。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "えんがわ ゆか", "sentence_source": "generated"}, {"text": "古い縁側に秋の日が差している。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "ふる えんがわ あき ひ さ", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 和室と庭の間の細長い板敷き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-co