INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52072, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を見るときの、目の表情や視線。", "primary_collocate": null, "pronunciation": "まなざし", "ipa": "manazaɕi", "syllable_count": 4, "sentences": [{"text": "陽だまりの縁側にて、幼き童子は陶器の鉢に植えられた一株の植物へと、無心なる眼差しを注いでいる。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "まなざ", "sentence_source": "mined"}, {"text": "秋の気配が色濃く漂う古びた縁側にて、一人の幼子が無心なる眼差しを向けているのは、掌に収められた一つの赤い果物である。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "まなざ", "sentence_source": "mined"}, {"text": "母はやさしい眼差しで子どもを見た。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "はは まなざ こ み", "sentence_source": "generated"}, {"text": "彼の真剣な眼差しに驚いた。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "かれ しんけん まなざ おどろ", "sentence_source": "generated"}, {"text": "観客は熱い眼差しを舞台に向けた。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "かんきゃく あつ まなざ ぶたい む", "sentence_source": "generated"}, {"text": "その眼差しには不安が見えた。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "まなざ ふあん み", "sentence_source": "generated"}, {"text": "先生の温かい眼差しがうれしかった。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "せんせい あたた まなざ", "sentence_source": "generated"}, {"text": "少年は空に眼差しを向けている。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "しょうねん そら まなざ む", "sentence_source": "generated"}, {"text": "冷たい眼差しを感じて振り返った。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "つめ まなざ かん ふ かえ", "sentence_source": "generated"}, {"text": "祖父の眼差しはいつも穏やかだ。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "そふ まなざ おだ", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 物を見るときの目の表情や視線", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37890ce6-5c8d-466c-9024-e7b599e72d5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36147, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "見える", "is_correct": true, "explanation": "正解：「みえる」と読む対象語。"}, {"text": "消える", "is_correct": false, "explanation": "「きえる」と読む。一モーラ目「み」が「き」に変わる。"}, {"text": "冷える", "is_correct": false, "explanation": "「ひえる」と読む。一モーラ目「み」が「ひ」に変わる。"}, {"text": "見せる", "is_correct": false, "explanation": "「みせる」と読む。二モーラ目「え」が「せ」に変わる。"}, {"text": "生える", "is_correct": false, "explanation": "「はえる」と読む。一モーラ目「み」が「は」に変わる。"}], "explanations": {"見える": "正解：「みえる」と読む対象語。", "消える": "「きえる」と読む。一モーラ目「み」が「き」に変わる。", "冷える": "「ひえる」と読む。一モーラ目「み」が「ひ」に変わる。", "見せる": "「みせる」と読む。二モーラ目「え」が「せ」に変わる。", "生える": "「はえる」と読む。一モーラ目「み」が「は」に変わる。"}, "sentence_index": null, "correct_answer": "見える"}, "level_3": {"options": [{"text": "見え", "is_correct": true, "explanation": "目で認識できないという意味で「目に見えぬ」となる。"}, {"text": "聞こえ", "is_correct": false, "explanation": "連語：「目に聞こえぬ」とは言わない。聞こえるのは耳である。"}, {"text": "生え", "is_correct": false, "explanation": "意味：根の網目が目に生えるのではない。"}, {"text": "冷え", "is_correct": false, "explanation": "意味：「目に冷えぬ」は意味をなさない。"}], "explanations": {"見え": "目で認識できないという意味で「目に見えぬ」となる。", "聞こえ": "連語：「目に聞こえぬ」とは言わない。聞こえるのは耳である。", "生え": "意味：根の網目が目に生えるのではない。", "冷え": "意味：「目に冷えぬ」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "見え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "暗くて前を何も見えない。", "explanation": "助詞の混同：「見える」は自動詞なので対象は「が」で示す。"}, {"text": "暗くて前が何も見えている。", "explanation": "呼応の誤り：「何も」は否定と呼応するので「見えない」が必要。"}, {"text": "前が暗くて何も見えないだった。", "explanation": "活用の誤り：「見えない」に「だった」は付かない。「見えなかった」とする。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36147, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓から富士山をよく見える。", "corrected_sentence": "窓から富士山がよく見える。", "error_description": "「見える」は自動詞なので、見える対象は「を」ではなく「が」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "見え", "is_correct": true, "explanation": "打消の「ぬ」は未然形「見え」に付く。"}, {"text": "見える", "is_correct": false, "explanation": "辞書形には「ぬ」が付かない。"}, {"text": "見えた", "is_correct": false, "explanation": "た形の後に「ぬ」は続かない。"}, {"text": "見えて", "is_correct": false, "explanation": "て形の後に「ぬ」は続かない。"}], "correct_form": "見え", "base_form": "見える", "form_label": "未然形（ぬ接続）", "sentence_index": 1, "explanations": {"見え": "打消の「ぬ」は未然形「見え」に付く。", "見える": "辞書形には「ぬ」が付かない。", "見えた": "た形の後に「ぬ」は続かない。", "見えて": "て形の後に「ぬ」は続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36147, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「試みる」の目的語「対話」を示す。"}, {"text": "が", "is_correct": false, "explanation": "「対話が試みる」では対話が主語になり意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「試みる」は「に」で対象を取らない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表し、ここでは非文になる。"}], "correct_answer": "を", "explanations": {"を": "他動詞「試みる」の目的語「対話」を示す。", "が": "「対話が試みる」では対話が主語になり意味が通らない。", "に": "「試みる」は「に」で対象を取らない。", "で": "手段や場所を表し、ここでは非文になる。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36147, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "見える", "is_correct": true, "explanation": "正解：「みえる」と読む対象語。"}, {"text": "燃える", "is_correct": false, "explanation": "「もえる」と読む。一モーラ目「み」が「も」に変わる。"}, {"text": "吠える", "is_correct": false, "explanation": "「ほえる」と読む。一モーラ目「み」が「ほ」に変わる。"}, {"text": "増える", "is_correct": false, "explanation": "「ふえる」と読む。一モーラ目「み」が「ふ」に変わる。"}, {"text": "見せる", "is_correct": false, "explanation": "「みせる」と読む。二モーラ目「え」が「せ」に変わる。"}], "explanations": {"見える": "正解：「みえる」と読む対象語。", "燃える": "「もえる」と読む。一モーラ目「み」が「も」に変わる。", "吠える": "「ほえる」と読む。一モーラ目「み」が「ほ」に変わる。", "増える": "「ふえる」と読む。一モーラ目「み」が「ふ」に変わる。", "見せる": "「みせる」と読む。二モーラ目「え」が「せ」に変わる。"}, "sentence_index": null, "correct_answer": "見える"}, "level_3": {"options": [{"text": "見える", "is_correct": true, "explanation": "眼鏡で字が目にはっきり映るので「見える」。"}, {"text": "聞こえる", "is_correct": false, "explanation": "連語：字は耳で聞くものではない。"}, {"text": "消える", "is_correct": false, "explanation": "意味：眼鏡をかけて字が消えるのは不自然。"}, {"text": "増える", "is_correct": false, "explanation": "意味：眼鏡で字の数が増えることはない。"}], "explanations": {"見える": "眼鏡で字が目にはっきり映るので「見える」。", "聞こえる": "連語：字は耳で聞くものではない。", "消える": "意味：眼鏡をかけて字が消えるのは不自然。", "増える": "意味：眼鏡で字の数が増えることはない。"}, "sentence_index": 6, "correct_answer": "見える"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室の後ろからでも黒板を見えます。", "explanation": "助詞の混同：自動詞「見える」の対象は「が」で示す。"}, {"text": "教室の後ろからでも黒板が見えてあります。", "explanation": "アスペクトの誤り：「てある」は他動詞に付く形で、「見える」には使えない。"}, {"text": "黒板が教室の後ろからでも見えますでした。", "explanation": "活用の誤り：「見えます」の過去は「見えました」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36147, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "霧で山の頂上を見えなかった。", "corrected_sentence": "霧で山の頂上が見えなかった。", "error_description": "自動詞「見える」の主語は「を」ではなく「が」で示す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "見え", "is_correct": true, "explanation": "否定の「なかった」は未然形「見え」に付く。"}, {"text": "見えろ", "is_correct": false, "explanation": "命令形の後に「なかった」は続かない。"}, {"text": "見えよう", "is_correct": false, "explanation": "意向形の後に「なかった」は続かない。"}, {"text": "見えれば", "is_correct": false, "explanation": "仮定形の後に「なかった」は続かない。"}], "correct_form": "見え", "base_form": "見える", "form_label": "未然形（ない接続）", "sentence_index": 7, "explanations": {"見え": "否定の「なかった」は未然形「見え」に付く。", "見えろ": "命令形の後に「なかった」は続かない。", "見えよう": "意向形の後に「なかった」は続かない。", "見えれば": "仮定形の後に「なかった」は続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36147, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "自動詞「見える」の主語（見える物）を示す。"}, {"text": "を", "is_correct": false, "explanation": "「見える」は自動詞なので「を」は取れない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、見える対象を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「頂上に見えなかった」は見える物を示さず不自然。"}], "correct_answer": "が", "explanations": {"が": "自動詞「見える」の主語（見える物）を示す。", "を": "「見える」は自動詞なので「を」は取れない。", "へ": "方向を表し、見える対象を示せない。", "に": "「頂上に見えなかった」は見える物を示さず不自然。"}, "error_tags": {"を": "object_marking", "へ": "direction", "に": "location_vs_target"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39227, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "植える", "is_correct": true, "explanation": "正解：「うえる」と読む対象語。"}, {"text": "終える", "is_correct": false, "explanation": "「おえる」と読む。一モーラ目「う」が「お」に変わる。"}, {"text": "受ける", "is_correct": false, "explanation": "「うける」と読む。二モーラ目「え」が「け」に変わる。"}, {"text": "埋める", "is_correct": false, "explanation": "「うめる」と読む。二モーラ目「え」が「め」に変わる。"}, {"text": "消える", "is_correct": false, "explanation": "「きえる」と読む。一モーラ目「う」が「き」に変わる。"}], "explanations": {"植える": "正解：「うえる」と読む対象語。", "終える": "「おえる」と読む。一モーラ目「う」が「お」に変わる。", "受ける": "「うける」と読む。二モーラ目「え」が「け」に変わる。", "埋める": "「うめる」と読む。二モーラ目「え」が「め」に変わる。", "消える": "「きえる」と読む。一モーラ目「う」が「き」に変わる。"}, "sentence_index": null, "correct_answer": "植える"}, "level_3": {"options": [{"text": "植え", "is_correct": true, "explanation": "植物を鉢の土に入れたので「植えられた」。"}, {"text": "食べ", "is_correct": false, "explanation": "意味：鉢に食べられた植物は不自然。"}, {"text": "教え", "is_correct": false, "explanation": "項構造：植物は「教えられる」対象にならない。"}, {"text": "建て", "is_correct": false, "explanation": "連語：「建てる」は建物に使い、植物には使わない。"}], "explanations": {"植え": "植物を鉢の土に入れたので「植えられた」。", "食べ": "意味：鉢に食べられた植物は不自然。", "教え": "項構造：植物は「教えられる」対象にならない。", "建て": "連語：「建てる」は建物に使い、植物には使わない。"}, "sentence_index": 0, "correct_answer": "植え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父と一緒に桜の木が植えた。", "explanation": "助詞の混同：他動詞「植える」の対象は「を」で示す。"}, {"text": "祖父と一緒に桜の木を植えるた。", "explanation": "活用の誤り：過去形は「植えた」で、辞書形に「た」は付かない。"}, {"text": "一冊の桜の木を祖父と一緒に植えた。", "explanation": "助数詞の誤り：木は「冊」ではなく「本」で数える。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39227, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春になったら庭が花を植えよう。", "corrected_sentence": "春になったら庭に花を植えよう。", "error_description": "植える場所は「が」ではなく「に」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "植える", "is_correct": true, "explanation": "文末で習慣的な行為を述べる辞書形。"}, {"text": "植えて", "is_correct": false, "explanation": "て形では文が終わらない。"}, {"text": "植えれば", "is_correct": false, "explanation": "仮定形では文が完結しない。"}, {"text": "植えろ", "is_correct": false, "explanation": "命令形は農家の行為の描写に合わない。"}], "correct_form": "植える", "base_form": "植える", "form_label": "辞書形（終止形）", "sentence_index": 1, "explanations": {"植える": "文末で習慣的な行為を述べる辞書形。", "植えて": "て形では文が終わらない。", "植えれば": "仮定形では文が完結しない。", "植えろ": "命令形は農家の行為の描写に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
